// The Agents page's Delegate controls (Pair and Delegate plan, UI r3.2 §2; UI-3), drawn from delegate.ts's model:
//   - the switch in the header ("Delegate: on/off"): on after the person confirms what it allows; off with a
//     confirmation that may also close the running tasks for good (unticked), sent first; the page's task actions
//     disabled from the moment it starts turning off;
//   - Delegate… beside Send: a sheet with the task (the composer's text), its title, the documents (the file open in the
//     pane, editable), where it runs (this computer), and May run code (only if the grant may, frozen at Start);
//   - the Tasks list under the chats, each with its chip;
//   - a task's view in place of the chat: its status, its thread (the agent's turns), and its proposal's card, which
//     opens the proposal view (the review chunk's) in a dialog. Merge, Close and Ask for changes come with UI-4.
// Shown only for an agent on this computer whose hello offers delegate.1: nothing changes for any other.
import type { Thread, Turn } from "../workspace/agent-chat/events";
import { AgentError } from "../workspace/agent-pair";
import { chipOf, type DelegateDoc, type DelegateTasks } from "./delegate";

export const DELEGATE_UI_TEXT = {
  switchOn: "Delegate: on",
  switchOff: "Delegate: off",
  switchTurning: "Delegate: turning off…",
  onTitle: "Allow Delegate tasks on this computer?",
  onBody: (agent: string) => `${agent} works on its own copy of the documents you choose, on this computer, and proposes the changes back to you. Turning this on lets this page start tasks, and read every existing Delegate task of this agent installation. You can turn it off at any time.`,
  offTitle: "Turn off Delegate tasks?",
  offBody: "This page will no longer start or read tasks. Running turns stop; your tasks stay available.",
  alsoClose: (n: number) => `Also close ${n === 1 ? "my running task" : `my ${n} running tasks`} for good`,
  closeFailed: (n: number) => `Delegate is off. ${n === 1 ? "One task" : `${n} tasks`} couldn't be closed.`,
  sheetTitle: "Delegate a task",
  where: "This computer",
  whereNote: "The task's copy and its runs stay on this computer.",
  run: "May run code",
  runNote: "Fixed for this task once it starts.",
  runNotGranted: "Your grant to this agent doesn't allow running code.",
  noDocs: "No documents: add a path, or open a file in the pane first.",
  start: "Start",
  starting: "Starting…",
  tasks: "Tasks",
  skipped: (n: number) => (n === 1 ? "One event of this task couldn't be shown here." : `${n} events of this task couldn't be shown here.`),
  proposal: (n: number, base: string, commit: string) => `Proposal: ${n === 1 ? "1 file" : `${n} files`} changed · base ${base.slice(0, 7)} · proposal ${commit.slice(0, 7)}`,
  laterActions: "Merge, Close and Ask for changes come in a later update.",
  unreadable: "Couldn't read this task from the agent.",
  back: "← Back to chats",
} as const;

const el = <K extends keyof HTMLElementTagNameMap>(tag: K, props: Record<string, unknown> = {}, ...kids: (Node | string)[]): HTMLElementTagNameMap[K] => {
  const e = Object.assign(document.createElement(tag), props);
  e.append(...kids);
  return e;
};

export type DelegateHost = {
  tasks: DelegateTasks;
  agent: () => string;
  mayRun: () => boolean;
  openPath: () => string | null;
  draft: () => string;
  clearDraft: () => void;
  readDoc: (path: string) => Promise<DelegateDoc>;
  turnNode: (thread: Thread, turn: Turn) => HTMLElement;
  /** the task view shown (true) or gone (false): the page hides or shows its chat */
  shown: (on: boolean) => void;
  site: URL;
  toast: (text: string, ms?: number) => void;
};

export function mountDelegate(h: DelegateHost) {
  const T = DELEGATE_UI_TEXT, D = h.tasks;
  let open: string | null = null, readErr = false;

  // (the switch, in the header; Delegate…, beside Send; the Tasks list, under the chats; the task's view, in place of
  //  the chat)
  const sw = el("button", { id: "delegate-switch", className: "link", hidden: true, type: "button" });
  document.querySelector("#connect")?.before(sw);
  const btn = el("button", { id: "delegate", hidden: true, type: "button", title: "Give the agent a task to work on by itself, on its own copy" }, "Delegate…");
  document.querySelector("#send")?.before(btn);
  const list = el("div", { className: "list" });
  const side = el("div", { id: "tasks", hidden: true }, el("div", { className: "tasks-h" }, T.tasks), list);
  document.querySelector("#threads")?.after(side);
  const view = el("section", { id: "task-view", hidden: true, ariaLabel: "Task" });
  document.querySelector("main .composer-wrap")?.before(view);

  function confirmDialog(title: string, body: string, ok: string, extra?: HTMLElement): Promise<boolean> {
    const dlg = el("dialog", { className: "delegate-dlg" });
    const form = el("form", { method: "dialog" },
      el("h3", { textContent: title }), el("p", { textContent: body }), ...(extra ? [extra] : []),
      el("menu", {}, el("button", { value: "cancel", textContent: "Cancel" }), " ", el("button", { value: "ok", className: "primary", textContent: ok })));
    dlg.append(form);
    document.body.append(dlg);
    dlg.showModal();
    return new Promise((resolve) => dlg.addEventListener("close", () => { resolve(dlg.returnValue === "ok"); dlg.remove(); }, { once: true }));
  }

  async function switchOn(): Promise<boolean> {
    if (D.state() !== "off") return D.state() === "on";
    if (!(await confirmDialog(T.onTitle, T.onBody(h.agent()), "Turn on"))) return false;
    return D.turnOn();
  }
  async function switchOff() {
    if (D.state() !== "on") return;
    const running = D.tasks.filter((t) => t.entry.status === "working");
    const box = el("input", { type: "checkbox", id: "delegate-also-close" });
    const extra = running.length
      ? el("div", { className: "also" }, el("label", {}, box, " ", T.alsoClose(running.length)), el("ul", {}, ...running.map((t) => el("li", { textContent: t.entry.title }))))
      : undefined;
    if (!(await confirmDialog(T.offTitle, T.offBody, "Turn off", extra))) return;
    // (from here the page's task actions are off: Delegate…, Start; the chosen tasks are closed first, then the switch)
    const failed = await D.turnOff(box.checked ? running.map((t) => t.entry.task) : []);
    if (failed.length) h.toast(T.closeFailed(failed.length), 6000);
    close();
  }
  sw.onclick = () => void (D.state() === "on" ? switchOff() : D.state() === "off" ? switchOn().then(() => render()) : undefined);

  // ---- the sheet
  btn.onclick = async () => {
    if (btn.getAttribute("aria-disabled") === "true") return;
    if (!(await switchOn())) return;
    sheet();
  };
  function sheet() {
    const prompt = el("textarea", { id: "delegate-prompt", rows: 5, value: h.draft(), required: true, maxLength: 64 * 1024 });
    const firstLine = h.draft().trim().split("\n")[0] ?? "";
    const title = el("input", { id: "delegate-title", value: firstLine.slice(0, 80), maxLength: 200, required: true });
    const docs = el("ul", { className: "docs" });
    const addDoc = (p: string) => {
      p = p.trim().replace(/^\/+/, "");
      if (!p || [...docs.querySelectorAll("li")].some((li) => li.dataset.path === p)) return;
      const x = el("button", { type: "button", className: "icon", title: "Remove", textContent: "×" });
      const li = el("li", {}, el("code", { textContent: p }), " ", x);
      li.dataset.path = p;
      x.onclick = () => li.remove();
      docs.append(li);
    };
    const here = h.openPath();
    if (here) addDoc(here);
    const more = el("input", { id: "delegate-add", placeholder: "Add a path, e.g. work/notes.ipynb" });
    more.onkeydown = (e) => { if (e.key === "Enter") { e.preventDefault(); addDoc(more.value); more.value = ""; } };
    const run = el("input", { type: "checkbox", id: "delegate-run", disabled: !h.mayRun() });
    const msg = el("p", { className: "msg", role: "alert" });
    const start = el("button", { type: "submit", className: "primary", textContent: T.start });
    const dlg = el("dialog", { className: "delegate-dlg sheet", ariaLabel: T.sheetTitle });
    const form = el("form", {},
      el("h3", { textContent: T.sheetTitle }),
      el("label", {}, "Task", prompt),
      el("label", {}, "Title", title),
      el("div", { className: "field" }, el("span", {}, "Documents"), docs, more),
      el("div", { className: "field" }, el("span", {}, "Where"), el("label", {}, el("input", { type: "radio", checked: true, name: "where" }), " ", T.where), el("small", { textContent: T.whereNote })),
      el("div", { className: "field" }, el("label", {}, run, " ", T.run), el("small", { textContent: h.mayRun() ? T.runNote : T.runNotGranted })),
      msg,
      el("menu", {}, el("button", { type: "button", value: "cancel", textContent: "Cancel", onclick: () => dlg.close() }), " ", start));
    dlg.append(form);
    document.body.append(dlg);
    dlg.addEventListener("close", () => dlg.remove(), { once: true });
    dlg.showModal();
    form.onsubmit = async (e) => {
      e.preventDefault();
      if (more.value.trim()) { addDoc(more.value); more.value = ""; }
      const paths = [...docs.querySelectorAll("li")].map((li) => li.dataset.path!);
      if (D.state() !== "on") { msg.textContent = D.state() === "turning-off" ? "Delegate is turning off." : "Delegate is off."; return; }
      if (!prompt.value.trim() || !title.value.trim()) { msg.textContent = "Say what the task is, and give it a title."; return; }
      if (!paths.length) { msg.textContent = T.noDocs; return; }
      start.textContent = T.starting;
      start.setAttribute("aria-disabled", "true");
      try {
        const read = await Promise.all(paths.map((p) => h.readDoc(p)));
        const id = await D.start({ title: title.value.trim(), prompt: prompt.value, docs: read, run: run.checked });
        h.clearDraft();
        dlg.close();
        show(id);
      } catch (err) {
        msg.textContent = err instanceof AgentError || err instanceof Error ? `Couldn't start the task: ${err.message}` : "Couldn't start the task.";
      } finally {
        start.textContent = T.start;
        start.removeAttribute("aria-disabled");
      }
    };
  }

  // ---- a task's view
  function show(id: string) {
    open = id;
    readErr = false;
    h.shown(true);
    render();
    void D.open(id).then(() => render(), () => { readErr = true; render(); });
  }
  function close() {
    if (open === null) return;
    open = null;
    view.hidden = true;
    h.shown(false);
    render();
  }
  async function openProposal(id: string, commit: string) {
    const dlg = el("dialog", { className: "delegate-dlg proposal" });
    const panel = el("div");
    dlg.append(el("button", { type: "button", className: "x", ariaLabel: "Close", textContent: "×", onclick: () => dlg.close() }), panel);
    document.body.append(dlg);
    dlg.showModal();
    let pv: { close(): void } | null = null;
    dlg.addEventListener("close", () => { pv?.close(); dlg.remove(); }, { once: true });
    const mod = (await import(new URL("sagebrush-review.js", h.site).href)) as typeof import("../workspace/review/review-page");
    if (!dlg.isConnected) return;
    const actions = el("p", { className: "st", textContent: T.laterActions });
    pv = mod.openProposal(D.source(id, commit), panel, { notebook: () => import(new URL("sagebrush-notebook.js", h.site).href), actions });
  }

  function render() {
    const s = D.state(), offered = s !== "unoffered";
    sw.hidden = !offered;
    sw.textContent = s === "on" ? T.switchOn : s === "turning-off" ? T.switchTurning : T.switchOff;
    sw.setAttribute("aria-pressed", String(s === "on"));
    btn.hidden = !offered;
    s === "turning-off" ? btn.setAttribute("aria-disabled", "true") : btn.removeAttribute("aria-disabled");
    side.hidden = !(s === "on" || s === "turning-off") || !D.tasks.length;
    list.replaceChildren(...D.tasks.map((t) => {
      const b = el("button", { type: "button", className: "thread task" + (t.entry.task === open ? " on" : "") }, el("span", { className: "t", textContent: t.entry.title }), el("span", { className: `chip ${t.entry.status}${t.entry.question ? " question" : ""}`, textContent: chipOf(t.entry) }));
      b.dataset.task = t.entry.task;
      b.onclick = () => show(t.entry.task);
      return b;
    }));
    const t = open ? D.task(open) : undefined;
    if (!t) {
      if (open !== null && s !== "on" && s !== "turning-off") close();
      view.hidden = true;
      return;
    }
    view.hidden = false;
    const back = el("button", { type: "button", className: "link", textContent: T.back, onclick: () => close() });
    const head = el("div", { className: "task-head" }, back, el("h2", { textContent: t.entry.title }), el("span", { className: `chip ${t.entry.status}`, textContent: chipOf(t.entry) }));
    const parts: Node[] = [head];
    if (t.reason) parts.push(el("p", { className: "reason", textContent: t.reason }));
    if (readErr) parts.push(el("p", { className: "msg", role: "alert", textContent: T.unreadable }));
    for (const e of t.thread.entries) if (e.kind === "turn") parts.push(h.turnNode(t.thread, e));
    if (t.skipped) parts.push(el("p", { className: "skipped", textContent: T.skipped(t.skipped) }));
    const p = t.proposal;
    if (p) {
      const card = el("button", { type: "button", className: "proposal-card", textContent: T.proposal(p.files.length, p.base, p.commit) });
      card.onclick = () => void openProposal(t.entry.task, p.commit);
      parts.push(card);
    }
    view.replaceChildren(...parts);
  }

  return { render, close, showing: () => open };
}

// The Agents page's Delegate tasks (Pair and Delegate plan, UI r3.2 §2, UI-3): the tasks of the paired agent's
// installation, each with its status and its chat thread, read from the agent (design/workspace-agent-protocol.md §6,
// `delegate.1`); Start; the Delegate switch's off; and a proposal's files for the proposal view. No DOM here: the page
// (page.ts) draws it.
//
// - Nothing about a task is kept on the page: the list comes from tasks.list on every connect and switch-on, a task's
//   thread from tasks.get (paged by `after`) when it is opened, and both move on with task.event while connected. A
//   task's chip moves only forward (chip()): an event or answer older than what the page has never moves it back.
// - Every answer and event is checked first (tasks-schema.ts). One event this page refuses is skipped and counted
//   (`skipped`), and the rest of the thread still shows.
// - A task's chat turn events go into an ordinary chat thread (agent-chat/events.ts apply), numbered by the task's seq.
//   Its task_status and proposal events move its chip and its proposal.
// - The switch's off (§6.2; UI r3.2 §11): from its first moment Start is refused here, nothing sent; the tasks the
//   person chose to close are revoked first (each failure or timeout only reported); then the grant goes without
//   `delegate`, always, whatever happened to those.
// - A proposal's files (ProposalSource): only the proposal commit named and its base, each file's bytes checked against
//   the blob id tasks.diff gave for that path at that commit (its git blob id, recomputed here).
import { AgentError, type AgentPairing } from "../workspace/agent-pair";
import { DELEGATE_FEATURE, TaskClient } from "../workspace/tasks-client";
import { TASK_RESULTS, blobId, contentBytes, taskLog, taskNotice, type DiffFile, type TaskEntry, type TaskEvent, type TaskLogEntry } from "../workspace/tasks-schema";
import { apply, newThread, type Thread, type TurnEvent } from "../workspace/agent-chat/events";
import type { ProposalDiff, ProposalSource } from "../workspace/review/proposal-view";

export type DelegateState = "unoffered" | "off" | "turning-off" | "on";
export type DelegateDoc = { path: string; kind: "notebook" | "file"; content: string };
export type DelegateTask = {
  entry: TaskEntry;
  /** its chat turn events, as a chat thread; `applied_seq` is the task's seq of the last event taken */
  thread: Thread;
  proposal: { round: number; base: string; commit: string; files: DiffFile[] } | null;
  /** the last task_status's reason, if it gave one */
  reason?: string;
  /** events this page refused, skipped */
  skipped: number;
  /** whether its thread has been read from the agent (tasks.get); until then only its chip moves */
  loaded: boolean;
  // (the turn its next untagged turn event belongs to: the agent records them without turn_id)
  turn: string | null;
};

export const DELEGATE_LIMITS = Object.freeze({ pages: 1000, closing: 4, closeMs: 10_000 });

export const DELEGATE_TEXT = {
  chip: { working: "Working", question: "Question", proposal: "Proposal ready", merged: "Merged", closed: "Closed", failed: "Failed", interrupted: "Interrupted" } as Record<string, string>,
  turningOff: "Delegate is turning off",
  off: "Delegate tasks aren't turned on for this agent",
  changed: "The proposal changed while you were reading it",
  binary: "This file isn't text",
  notThis: "That file isn't part of this proposal",
} as const;

/** A task's chip: its status, or Question while it works waiting for an answer. */
export const chipOf = (e: TaskEntry) => DELEGATE_TEXT.chip[e.status === "working" && e.question ? "question" : e.status];

export class DelegateTasks {
  /** the tasks, newest first */
  tasks: DelegateTask[] = [];
  private p: AgentPairing | null = null;
  private off = false;
  private unlisten: (() => void)[] = [];
  private wasOn = false;
  private loading = new Map<string, Promise<void>>();

  constructor(private o: { changed: () => void; closeMs?: number }) {}

  /** Follow this pairing (or none): its switch, and its task.event notifications. */
  attach(p: AgentPairing | null) {
    for (const u of this.unlisten.splice(0)) u();
    this.p = p;
    this.tasks = [];
    this.wasOn = false;
    if (p) {
      this.unlisten.push(p.onChange(() => this.moved()));
      this.unlisten.push(p.onNotification((method, params) => { if (method === "task.event") this.heard(params); }));
    }
    this.moved();
  }

  state(): DelegateState {
    const p = this.p;
    if (!p || p.state !== "granted" || p.link || !p.hello?.features?.includes(DELEGATE_FEATURE)) return "unoffered";
    if (this.off) return "turning-off";
    return p.grant?.delegate === true ? "on" : "off";
  }

  task(id: string) { return this.tasks.find((t) => t.entry.task === id); }

  // (the pairing moved: a switch turned on reads the list; without the switch, no tasks are shown)
  private moved() {
    const on = this.state() === "on";
    if (on && !this.wasOn) void this.refresh().catch(() => {});
    if (!on && this.state() !== "turning-off" && this.tasks.length) this.tasks = [];
    this.wasOn = on;
    this.o.changed();
  }

  private client(): TaskClient {
    if (!this.p) throw new AgentError("closed", "the agent isn't connected");
    return TaskClient.of(this.p);
  }

  /** The list, from tasks.list: each task's entry, its thread kept (and read further if it is open and moved on). */
  async refresh() {
    const p = this.p;
    const { tasks } = TASK_RESULTS["tasks.list"](await this.client().request("tasks.list", {}));
    if (p !== this.p || this.state() !== "on") return;
    const next: DelegateTask[] = [];
    for (const entry of tasks) {
      const t = this.task(entry.task);
      if (t) {
        // (an answer older than what this page has (a task.event came after it was made) never moves a task back: chip())
        chip(t, entry.seq, entry);
        if (t.loaded && entry.seq > t.thread.applied_seq) void this.open(entry.task).catch(() => {});
        next.push(t);
      } else next.push(fresh(entry));
    }
    this.tasks = next.sort((a, b) => b.entry.updated - a.entry.updated);
    this.o.changed();
  }

  /** A task's thread read from the agent: tasks.get from what this page has, page by page, until its seq. */
  open(id: string): Promise<void> {
    const held = this.loading.get(id);
    if (held) return held;
    const run = (async () => {
      const p = this.p;
      for (let page = 0; page < DELEGATE_LIMITS.pages; page++) {
        const t = this.task(id);
        if (!t) return;
        const r = taskLog(await this.client().request("tasks.get", { task: id, after: t.thread.applied_seq }));
        if (p !== this.p || this.task(id) !== t) return;
        if (r.task.task !== id) throw new AgentError("bad_request", "the agent answered for another task");
        let cur = t;
        if (r.reset) {
          // (the agent doesn't know where this page was: read again from the start)
          cur = fresh(r.task);
          this.tasks = this.tasks.map((x) => (x === t ? cur : x));
        }
        for (const e of r.events) if (!take(cur, e)) break;
        // (the same rule for tasks.get's entry, unless the log was read again from its start)
        if (cur === t) chip(cur, r.task.seq, r.task);
        cur.loaded = true;
        this.o.changed();
        if (r.last >= r.task.seq || !r.events.length) return;
      }
    })();
    this.loading.set(id, run);
    return run.finally(() => this.loading.delete(id));
  }

  // (a task.event: an open task's thread takes it in order (a gap reads the log again); a task not open moves its chip
  //  only; a task not listed yet reads the list)
  private heard(params: unknown) {
    if (this.state() !== "on") return;
    let n: { task: string } & TaskLogEntry;
    try { n = taskNotice(params); } catch { return; }
    const t = this.task(n.task);
    if (!t) { void this.refresh().catch(() => {}); return; }
    if (!t.loaded) {
      if ("event" in n) chipOfEvent(t, n.event, n.seq);
      this.o.changed();
      return;
    }
    if (!take(t, n)) void this.open(n.task).catch(() => {});
    this.o.changed();
  }

  /** Start a task (tasks.start): only with the switch on, never while it turns off. */
  async start(o: { title: string; prompt: string; docs: DelegateDoc[]; run: boolean }): Promise<string> {
    const s = this.state();
    if (s !== "on") throw new AgentError("forbidden", s === "turning-off" ? DELEGATE_TEXT.turningOff : DELEGATE_TEXT.off);
    const r = TASK_RESULTS["tasks.start"](await this.client().request("tasks.start", { title: o.title, prompt: o.prompt, target: "local", run: o.run, docs: o.docs }));
    await this.refresh().catch(() => {});
    return r.task;
  }

  /** The switch turned on (AgentPairing.setDelegate). */
  turnOn(): boolean { return !!this.p && this.state() === "off" && this.p.setDelegate(true); }

  /** The switch turned off: the tasks in `close` revoked first (closed for good), a few at a time, each failure or
   * timeout only reported (the ids returned); then the capability revoked, always. */
  async turnOff(close: string[]): Promise<string[]> {
    const p = this.p;
    if (!p || this.off) return [];
    this.off = true;
    this.o.changed();
    const failed: string[] = [];
    try {
      const left = [...close];
      const one = async () => {
        for (let id = left.shift(); id !== undefined; id = left.shift()) {
          try { TASK_RESULTS["tasks.revoke"](await TaskClient.of(p).request("tasks.revoke", { task: id }, { timeoutMs: this.o.closeMs ?? DELEGATE_LIMITS.closeMs })); } catch { failed.push(id); }
        }
      };
      await Promise.all(Array.from({ length: Math.min(DELEGATE_LIMITS.closing, left.length) }, one));
    } finally {
      p.setDelegate(false);
      this.off = false;
      if (p === this.p) this.tasks = [];
      this.moved();
    }
    return failed;
  }

  /** A proposal's files, for the proposal view: `commit` and its base only, each file checked against its blob id. */
  source(id: string, commit: string): ProposalSource {
    let diff: { base: string; commit: string; files: DiffFile[] } | null = null;
    return {
      diff: async (): Promise<ProposalDiff> => {
        const d = TASK_RESULTS["tasks.diff"](await this.client().request("tasks.diff", { task: id, commit }));
        if (d.task !== id || d.commit !== commit) throw new AgentError("bad_request", "the agent answered for another proposal");
        diff = d;
        return { base: d.base, proposal: d.commit, round: d.round, seq: d.seq, files: d.files.map((f) => ({ path: f.path, kind: f.kind, change: f.change })) };
      },
      file: async (path: string, at: string): Promise<string | null> => {
        const f = diff?.files.find((x) => x.path === path);
        const want = !diff || !f ? undefined : at === diff.commit ? f.blob : at === diff.base ? f.base_blob : undefined;
        if (want === undefined) throw new AgentError("bad_request", DELEGATE_TEXT.notThis);
        if (want === null) return null;
        const r = TASK_RESULTS["tasks.file"](await this.client().request("tasks.file", { task: id, commit: at, path }));
        const bytes = contentBytes(r.content);
        if (r.blob !== want || (await blobId(bytes)) !== want) throw new AgentError("stale", DELEGATE_TEXT.changed);
        if (typeof r.content === "string") return r.content;
        try { return new TextDecoder("utf-8", { fatal: true }).decode(bytes); } catch { throw new AgentError("bad_request", DELEGATE_TEXT.binary); }
      },
    };
  }
}

function fresh(entry: TaskEntry): DelegateTask {
  return { entry: { ...entry }, thread: newThread("task:" + entry.task, entry.title), proposal: null, skipped: 0, loaded: false, turn: null };
}

// (a task's chip, its entry, moves only forward: one rule for its events, tasks.list and tasks.get. The entry's seq is
//  the seq of what the chip says. Above it, `next` replaces the status and the rest; at it, only what is missing is
//  filled in; below it, the chip doesn't change. A status's reason and a proposal's files are filled in from an older
//  event too, when it names what the chip already says: the log read when a task is opened, after its list entry)
type Extra = { reason?: string; proposal?: DelegateTask["proposal"] };
function chip(t: DelegateTask, seq: number, next: Partial<TaskEntry>, more: Extra = {}) {
  const was = t.entry;
  if (seq > was.seq) {
    t.entry = { ...was, ...next, seq };
    if (next.status !== undefined && next.status !== was.status) t.reason = more.reason;
    else if (more.reason !== undefined) t.reason = more.reason;
    if (more.proposal) t.proposal = more.proposal;
    return;
  }
  if (seq === was.seq && was.proposal === null && next.proposal) t.entry = { ...was, proposal: next.proposal, round: next.round ?? was.round };
  if (more.reason !== undefined && t.reason === undefined && next.status === t.entry.status) t.reason = more.reason;
  if (more.proposal && more.proposal.commit === t.entry.proposal && t.proposal?.commit !== more.proposal.commit) t.proposal = more.proposal;
}
// (a task's own event on its chip: task_status and proposal)
function chipOfEvent(t: DelegateTask, e: TaskEvent, seq: number) {
  if (e.type === "task_status") chip(t, seq, { status: e.status, ...(e.status === "working" ? {} : { question: false }) }, { reason: e.reason });
  else if (e.type === "proposal") chip(t, seq, { round: e.round, proposal: e.commit }, { proposal: { round: e.round, base: e.base, commit: e.commit, files: e.files } });
}

/** One event of a task's log, in seq order: false if it doesn't follow on (a gap: read the log again). */
function take(t: DelegateTask, e: TaskLogEntry): boolean {
  const th = t.thread;
  if (e.seq <= th.applied_seq) return true;
  if (e.seq !== th.applied_seq + 1) return false;
  if ("refused" in e) {
    t.skipped++;
    th.applied_seq = e.seq;
    return true;
  }
  const ev = e.event;
  if (ev.type !== "turn") {
    // (task_status and proposal move the chip; the question events are M2's, not shown yet)
    chipOfEvent(t, ev, e.seq);
    th.applied_seq = e.seq;
    return true;
  }
  const d = ev.event as Record<string, unknown> & { type: string; turn_id?: string };
  // (a turn's events, untagged by the agent, belong to the turn its last turn_started began; tagged ones to their own)
  if (d.type === "turn_started" || !t.turn) t.turn = "s" + e.seq;
  const turn_id = typeof d.turn_id === "string" ? d.turn_id : t.turn;
  apply(th, { ...d, seq: e.seq, turn_id } as unknown as TurnEvent);
  if (d.type === "turn_finished") t.turn = null;
  th.applied_seq = e.seq;
  return true;
}

// What a paired agent may touch (design/workspace-agent-protocol.md §2.2, §3): the person's grant, kept by the
// page.  The server treats a grant as opaque (§2.3, 7), so these rules are the only guard on an agent's folders
// and write access, and every verb passes them before it reaches the workspace.
//
// - A path counts only as normPath makes it (paths.ts: no "." or "..", no empty names, no control characters,
//   within the bounds), and only if it is one of the granted folders or inside one (`within`: "/A" never covers
//   "/AB").  A path normPath refuses is refused.
// - Each verb's paths are all checked: rename's from and to, duplicate's path and to (or, without to, the folder
//   the copy goes in).  list is of a granted folder only.
// - Reading (list, stat, read, history, version) needs the grant; changing anything (write, create, mkdir,
//   rename, duplicate, remove, restore) needs it with write.
// - The granted folders themselves stay: an agent may change what's in them, never remove or move them.
// - Trash: an entry in Trash is reached only through "/" (everything), except restore, which is checked against
//   where the entry came from (its `trashed.from`): that folder, the one it goes back into (under another name if
//   that one is taken), must be granted, with write.
// - An expired grant, or one with no folders, allows nothing.
// - git_branch (chat plan PR 3) is authorized by the page that offers it (git-branch.ts's gitBranchProblem, with the
//   same grant: write, and /Branches/<name> in it, no implicit widening); who may change a branch is the
//   workspace's check at use (branch-rules.ts), by the grant's `id`.

import { TRASH, normPath, parentOf, within } from "./paths";


export type Grant = {
  /** the grant's own id, made by the page when the person allows it (never from the agent or a name), kept with a
   * remembered grant and on a resumption of it: who owns the branches it makes (chat plan PR 3, Q1) */
  id: string;
  agent: string; // the agent's name, as it says
  client: string; // "claude-code", "codex", …, as it says
  folders: string[]; // normalized, "/" for everything
  write: boolean;
  /** "May run code" (design/workspace-files.md §8.3; chat plan PR 4): the run verbs, in Sagebrush's sandbox. A grant
   * kept without it (made before PR 4) is false: never promoted until the person grants again */
  run: boolean;
  expires: number | null; // ms since the epoch; null: until this page closes
  /** The Delegate switch (design/workspace-agent-protocol.md §6.2: "Allow Delegate tasks on this computer"): present,
   * and true, only while the person has it on for this pairing; never kept with a remembered grant or a reload record,
   * so a new pairing starts with it off */
  delegate?: true;
  created: number;
  lastUsed: number;
};

const READ = new Set(["workspace.list", "workspace.stat", "workspace.read", "workspace.history", "workspace.version"]);
const CHANGE = new Set(["workspace.write", "workspace.create", "workspace.mkdir", "workspace.rename", "workspace.duplicate", "workspace.remove", "workspace.restore"]);
/** A grant's id: 16 random bytes, as hex. */
export const GRANT_ID = /^[0-9a-f]{32}$/;
/** `n` random bytes as hex: a grant's id (16, the default), a pairing's (12). */
export const newGrantId = (n = 16) => [...crypto.getRandomValues(new Uint8Array(n))].map((b) => b.toString(16).padStart(2, "0")).join("");

/** A path as normPath makes it, or null if it isn't one. */
export function norm(p: unknown): string | null {
  try { return normPath(p); } catch { return null; }
}

/** The folders as a grant keeps them: each normalized, Trash and anything in it refused, duplicates and folders
 * inside another granted folder dropped.  Throws on a folder that isn't a path or is in Trash. */
export function grantFolders(folders: unknown): string[] {
  if (!Array.isArray(folders) || folders.length === 0) throw new Error("a grant names at least one folder");
  const out: string[] = [];
  for (const f of folders) {
    const p = norm(f);
    if (p === null) throw new Error(`not a folder path: ${JSON.stringify(String(f)).slice(0, 80)}`);
    if (p !== "/" && within(p, TRASH)) throw new Error("Trash isn't granted on its own");
    out.push(p);
  }
  return out.filter((p, i) => !out.some((q, j) => (j !== i && q !== p && within(p, q)) || (j < i && q === p)));
}

/** Whether the grant allows anything at all now: why not, or null. */
export function grantProblem(g: Grant | null, now: number): string | null {
  if (!g) return "no grant: the person hasn't allowed this agent anything";
  if (!Array.isArray(g.folders) || g.folders.length === 0) return "the grant names no folders";
  if (g.expires !== null && !(now < g.expires)) return "the grant has expired";
  return null;
}

/** Whether `p` (as normPath makes it) is one of `folders` or inside one, and outside Trash unless "/" is granted. */
export function inGrant(p: string | null, folders: string[]): boolean {
  if (p === null) return false;
  if (within(p, TRASH) && !folders.includes("/")) return false;
  return folders.some((f) => within(p, f));
}

/** Whether `p` is itself one of the granted folders (which an agent may not remove or move). */
const isGrantRoot = (p: string | null, folders: string[]) => p !== null && folders.includes(p);

/** An entry in Trash, as the workspace's stat gives it: `trashed.from` is where it was removed from. */
export type TrashEntry = { trashed?: { from: string } } & Record<string, unknown>;

/** Why the call isn't allowed under `g` at `now`, or null.  `trashEntry(p)` gives the entry at `p` (restore's
 * check: where it came from), or null.  For restore, `out.expect` is set to that very entry: the restore must be
 * of it and no other (Workspace.restore's `expect`, checked holding its lock), so an entry put in its place in
 * the meantime is never restored on this authorization. */
export async function authorize(method: string, params: any, g: Grant | null, now: number, trashEntry: (p: string) => Promise<TrashEntry | null | undefined>, outArg: { expect?: TrashEntry } = {}): Promise<string | null> {
  const no = grantProblem(g, now);
  if (no) return no;
  const folders = g!.folders;
  const read = READ.has(method), change = CHANGE.has(method);
  if (!read && !change) return `not a verb an agent may call: ${method}`;
  if (change && !g!.write) return "the grant is read only";
  const out = (p: unknown) => `outside the folders this agent may ${change ? "change" : "read"}: ${JSON.stringify(String(p)).slice(0, 120)}`;
  switch (method) {
    case "workspace.list": {
      const f = norm(params.folder);
      return inGrant(f, folders) ? null : out(params.folder);
    }
    case "workspace.rename": {
      const from = norm(params.from), to = norm(params.to);
      if (!inGrant(from, folders)) return out(params.from);
      if (!inGrant(to, folders)) return out(params.to);
      if (isGrantRoot(from, folders)) return "a granted folder itself can't be moved by the agent";
      return null;
    }
    case "workspace.duplicate": {
      const p = norm(params.path);
      if (!inGrant(p, folders)) return out(params.path);
      if (params.to !== undefined) return inGrant(norm(params.to), folders) ? null : out(params.to);
      // (without to, the copy goes beside it: in its folder)
      return inGrant(parentOf(p!), folders) ? null : out(params.path);
    }
    case "workspace.remove": {
      const p = norm(params.path);
      if (!inGrant(p, folders)) return out(params.path);
      return isGrantRoot(p, folders) ? "a granted folder itself can't be removed by the agent" : null;
    }
    case "workspace.restore": {
      const p = norm(params.path);
      if (p === null || !within(p, TRASH) || p === TRASH) return "restore takes an entry in Trash";
      const e = await trashEntry(p);
      const from = norm(e?.trashed?.from);
      if (!e || from === null) return "no such entry in Trash";
      if (!inGrant(from, folders)) return out(from);
      // (it goes back into the folder it came from, under another name if that one is taken (Workspace.restore):
      // so that folder must be in the grant, whatever name it ends up with, now or by the time it runs)
      if (!inGrant(parentOf(from), folders)) return `restoring ${JSON.stringify(from)} would put it in ${JSON.stringify(parentOf(from))}, outside the folders this agent may change`;
      outArg.expect = e;
      return null;
    }
    default: {
      // stat, read, history, version, write, create, mkdir: one path
      const p = norm(params.path);
      return inGrant(p, folders) ? null : out(params.path);
    }
  }
}

// The page's side of a pairing with an agent on this computer (design/workspace-agent-protocol.md): a WebSocket
// to sagebrush-mcp on the loopback address, the hello with the code the agent gave, then, once the person has
// granted it something, the workspace verbs the agent calls, each checked here before it reaches the workspace.
//
// The server checks the origin, the code and the framing; it treats the grant as opaque (§2.3, 7).  So this page
// is the only guard on what the agent may touch, and every call passes, in order:
//   1. the frame: at most 8 KiB before the hello has paired, 12 MiB after, measured before it is parsed; strict
//      JSON (no key twice in an object) — else the socket closes (1009, 1007);
//   2. the verb and its params against schema.json (agent-schema.ts);
//   3. the grant (agent-grant.ts): folders, write, expiry;
//   4. the limits: 8 calls in flight, 100 a second (a burst of 200), 8 MiB of contents;
//   5. the workspace, through forAgent: every change credited to agent:<name>.
// Nothing the server sends is ever evaluated. After the hello the page sends it notifications, and, through own()
// (tasks-client.ts, Delegate's tasks.* only), its own requests, whose answers are matched by id.

import { checkCall, badValue, AGENT_LIMITS } from "./agent-schema";
import { editProblem, type NotebookEdit } from "./notebook-edit";
import { authorize, grantFolders, grantProblem, newGrantId, norm, GRANT_ID, type Grant, type TrashEntry } from "./agent-grant";
import { BRANCHES, within } from "./paths";
import { entryUrl } from "./entry-url";
import { MADE_CHANNEL, type TexMade, type TexMayRun, type TexMayRunYes } from "./agent-made-tex";

/** What the hello's result says (the agent's own claims, shown as such). Over a runner (`link`), the agent's
 * agent.ready says it, with `child`: this agent process's identity, bound into every permission digest. */
export type Hello = { protocol: 1; agent: { name: string; client: string; version?: string }; wants: { folders?: string[]; write?: boolean; run?: boolean }; session?: string; features?: string[]; child?: string; log?: { instance: string } };
/** What a page may offer beyond the workspace's verbs, said in its hello and in the agent's: "notebook.edit", an
 * agent's edit of an open notebook by cell (web/workspace/notebook-edit.ts, A12 step 1); "permission.digest", an Allow
 * that carries the digest of the action shown (agent-canon.ts); "run.context", a run verb's call that carries the chat and
 * the turn it came from (`conversation`, `turn_id`), added by the agent's server after the model's arguments, never the
 * model's own (run_notebook in the notebook open on the page runs there only for that chat's running turn);
 * "chat.resume", an agent that keeps each conversation's log and replays what a page missed (its hello's `log` names
 * the run its numbers belong to); "edit.turn", a notebook.edit that carries the turn it came from (`turn_id`, the
 * agent's server's), applied only while that turn is the chat's running one; "chat.steer", an agent that takes a message
 * into its running turn (Steer, step 3); "egress.turn", a web card (the agent's fetch, the built-in search) that also
 * offers "for this turn", its own action and digest (agent-egress.ts); "delegate.1", an agent that takes Delegate's
 * tasks.* requests (pair-delegate-plan-r3.3 §2.5; the page's side is tasks-client.ts). */
export const FEATURES = ["notebook.edit", "permission.digest", "run.context", "chat.resume", "edit.turn", "chat.steer", "egress.turn", "delegate.1"] as const;
/** The `log` an agent's hello or agent.ready names: its run, as the agent's random hex id; anything else, none. */
export const logOf = (v: unknown): { instance: string } | undefined => {
  const i = (v as { instance?: unknown } | null)?.instance;
  return typeof i === "string" && /^[0-9a-f]{8,64}$/.test(i) ? { instance: i } : undefined;
};
/** The pairing's other end on one of the person's computers (agent-relay.ts's AgentLeg), in place of the loopback
 * socket, with its own frame bound, queue and reply slots: what the pairing asks of it. */
export type AgentLink = {
  /** the leg as the pairing's socket; `ended` hears why it ended first */
  socket(ended: (e: { kind: string; why: string }) => void): WebSocket;
  /** an agent.ready: who the agent is (undefined: not one; false: one in an unknown form) */
  ready(msg: any): { agent: Hello["agent"]; features: string[]; child: string; log?: { instance: string } } | false | undefined;
  send(text: string): "ok" | "full" | "over" | "closed";
  /** a reply's place, taken as a call arrives (false: too many owed, the leg ends) */
  owe(): boolean;
  /** an owed reply: the first of `tries` within the leg's bound, else its limit error */
  answer(id: string, tries: unknown[]): void;
  disconnect(): Promise<void>;
};
/** The verbs, as Workspace.forAgent gives them. */
export type AgentVerbs = {
  list(folder: string, opts?: { recursive?: boolean }): Promise<any[]>;
  stat(p: string): Promise<any | undefined | null>;
  read(p: string): Promise<{ entry: any; content: any; rev: number }>;
  write(p: string, content: unknown, opts?: { base?: number }): Promise<{ entry: any; rev: number }>;
  create(p: string, opts?: { content?: unknown; mode?: string }): Promise<any>;
  mkdir(p: string): Promise<any>;
  rename(from: string, to: string): Promise<any>;
  duplicate(p: string, to?: string): Promise<any>;
  remove(p: string): Promise<any>;
  restore(p: string, expect?: any): Promise<any>;
  history(p: string): Promise<any[]>;
  version(p: string, i: number): Promise<Uint8Array>;
  /** The workspace's check at use of a change made elsewhere (notebook.edit): the branches' rule, asked holding its
   * lock, which is kept until the returned release is called (or a few seconds pass). */
  holdChange?(p: string): Promise<() => void>;
};
/** git_branch, the page's (git-branch.ts, through Workspace.branchHost), on the pages that offer it: its parameters'
 * and grant checks, and the branch made for the grant `owner`. */
export type GitBranch = {
  params(p: unknown): string | null;
  problem(p: unknown, g: Grant | null, now: number): string | null;
  run(a: { actor: string; name: string; owner: string; folders: string[]; live: () => boolean }): Promise<unknown>;
};
/** The run verbs (chat plan PR 4a: run_notebook, run_file, run_stop), on the pages that offer them (run-holder.ts): the
 * pairing only hands them the call and its side of it (`side`), so a page without runs carries none of their checks. */
export type RunSide = {
  grant: Grant | null; agent: string; actor: string; now(): number;
  /** whether this pairing's grant is in force and is `g` (current()) */
  current(g: Grant | null): boolean;
  live: { state(): PairState; grant(): Grant | null; closeReason(): string };
  onChange(cb: () => void): () => void;
  reply(result: unknown): void; fail(code: string, message: string): void;
  /** the chat and the turn the call came from (run.context), both or neither: as the agent's server said them */
  context?: { conversation: string; turnId: string };
};
export type RunVerbs = { serve(method: string, params: unknown, side: RunSide): Promise<void> };
/** run.context's ids: at most this long (notebook.edit's conversation's bound) */
const RUN_CONTEXT_LENGTH = 128;
export const RUN_VERBS = ["workspace.run_notebook", "workspace.run_file", "workspace.run_stop", "workspace.latex_build"] as const;
/** Where the page keeps grants (Workspace.agentGrants / putAgentGrant). */
export type GrantStore = { agentGrants(): Promise<Record<string, unknown>>; putAgentGrant(id: string, g: unknown | null): Promise<void> };
/** A grant as kept: the grant, and the session secret if the person ticked "Remember this agent". */
export type Kept = { grant: Grant; session?: string; port: number };

export type PairState = "connecting" | "paired" | "granted" | "closed";

const PRE_HELLO_MAX = 8 * 1024;
const enc = new TextEncoder();

/** `text` parsed as strict JSON: what JSON.parse takes, and no object with a key twice (compared as decoded). */
export function parseStrict(text: string): unknown {
  const v = JSON.parse(text);
  // (a scan of the text for each object's keys, strings skipped: JSON.parse said the text is well formed)
  const stack: (Set<string> | null)[] = [];
  let expectKey = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '"') {
      let j = i + 1;
      while (text[j] !== '"') j += text[j] === "\\" ? 2 : 1;
      const top = stack[stack.length - 1];
      if (top && expectKey) {
        const k = JSON.parse(text.slice(i, j + 1)) as string;
        if (top.has(k)) throw new SyntaxError(`a JSON object repeats the key ${JSON.stringify(k.slice(0, 64))}`);
        top.add(k);
        expectKey = false;
      }
      i = j;
    } else if (c === "{") { stack.push(new Set()); expectKey = true; }
    else if (c === "[") { stack.push(null); }
    else if (c === "}" || c === "]") { stack.pop(); }
    else if (c === "," && stack[stack.length - 1]) expectKey = true;
  }
  return v;
}

/** The bytes of a frame, or more than `max` if it is surely over (a UTF-16 unit is at least one UTF-8 byte). */
const frameBytes = (s: string, max: number) => (s.length > max ? s.length : enc.encode(s).length);

/** An agent name as forAgent takes it: agent:<letters, digits, _ . ->, at most 64. */
export function actorOf(name: string, client: string): string {
  const n = (String(name || client || "agent").replace(/[^\w.-]+/g, "-").replace(/^-+|-+$/g, "") || "agent").slice(0, 64);
  return "agent:" + n;
}

/** An entry as an agent sees it: its path, kind and what a person sees of it, nothing internal (ids, refs). With
 * `origin`, and when it has a page of its own (a notebook, a board, a .tex or code file), also `url`: that page on this
 * site, as the file browser opens it (entry-url.ts), for the agent to give the person a link. It comes from this very
 * entry, the one the verb returned under the grant: no other read. */
function entryOut(e: any, origin?: string) {
  if (!e) return null;
  const out: Record<string, unknown> = { path: e.path, kind: e.kind, created: e.created, updated: e.updated };
  for (const k of ["mode", "size", "rev"]) if (e[k] !== undefined) out[k] = e[k];
  if (e.trashed) out.trashed = { from: e.trashed.from, at: e.trashed.at };
  const u = origin && !e.trashed ? entryUrl(e) : null;
  if (u) out.url = origin + u;
  return out;
}

const b64 = (u: Uint8Array) => { let s = ""; for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode(...u.subarray(i, i + 0x8000)); return btoa(s); };
const unb64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

/** Contents' size in bytes, the same in both directions: a document's JSON text in UTF-8, a text's UTF-8 bytes,
 * a data file's bytes (base64's decoded length). */
export function contentBytes(c: { json: unknown } | { text: string } | { bytes: Uint8Array }): number {
  if ("json" in c) return enc.encode(JSON.stringify(c.json)).length;
  if ("text" in c) return enc.encode(c.text).length;
  return c.bytes.length;
}
const tooBig = (n: number, what: string) => new AgentError("limit", `${what}: ${n} bytes of contents, at most ${AGENT_LIMITS.maxContentBytes} in one call`);
/** Contents on the wire: a document as {json}; a data file as {text} if it is UTF-8, else {base64}; over 8 MiB
 * refused with their size (never cut). */
function contentOut(kind: string, c: unknown, what: string) {
  const MAX = AGENT_LIMITS.maxContentBytes;
  if (kind === "notebook" || kind === "board") { const n = contentBytes({ json: c }); if (n > MAX) throw tooBig(n, what); return { json: c }; }
  if (typeof c === "string") { const n = contentBytes({ text: c }); if (n > MAX) throw tooBig(n, what); return { text: c }; }
  const u = c instanceof Uint8Array ? c : c instanceof ArrayBuffer ? new Uint8Array(c) : null;
  if (!u) throw new AgentError("storage", "contents in an unknown form");
  if (u.length > MAX) throw tooBig(u.length, what);
  try { return { text: new TextDecoder("utf-8", { fatal: true }).decode(u) }; } catch { return { base64: b64(u) }; }
}
/** Contents from the wire (8 MiB at most, refused with their size, never cut). */
function contentIn(c: any, what: string): unknown {
  const v = "json" in c ? { json: c.json } : "text" in c ? { text: c.text as string } : { bytes: unb64(c.base64) };
  const n = contentBytes(v);
  if (n > AGENT_LIMITS.maxContentBytes) throw tooBig(n, what);
  return "json" in v ? v.json : "text" in v ? v.text : v.bytes;
}

/** A document an agent created through its pairing: `op` this creation's own id, `ref` a notebook's or board's document
 * id (its identity wherever it moves), `grant` the grant it was created under; a file's `fid` and the revision it was
 * left at, `rev` (a .tex's, for its run once by itself: agent-made-tex.ts). */
export type Created = { op: string; path: string; kind: "notebook" | "board" | "file"; ref?: string; grant: string; updated?: number; fid?: string; rev?: number };
const isTex = (c: Created | null): c is Created & { fid: string; rev: number } => !!c && c.kind === "file" && /\.tex$/i.test(c.path) && typeof c.fid === "string" && typeof c.rev === "number";

export class AgentError extends Error {
  constructor(public code: string, message: string, public extra: Record<string, unknown> = {}) { super(message); }
}

/** The pairing.  `verbsFor(actor)` gives the workspace's verbs credited to `actor` (Workspace.forAgent). */
// (what is said when the grant changed under a call: nothing of what it read, and, for a change, no claim either way)
/** A grant as the server is told it (grant.changed): `delegate` only when on, so an agent that doesn't know it reads
 * the same grant as before. */
const changed = (g: Grant) => ({ id: g.id, agent: g.agent, client: g.client, folders: g.folders, write: g.write, run: g.run, expires: g.expires, ...(g.delegate ? { delegate: true } : {}) });
export const CHANGED_WHILE_RUNNING = "the grant changed or expired while this ran: nothing of it is said (a change may or may not have been made)";

export class AgentPairing {
  state: PairState = "connecting";
  hello: Hello | null = null;
  grant: Grant | null = null;
  changes = 0;
  /** What this agent created last through this pairing (workspace.create, answered under the grant in force): the page's
   * Open for it */
  created: Created | null = null;
  /** The .tex this agent last built (latex_build, done, under the grant in force), at the revision it built, if that
   * revision is still the file's when the build answered: its run once by itself, as a creation's (agent-made-tex.ts) */
  built: Created | null = null;
  closeReason = "";
  // (the editors' channel (agent-made-tex.ts), and the made .tex revisions whose one run has been answered yes)
  private texChan: BroadcastChannel | null = null;
  private texSpent = new Set<string>();
  private sock: WebSocket;
  private verbs: AgentVerbs | null = null;
  private inFlight = 0;
  private tokens: number;
  private refill: number;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private listeners = new Set<() => void>();
  private notified = new Set<(method: string, params: unknown) => void>();
  private pairingId = "";
  private remember = false;
  private helloSent: Promise<Hello>;
  // (A14: the session secret this pairing holds, from the hello or the reload record it was restored from; its
  //  generation, so an older pairing's end can't touch a newer one's record; the record it would restore from after
  //  an involuntary loss, kept in memory only)
  private sessionSecret: string | undefined;
  private readonly gen = ++pairingGen;
  lostRecord: ReloadRecord | null = null;
  private revoked = false;
  // (the page's own requests (Delegate's, tasks-client.ts): who hears their answers)
  private ownAnswers: ((msg: any, bytes: number) => boolean) | null = null;

  /** Over a runner: the leg, the computer's name, and why the leg ended (for the page's words). */
  readonly link: AgentLink | null = null;
  readonly computer: string = "";
  linkEnd: { kind: string; why: string } | null = null;

  constructor(
    readonly port: number,
    how: { code: string } | { session: string; pairingId: string; agent?: { name: string; client: string } } | { link: AgentLink; computer: string },
    private opts: { verbsFor: (actor: string, host: { owner: () => string | null }) => AgentVerbs; gitBranch?: GitBranch; gitVerbs?: RunVerbs; store: GrantStore; trashEntry: (p: string) => Promise<TrashEntry | null | undefined>; page: { origin: string; path: string }; now?: () => number; WebSocketImpl?: typeof WebSocket; runVerbs?: RunVerbs; notebookEdit?: (edit: NotebookEdit, may: () => boolean, hold?: () => Promise<() => void>, turnId?: string) => Promise<unknown>; onCreated?: (c: Created, p: AgentPairing) => void; egressTurn?: boolean; reload?: { storage: ReloadStorage | null; scope: ReloadScope; leaving: () => boolean } },
  ) {
    if ("link" in how) { this.link = how.link; this.computer = how.computer; }
    else if (!Number.isInteger(port) || port < 1 || port > 65535) throw new AgentError("invalid", "a port is 1 to 65535");
    // (the editors' channel, once the pairing is admitted: agent-made-tex.ts)
    if (typeof BroadcastChannel === "function") { this.texChan = new BroadcastChannel(MADE_CHANNEL); this.texChan.onmessage = (e) => this.texAsked(e.data); }
    const now = this.now();
    this.tokens = AGENT_LIMITS.burst;
    this.refill = now;
    if (this.link) this.sock = this.link.socket((e) => { this.linkEnd = e; });
    else { const WS = opts.WebSocketImpl ?? WebSocket; this.sock = new WS(`ws://127.0.0.1:${port}/sagebrush`); }
    if ("pairingId" in how) { this.pairingId = how.pairingId; this.sessionSecret = how.session; }
    this.helloSent = new Promise<Hello>((resolve, reject) => {
      this.sock.onopen = () => {
        if ("link" in how) return; // (the leg made its own hello; the agent's agent.ready answers here)
        const params: Record<string, unknown> = { protocol: 1, page: opts.page };
        if ("code" in how) params.code = String(how.code).trim().replace(/[\s-]+/g, "");
        else params.session = how.session;
        this.sock.send(JSON.stringify({ jsonrpc: "2.0", id: "p1", method: "hello", params }));
      };
      this.sock.onerror = () => {};
      this.sock.onclose = (e) => {
        const why = this.closeReason || e.reason || (e.code === 1006 ? "the connection failed (is the agent's sagebrush-mcp running, and is this browser allowed to reach it?)" : `closed (${e.code})`);
        this.end(why);
        reject(new AgentError("refused", why));
      };
      this.sock.onmessage = (e) => {
        if (this.state === "closed") return; // (nothing after the end)
        if (typeof e.data !== "string") return this.close(1003, "only text frames");
        const max = this.state === "connecting" ? PRE_HELLO_MAX : AGENT_LIMITS.maxFrameBytes;
        const bytes = frameBytes(e.data, max);
        if (bytes > max) return this.close(1009, `a message over ${max} bytes`);
        let msg: any;
        try { msg = parseStrict(e.data); } catch (err) { return this.close(1007, "not strict JSON: " + (err as Error).message); }
        if (!msg || typeof msg !== "object" || Array.isArray(msg) || msg.jsonrpc !== "2.0") return this.close(1002, "not JSON-RPC 2.0");
        // (over a runner: the agent's agent.ready, on each attach, says who it is and its child, the identity its
        //  permission digests bind; the first one pairs)
        const ready = this.link?.ready(msg);
        if (ready === false) return this.close(1002, "an agent.ready in an unknown form");
        if (ready) {
          if (this.state !== "connecting") { this.hello = { ...this.hello!, log: undefined, ...ready }; this.emit(); return; }
          this.hello = { protocol: 1, wants: { folders: ["/"], write: true }, ...ready };
          this.pairingId = newGrantId(12);
          this.state = "paired";
          this.emit();
          return resolve(this.hello);
        }
        if (this.state === "connecting") {
          if (this.link) return this.close(1002, "a message before the agent was ready");
          if (msg.id !== "p1") return this.close(1002, "the first answer must be the hello's");
          if (msg.error) {
            const m = String(msg.error?.data?.message ?? msg.error?.message ?? "refused").slice(0, 300);
            this.end("the agent refused: " + m);
            return reject(new AgentError(String(msg.error?.data?.code ?? "refused"), m));
          }
          const r = msg.result;
          if (!r || r.protocol !== 1 || !r.agent || typeof r.agent.name !== "string") return this.close(1002, "a hello result in an unknown form");
          this.hello = { protocol: 1, agent: { name: String(r.agent.name).slice(0, 80), client: String(r.agent.client ?? "").slice(0, 40), version: r.agent.version ? String(r.agent.version).slice(0, 40) : undefined }, wants: { folders: Array.isArray(r.wants?.folders) ? r.wants.folders.slice(0, 50).map(String) : undefined, write: !!r.wants?.write, run: !!r.wants?.run }, session: typeof r.session === "string" ? r.session : undefined, log: logOf(r.log), features: Array.isArray(r.features) ? r.features.filter((f: unknown): f is string => typeof f === "string" && (FEATURES as readonly string[]).includes(f)) : [], ...(typeof r.child === "string" && /^[A-Za-z0-9_-]{1,128}$/.test(r.child) ? { child: r.child } : {}) };
          // (A14: a restore's session must be answered by the agent it was given to, name and client; else closed)
          if ("agent" in how && how.agent && (this.hello.agent.name !== how.agent.name || this.hello.agent.client !== how.agent.client)) {
            // (said first: a socket whose close is heard at once (Bun 1.3's) would otherwise answer it as a plain close)
            reject(new AgentError("identity", "another agent answered this page's session"));
            return this.close(1000, "another agent answered this page's session");
          }
          if (!this.pairingId) this.pairingId = newGrantId(12);
          if (this.hello.session) this.sessionSecret = this.hello.session;
          this.state = "paired";
          this.emit();
          return resolve(this.hello);
        }
        if (typeof msg.method === "string" && msg.id === undefined) {
          // (a notification: the chat on the same connection, §4; only once paired, given to the page's listeners)
          for (const cb of this.notified) cb(msg.method, msg.params);
          return;
        }
        if (typeof msg.method === "string" && typeof msg.id === "string") return void this.call(msg.id, msg.method, msg.params);
        // (an answer to one of the page's own requests, if its client knows the id; any other answer is dropped)
        if (msg.method === undefined && typeof msg.id === "string" && this.ownAnswers?.(msg, bytes)) return;
        // (any other answer: to no request the page has pending (not one of own()'s ids), dropped)
      };
    });
  }

  private now() { return this.opts.now ? this.opts.now() : Date.now(); }
  /** The hello's result, once paired. */
  paired(): Promise<Hello> { return this.helloSent; }
  get id() { return this.pairingId; }
  onChange(cb: () => void) { this.listeners.add(cb); return () => void this.listeners.delete(cb); }
  /** The server's notifications (the chat, §4): what it says is data for the page to show, never run. */
  onNotification(cb: (method: string, params: unknown) => void) { this.notified.add(cb); return () => void this.notified.delete(cb); }
  /** A notification to the server (the chat, §4): only while granted, and within the frame bound (else false). */
  notify(method: string, params: unknown): boolean {
    return this.notifyWhy(method, params) === "ok";
  }
  /** The same, saying why one wasn't sent: "full" (over a runner: the queue has no room now), "over" (its message
   * alone is over the connection's bound), "closed" (not granted). */
  notifyWhy(method: string, params: unknown): "ok" | "full" | "over" | "closed" {
    if (this.state !== "granted") return "closed";
    const text = JSON.stringify({ jsonrpc: "2.0", method, params });
    if (this.link) return this.link.send(text);
    return this.sendBounded({ jsonrpc: "2.0", method, params }) ? "ok" : "over";
  }
  private emit() { for (const cb of this.listeners) cb(); }
  /** For the page's own requests (tasks-client.ts, its only user): send one message, while granted and on the loopback
   * pairing only, within the frame bound; and hear the answers, each with its frame's UTF-8 bytes as received (`hear`
   * returns true for an id it knows). */
  own(hear: (msg: any, bytes: number) => boolean): { send(m: unknown): "ok" | "closed" | "over" | "link" } {
    this.ownAnswers = hear;
    return { send: (m) => (this.link ? "link" : this.state !== "granted" ? "closed" : this.sendBounded(m) ? "ok" : "over") };
  }

  /** The person's grant: sent to the server, kept (with the session secret if `remember`), and in force from now.
   * `id`: the id of the grant this resumes (a remembered one, or the reload record's); else this pairing's grant's,
   * if it has one; else a new one (Q1: made here, never the agent's). */
  async allow(g: { folders: string[]; write: boolean; run?: boolean; expires: number | null; id?: string }, remember: boolean) {
    if (this.state !== "paired" && this.state !== "granted") throw new AgentError("invalid", "not paired");
    const h = this.hello!, now = this.now();
    const id = typeof g.id === "string" && GRANT_ID.test(g.id) ? g.id : this.grant?.id ?? newGrantId();
    // (the Delegate switch is apart from Pair's grant (§6.2): a new grant from the person keeps it as it was)
    const grant: Grant = { id, agent: h.agent.name, client: h.agent.client, folders: grantFolders(g.folders), write: !!g.write, run: g.run === true, expires: g.expires, ...(this.grant?.delegate ? { delegate: true as const } : {}), created: this.grant?.created ?? now, lastUsed: now };
    this.grant = grant;
    this.remember = remember;
    this.verbs = this.opts.verbsFor(actorOf(h.agent.name, h.agent.client), { owner: () => grant.id });
    // (what this page offers beyond the verbs, sent before its grant (A2-1): a notification, which a server that
    //  doesn't know it ignores, §1 rule 4)
    // (permission.digest: every Allow carries the digest of the action shown, from any page that pairs)
    this.send({ jsonrpc: "2.0", method: "page.features", params: { features: [...(this.opts.notebookEdit ? ["notebook.edit", "edit.turn"] : []), "permission.digest", ...(this.opts.runVerbs ? ["run.context"] : []), ...(this.opts.egressTurn ? ["egress.turn"] : [])] } });
    this.send({ jsonrpc: "2.0", method: "grant.changed", params: changed(grant) });
    await this.keep();
    // (S4: while it waited, the grant may have been revoked, the pairing closed or the grant replaced: then nothing
    //  of this allow() goes on, no record, no timer, no "granted")
    if ((this.state as AgentPairing["state"]) === "closed" || this.grant !== grant) return;
    this.keepForReload();
    if (this.timer) clearTimeout(this.timer);
    if (grant.expires !== null) this.timer = setTimeout(() => void this.revoke("the grant expired"), Math.max(0, grant.expires - now));
    this.state = "granted";
    this.emit();
  }
  private async keep() {
    if (!this.grant || !this.pairingId) return;
    // (only a remembered grant outlives the page: "until this page closes" is never kept. The session kept is the one in
    //  force: the hello's after a code, the remembered one after a reconnect, whose hello carries none; the hello's alone
    //  lost it on the first reconnect, and the next had nothing to send (T1, found by git-proto at b72938d8a))
    if (this.remember && this.grant.expires !== null) {
      const { delegate: _, ...grant } = this.grant;
      await this.opts.store.putAgentGrant(this.pairingId, { grant, session: this.sessionSecret, port: this.port } satisfies Kept);
    }
  }

  /** The reload record (A14): written for an unremembered grant only (a remembered one is kept in IndexedDB, above),
   * with the grant exactly as allowed; never for a pairing without a session secret. */
  private keepForReload() {
    const r = this.opts.reload, g = this.grant, h = this.hello;
    if (!r || !g || !h || this.remember || !this.pairingId || !this.sessionSecret || this.gen !== pairingGen) return;
    putReloadRecord(r.storage, { v: 1, pairingId: this.pairingId, session: this.sessionSecret, port: this.port, agent: { name: h.agent.name, client: h.agent.client }, grant: { folders: g.folders, write: g.write, ...(g.run ? { run: true } : {}), expires: g.expires, id: g.id }, workspace: r.scope.workspace, page: r.scope.page });
  }
  /** The record removed from storage, if it is this pairing's (its id) and this is the newest pairing (its gen). */
  private dropReload() {
    const r = this.opts.reload;
    if (!r || this.gen !== pairingGen) return;
    let held: ReloadRecord | null = null;
    try { held = parseReloadRecord(r.storage?.getItem(RELOAD_KEY) ?? null); } catch { held = null; }
    if (!held || held.pairingId === this.pairingId) putReloadRecord(r.storage, null);
  }

  /** "May run code" turned off by the person, mid-session (chat plan PR 4): the grant in force replaced by the same one
   * without it, so a call or run made under the old one finds it changed (current()) and ends; told to the server and
   * kept as the grant is. Never turned on here: only a new grant does that. */
  async noRun() {
    const g = this.grant;
    if (this.state !== "granted" || !g || !g.run) return;
    const next = this.regrant({ ...g, run: false });
    await this.keep();
    if (this.grant === next) this.keepForReload();
  }

  /** The Delegate switch (§6.2), turned on or off by the person: the grant in force replaced by the same one with or
   * without `delegate: true`, told to the server at once (whose every tasks.* call checks it; off stops the tasks'
   * turns there). On only for an agent on this computer whose hello offers delegate.1. False if nothing was sent. */
  setDelegate(on: boolean): boolean {
    const g = this.grant;
    if (this.state !== "granted" || !g || !!g.delegate === on || (on && (this.link || !this.hello?.features?.includes("delegate.1")))) return false;
    const { delegate: _, ...rest } = g;
    this.regrant(on ? { ...rest, delegate: true } : rest);
    return true;
  }
  // (the grant in force replaced by `next`: a call or run made under the old one finds it changed (current()) and ends)
  private regrant(next: Grant): Grant {
    this.grant = next;
    this.verbs = this.opts.verbsFor(actorOf(this.hello!.agent.name, this.hello!.agent.client), { owner: () => next.id });
    this.send({ jsonrpc: "2.0", method: "grant.changed", params: changed(next) });
    this.emit();
    return next;
  }

  /** Dropped: the socket closed and nothing else (no grant change sent, nothing forgotten): an attempt another pairing
   * has superseded, which must not touch what the person has since chosen. */
  drop(why = "superseded") { this.close(1000, why); }

  /** Revoke: the server told ({}), the socket closed, the kept grant and session forgotten, at once. */
  async revoke(why = "revoked") {
    const id = this.pairingId;
    this.revoked = true;
    this.lostRecord = null;
    this.dropReload();
    this.grant = null;
    this.verbs = null;
    if (this.timer) { clearTimeout(this.timer); this.timer = null; }
    if (this.link) {
      // (over a runner: the leg's drain says grant.changed {} and {"unpair":true}, in order, then closes; the pairing
      //  is over at once, so nothing new is sent or applied meanwhile)
      this.closeReason ||= why;
      const drained = this.link.disconnect();
      this.end(why);
      await drained;
      return;
    }
    if (this.sock.readyState === 1) this.send({ jsonrpc: "2.0", method: "grant.changed", params: {} });
    this.close(1000, why);
    if (id) await this.opts.store.putAgentGrant(id, null);
  }

  private send(m: unknown) { if (this.link) { this.link.send(JSON.stringify(m)); return; } if (this.sock.readyState === 1) this.sock.send(JSON.stringify(m)); }
  /** Close the socket for `why`, with the protocol's code `code` (1002 framing, 1003 not text, 1007 not strict JSON,
   * 1009 too big).  A page's WebSocket may send only 1000 or 3000-4999, with a reason of at most 123 UTF-8 bytes, so
   * the code goes as 4000 + code (1000 stays 1000); if the browser refuses even that, a plain close(), so the socket
   * never stays open. */
  private close(code: number, why: string) {
    this.closeReason ||= why;
    this.grant = null;
    this.verbs = null;
    const wire = code === 1000 ? 1000 : 4000 + (code % 1000);
    let reason = why;
    while (enc.encode(reason).length > 123) reason = reason.slice(0, -1);
    try { this.sock.close(wire, reason); } catch { try { this.sock.close(); } catch {} }
    this.end(why);
  }
  private end(why: string) {
    if (this.state === "closed") return;
    try { this.texChan?.close(); } catch {}
    this.texChan = null;
    this.closeReason ||= why;
    // (A14: an involuntary loss, while the page stays: the record leaves storage, so a later reload doesn't try a
    //  session that just failed, and stays in memory for the bar's one [Reconnect]; a revoke dropped it already; the
    //  page leaving (a reload) keeps it, for the restore)
    const r = this.opts.reload;
    if (r && !this.revoked && !r.leaving() && this.gen === pairingGen) {
      let held: ReloadRecord | null = null;
      try { held = parseReloadRecord(r.storage?.getItem(RELOAD_KEY) ?? null); } catch { held = null; }
      if (held && held.pairingId === this.pairingId) { this.lostRecord = held; putReloadRecord(r.storage, null); }
    }
    this.state = "closed";
    this.grant = null;
    this.verbs = null;
    if (this.timer) { clearTimeout(this.timer); this.timer = null; }
    this.emit();
  }

  /** Send one message if it is within the frame bound; else false (nothing sent, nothing cut). */
  private sendBounded(m: unknown): boolean {
    const s = JSON.stringify(m);
    if (frameBytes(s, AGENT_LIMITS.maxFrameBytes) > AGENT_LIMITS.maxFrameBytes) return false;
    if (this.sock.readyState === 1) this.sock.send(s);
    return true;
  }
  private tooBigFrame(id: string) {
    this.sendBounded({ jsonrpc: "2.0", id, error: { code: -32000, message: "the answer would be over the frame bound", data: { code: "limit", message: `the answer would be over ${AGENT_LIMITS.maxFrameBytes} bytes as a message` } } });
  }
  /** An answer, never over the frame bound: one that would be is replaced by a limit error (nothing cut). */
  private reply(id: string, result: unknown) {
    if (this.link) return this.link.answer(id, [{ jsonrpc: "2.0", id, result }]);
    if (!this.sendBounded({ jsonrpc: "2.0", id, result })) this.tooBigFrame(id);
  }
  /** An error, never over the frame bound either: a conflict's current contents are dropped first (said why),
   * and if it is still too big, a bare limit error. */
  private fail(id: string, code: string, message: string, extra: Record<string, unknown> = {}) {
    const msg = (x: Record<string, unknown>) => ({ jsonrpc: "2.0", id, error: { code: -32000, message, data: { code, message, ...x } } });
    const smaller = () => { const { current: _c, ...rest } = extra; return msg({ ...rest, currentOmitted: `its current contents would make the answer over ${AGENT_LIMITS.maxFrameBytes} bytes as a message: read it` }); };
    if (this.link) return this.link.answer(id, "current" in extra ? [msg(extra), smaller()] : [msg(extra)]);
    if (this.sendBounded(msg(extra))) return;
    if ("current" in extra && this.sendBounded(smaller())) return;
    this.tooBigFrame(id);
  }
  /** Whether `g` (and `verbs`) are still this pairing's grant, in force now: checked after every wait, before anything
   * is said or done on it. */
  private current(g: Grant | null, verbs: AgentVerbs | null) {
    return this.state === "granted" && g !== null && verbs !== null && this.grant === g && this.verbs === verbs && grantProblem(g, this.now()) === null;
  }

  /** One call from the server: checked, then done, then answered (never thrown). */
  private async call(id: string, method: string, params: unknown) {
    if (!/^s[0-9]{1,15}$/.test(id)) return this.close(1002, "a request id the server doesn't make");
    // (over a runner: its reply's place, taken as it arrives, accepted or refused; past the leg's REPLY_SLOTS the leg
    //  ends, failing closed)
    if (this.link && !this.link.owe()) return;
    // (the limits first: a flood is refused before any work)
    const now = this.now();
    this.tokens = Math.min(AGENT_LIMITS.burst, this.tokens + ((now - this.refill) * AGENT_LIMITS.perSecond) / 1000);
    this.refill = now;
    if (this.inFlight >= AGENT_LIMITS.inFlight) return this.fail(id, "limit", `${AGENT_LIMITS.inFlight} calls are already in flight`, { retryAfterMs: 250 });
    if (this.tokens < 1) return this.fail(id, "limit", `more than ${AGENT_LIMITS.perSecond} calls a second`, { retryAfterMs: Math.ceil(((1 - this.tokens) * 1000) / AGENT_LIMITS.perSecond) });
    this.tokens -= 1;
    if (method === "notebook.edit") return void this.edit(id, params);
    if ((RUN_VERBS as readonly string[]).includes(method)) return void this.runVerb(id, method, params);
    // (git_branch: only where the page offers it; its name said as the agent was told it, board's C1)
    const branchy = method === "workspace.git_branch", gb = this.opts.gitBranch;
    if (branchy && !gb) return this.fail(id, "invalid", "not a verb: \"workspace.git_branch\"");
    // (git_commit, git_status, git_wait: only where the page offers branches)
    // (git_commit, git_status, git_wait (git-verbs.ts's GIT_METHODS): served as the run verbs are, by the page's own module
    //  (git-verbs.ts's gitServe), where it offers branches; elsewhere they are no verb, said below)
    if (this.opts.gitVerbs && /^workspace\.git_(commit|status|wait)$/.test(method)) return void this.runVerb(id, method, params, this.opts.gitVerbs, method === "workspace.git_commit");
    const bad = branchy ? gb!.params(params) : checkCall(method, params);
    if (bad) return this.fail(id, "invalid", bad);
    // (the slot is taken before anything is awaited, and given back on every way out: authorization's own reads count)
    this.inFlight++;
    const g = this.grant, verbs = this.verbs;
    try {
      const auth: { expect?: TrashEntry } = {};
      const no = branchy ? gb!.problem(params, g, now) : await authorize(method, params, g, now, this.opts.trashEntry, auth);
      // (while it was authorized, the grant may have been revoked or have expired: it must be the same one, and
      // still in force now, before anything is said, the refusal too, and before the workspace is touched)
      if (!this.current(g, verbs)) return this.fail(id, "invalid", grantProblem(this.grant, this.now()) ?? "the grant changed while this was checked");
      if (no) return this.fail(id, "invalid", no);
      let made: any = null;
      const result = method === "workspace.git_branch" ? await this.branch(g!, verbs!, (params as any).name) : await this.run(verbs!, method.slice("workspace.".length), params as any, auth.expect, (e) => (made = e));
      // (after the last wait, before anything is said: the same grant, in force now, or nothing of what it read)
      if (!this.current(g, verbs)) return this.fail(id, "invalid", CHANGED_WHILE_RUNNING);
      g!.lastUsed = this.now();
      this.reply(id, result);
      // (a document this agent created, answered under this very grant: the page's to open, after the answer)
      if (made) this.madeHere(made, g!);
    } catch (err: any) {
      // (the same check before any error is said: after a change, nothing more is read or said)
      if (!this.current(g, verbs)) return this.fail(id, "invalid", CHANGED_WHILE_RUNNING);
      if (err instanceof AgentError) return this.fail(id, err.code, err.message, err.extra);
      const code = typeof err?.code === "string" && ["invalid", "exists", "missing", "conflict", "limit", "storage"].includes(err.code) ? err.code : "invalid";
      const extra: Record<string, unknown> = {};
      if (code === "conflict" && method === "workspace.write") {
        // (the current contents, if within the content bound: else the conflict is said without them, and why)
        try { const r = await verbs!.read((params as any).path); extra.current = { entry: entryOut(r.entry), rev: r.rev, content: contentOut(r.entry.kind, r.content, (params as any).path) }; }
        catch (e2: any) { if (e2 instanceof AgentError && e2.code === "limit") extra.currentOmitted = e2.message; }
        // (that read was a wait too: checked again before it is said)
        if (!this.current(g, verbs)) return this.fail(id, "invalid", CHANGED_WHILE_RUNNING);
      }
      this.fail(id, code, String(err?.message ?? err).slice(0, 500), extra);
    } finally {
      this.inFlight--;
    }
  }

  /** Whether this pairing edits notebooks by cell: the page offers it and the agent said it uses it (its hello). */
  private edits() { return !!this.opts.notebookEdit && !!this.hello?.features?.includes("notebook.edit"); }

  /** An agent's edit of a notebook (notebook-edit.ts): its grammar, then the grant as for a write of its path, then the
   * page's own apply (the open notebook's host); the same grant checked after every wait, as for the verbs. */
  private async edit(id: string, params: unknown) {
    if (!this.edits()) return this.fail(id, "invalid", "not a verb: \"notebook.edit\"");
    // (edit.turn, when both ends said it: every edit says its turn, a short id, taken out before the edit's grammar is
    //  checked; one without it, or with another value, is refused, nothing applied; an agent that didn't say it: as before)
    let turnId: string | undefined;
    if (this.hello?.features?.includes("edit.turn") && params && typeof params === "object" && !Array.isArray(params)) {
      const { turn_id, ...rest } = params as Record<string, unknown>;
      if (typeof turn_id !== "string" || !turn_id || turn_id.length > RUN_CONTEXT_LENGTH) return this.fail(id, "invalid", "edit: turn_id is the turn's id");
      turnId = turn_id;
      params = rest;
    }
    const bad = badValue(params) ?? editProblem(params);
    if (bad) return this.fail(id, "invalid", bad);
    const e = params as NotebookEdit;
    this.inFlight++;
    const g = this.grant, verbs = this.verbs, now = this.now();
    try {
      const no = await authorize("workspace.write", { path: e.path }, g, now, this.opts.trashEntry);
      if (!this.current(g, verbs)) return this.fail(id, "invalid", grantProblem(this.grant, this.now()) ?? "the grant changed while this was checked");
      if (no) return this.fail(id, "invalid", no);
      // (the branches' rule (chat plan PR 3, P3-2), for a notebook in /Branches, the only place it says anything: the
      //  page asks it right before its own synchronous apply, holding the workspace's lock across both (`hold`), so
      //  nothing moves the branch between the check and the change; an edit elsewhere never waits on the lock)
      const np = norm(e.path);
      let hold: (() => Promise<() => void>) | undefined;
      if (np !== null && within(np, BRANCHES)) {
        if (!verbs?.holdChange) throw new AgentError("invalid", "this page can't check a notebook's branch");
        hold = () => verbs.holdChange!(np);
      }
      // (with the check of this very grant, for the page to make right before it changes anything: astra's C1)
      const result = await this.opts.notebookEdit!(e, () => this.current(g, verbs), hold, turnId);
      if (!this.current(g, verbs)) return this.fail(id, "invalid", CHANGED_WHILE_RUNNING);
      g!.lastUsed = this.now();
      this.changes++;
      this.emit();
      this.reply(id, result);
    } catch (err: any) {
      if (!this.current(g, verbs)) return this.fail(id, "invalid", CHANGED_WHILE_RUNNING);
      if (err instanceof AgentError) return this.fail(id, err.code, err.message, err.extra);
      this.fail(id, "invalid", String(err?.message ?? err).slice(0, 500));
    } finally {
      this.inFlight--;
    }
  }

  /** A run verb (chat plan PR 4a): the page's (run-holder.ts), for this grant, with its slot taken as any call's; or a
   * git verb, the same way (git-verbs.ts's gitServe), where the page offers branches. `counted`: a success is one of the
   * agent's changes (git_commit's), counted and told as the workspace's verbs' are. */
  private async runVerb(id: string, method: string, params: unknown, rv = this.opts.runVerbs, counted = false) {
    if (!rv) return this.fail(id, "invalid", `not a verb: ${JSON.stringify(method)}`);
    const h = this.hello!;
    // (run.context, when both ends said it: the chat and turn taken out of the call before its params are checked;
    //  each a short string, else the call is refused; one without the other is neither)
    let context: RunSide["context"];
    if (rv === this.opts.runVerbs && h.features?.includes("run.context") && params && typeof params === "object" && !Array.isArray(params) && ("conversation" in params || "turn_id" in params)) {
      const { conversation, turn_id, ...rest } = params as Record<string, unknown>;
      const id1 = (v: unknown) => v === undefined || (typeof v === "string" && v.length > 0 && v.length <= RUN_CONTEXT_LENGTH);
      if (!id1(conversation) || !id1(turn_id)) return this.fail(id, "invalid", "run context: conversation and turn_id are the chat's and the turn's ids");
      if (typeof conversation === "string" && typeof turn_id === "string") context = { conversation, turnId: turn_id };
      params = rest;
    }
    this.inFlight++;
    try {
      // (latex_build: the .tex as it was before, for its run once by itself if the build is done and it is unchanged; only
      //  under the grant in force now (current), and one that could ever let it (Everything and May run code:
      //  mayRunCreated), else nothing is read. Inside the try: every way out gives the call's slot back)
      const g0 = this.grant, v0 = this.verbs;
      const texPath = method === "workspace.latex_build" && typeof (params as any)?.path === "string" && this.current(g0, v0) && g0!.run === true && g0!.folders.length === 1 && g0!.folders[0] === "/" ? (params as any).path as string : null;
      const before = texPath ? await v0!.stat(texPath).catch(() => null) : null;
      await rv.serve(method, params, {
        grant: this.grant, agent: h.agent.name, actor: actorOf(h.agent.name, h.agent.client), now: () => this.now(),
        current: (g) => this.current(g, this.verbs),
        live: { state: () => this.state, grant: () => this.grant, closeReason: () => this.closeReason },
        onChange: (cb) => this.onChange(cb),
        ...(context ? { context } : {}),
        reply: (r) => { if (counted) { this.changes++; this.emit(); } this.reply(id, r); if (before && (r as any)?.ok === true && (r as any).ended === "done") void this.builtHere(before, g0, v0); }, fail: (c, m) => this.fail(id, c, m),
      });
    } finally {
      this.inFlight--;
    }
  }

  /** A .tex this agent built: its run once by itself, if it is still the revision it was before the build, under the
   * same grant, in force now (a write meanwhile, the person's or the agent's: not this build's, nothing). */
  private async builtHere(e: any, g: Grant | null, v: AgentVerbs | null) {
    if (!g || !v || e?.kind !== "file" || typeof e.fid !== "string" || typeof e.rev !== "number" || !/\.tex$/i.test(e.path ?? "")) return;
    const now = await v.stat(e.path).catch(() => null);
    if (!now || now.fid !== e.fid || now.rev !== e.rev || !this.current(g, v)) return;
    this.built = Object.freeze({ op: newGrantId(12), path: e.path, kind: "file" as const, grant: g.id ?? "", fid: e.fid, rev: e.rev });
    this.texTell(this.built);
  }
  /** Said to the editors: this agent made this .tex at this revision (one showing it asks). */
  private texTell(c: Created) {
    if (isTex(c)) try { this.texChan?.postMessage({ t: "tex-made", fid: c.fid, rev: c.rev } satisfies TexMade); } catch {}
  }
  /** An editor's question (agent-made-tex.ts): yes, once, if the file at that revision is the .tex this agent last
   * created or built, and it may run by itself now (mayRunCreated: the same conditions as a created notebook's). */
  private texAsked(m: unknown) {
    const q = m as TexMayRun;
    if (!q || q.t !== "tex-may-run" || typeof q.id !== "string" || typeof q.fid !== "string" || typeof q.rev !== "number") return;
    const c = [this.built, this.created].find((x) => isTex(x) && x.fid === q.fid && x.rev === q.rev);
    // (spent by the file's revision: its creation and a build at the same revision are one chance, not two)
    const at = q.fid + "@" + q.rev;
    if (!c || this.texSpent.has(at) || !this.mayRunCreated(c)) return;
    this.texSpent.add(at);
    try { this.texChan?.postMessage({ t: "tex-may-run", id: q.id.slice(0, 64), ok: true } satisfies TexMayRunYes); } catch {}
  }

  /** git_branch (chat plan PR 3): the page's, for this grant, while it is the one in force. */
  private async branch(g: Grant, verbs: AgentVerbs, name: string): Promise<unknown> {
    const h = this.hello!;
    const out = await this.opts.gitBranch!.run({ actor: actorOf(h.agent.name, h.agent.client), name, owner: g.id, folders: g.folders, live: () => this.current(g, verbs) });
    this.changes++;
    this.emit();
    return out;
  }

  /** A document created by this agent: kept for the bar's Open, and told to the page (onCreated). Never a folder, a
   * branch's worktree or the Trash: only what the person would open from Files. */
  private madeHere(e: any, g: Grant) {
    if (!e || typeof e.path !== "string" || !/^(notebook|board|file)$/.test(e.kind) || within(norm(e.path) ?? "/", BRANCHES) || /^\/Trash(\/|$)/.test(e.path)) return;
    this.created = Object.freeze({ op: newGrantId(12), path: e.path, kind: e.kind, ...(typeof e.ref === "string" ? { ref: e.ref } : {}), grant: g.id ?? "", ...(typeof e.updated === "number" ? { updated: e.updated } : {}),
      ...(e.kind === "file" && typeof e.fid === "string" && typeof e.rev === "number" ? { fid: e.fid, rev: e.rev } : {}) });
    this.emit();
    this.texTell(this.created!);
    try { this.opts.onCreated?.(this.created, this); } catch (err) { console.warn("agent: the page's open of a created document failed:", err); }
  }

  /** Whether `c` may run once by itself now, asked as the page admits that run (the conditions decided Nov 18 2026): it is
   * the last document this pairing created (or, a .tex, the last it built: Nov 19 2026), under the grant still in force,
   * and that grant has May run code and Everything. Any narrower grant never: the page's interpreter reads the whole
   * workspace, beyond the grant's folders. */
  mayRunCreated(c: Created): boolean {
    const g = this.grant;
    return this.state === "granted" && (this.created === c || this.built === c) && !!g && g.id === c.grant && g.run === true && g.folders.length === 1 && g.folders[0] === "/" && grantProblem(g, this.now()) === null;
  }

  private async run(v: AgentVerbs, verb: string, p: any, expect?: TrashEntry, made?: (e: unknown) => void): Promise<unknown> {
    const sized = (c: any) => contentIn(c, p.path ?? "contents");
    const changed = <T,>(x: T) => { this.changes++; this.emit(); return x; };
    // (the address of a single entry's page in its answer (entryOut): stat, read, write, create, rename, duplicate and
    //  restore; not list's entries, nor a folder's, a removed one's or a data file's, which have no page of their own)
    const url = this.opts.page.origin;
    switch (verb) {
      case "list": {
        const all = await v.list(p.folder, p.recursive ? { recursive: true } : {});
        const from = p.cursor === undefined ? 0 : /^[0-9]{1,9}$/.test(p.cursor) ? Number(p.cursor) : NaN;
        if (!Number.isFinite(from)) throw new AgentError("invalid", "not a cursor this page gave");
        const page = all.slice(from, from + AGENT_LIMITS.maxList).map((e) => entryOut(e));
        return from + page.length < all.length ? { entries: page, more: true, cursor: String(from + page.length) } : { entries: page };
      }
      case "stat": return { entry: entryOut(await v.stat(p.path), url) };
      case "read": {
        const r = await v.read(p.path);
        if (r.entry.kind === "folder") throw new AgentError("invalid", `${p.path} is a folder: list it`);
        // (a notebook's ref, for an edit by cell: the document read, so an edit never reaches another put at its path)
        return { entry: entryOut(r.entry, url), rev: r.rev, content: contentOut(r.entry.kind, r.content, p.path), ...(this.edits() && r.entry.kind === "notebook" && typeof r.entry.ref === "string" ? { ref: r.entry.ref } : {}) };
      }
      case "write": {
        // (an agent that edits notebooks by cell never rewrites one whole: that would drop its outputs, A12)
        if (this.edits() && /\.ipynb$/i.test(String(p.path))) throw new AgentError("invalid", `${p.path} is a notebook: change it with workspace_edit_notebook (by cell, its outputs kept), not a whole write`);
        const r = await v.write(p.path, sized(p.content), p.base !== undefined ? { base: p.base } : {}); return changed({ entry: entryOut(r.entry, url), rev: r.rev }); }
      case "create": { const e = await v.create(p.path, { ...(p.content ? { content: sized(p.content) } : {}), ...(p.mode ? { mode: p.mode } : {}) }); made?.(e); return changed({ entry: entryOut(e, url) }); }
      case "mkdir": return changed({ entry: entryOut(await v.mkdir(p.path)) });
      case "rename": return changed({ entry: entryOut(await v.rename(p.from, p.to), url) });
      case "duplicate": return changed({ entry: entryOut(await v.duplicate(p.path, p.to), url) });
      case "remove": return changed({ entry: entryOut(await v.remove(p.path)) });
      // (only the very entry authorized: Workspace.restore checks it holding its lock, so one put in its place meanwhile isn't restored)
      case "restore": if (!expect) throw new AgentError("invalid", "restore without its authorized entry"); return changed({ entry: entryOut(await v.restore(p.path, expect), url) });
      case "history": {
        const all = await v.history(p.path);
        const from = p.cursor === undefined ? 0 : /^[0-9]{1,9}$/.test(p.cursor) ? Number(p.cursor) : NaN;
        if (!Number.isFinite(from)) throw new AgentError("invalid", "not a cursor this page gave");
        const page = all.slice(from, from + AGENT_LIMITS.maxHistory).map((x: any) => ({ t: x.t, size: x.size, sha256: x.sha256, by: x.by }));
        return from + page.length < all.length ? { versions: page, more: true, cursor: String(from + page.length) } : { versions: page };
      }
      case "version": return { content: contentOut("file", await v.version(p.path, p.index), `${p.path} version ${p.index}`) };
    }
    throw new AgentError("invalid", `not a verb: ${verb}`);
  }
}

// ---- the reload record (A14 plan r3.1 + r3.2): an unremembered grant survives a reload of the same page
// One record in sessionStorage per page, closed and bounded: the pairing, its session secret, the agent it was, and the
// grant exactly. It newly keeps an unremembered bearer secret for the page's life (remembered ones are in IndexedDB,
// longer). It is never in a URL, the chat, a toast, diagnostics or an export. A copy in another tab (window.open, a
// duplicated or restored tab) is independent: a consume here doesn't reach it, so each page's own checks decide.

export const RELOAD_KEY = "sb-agent-reload-v1";
// (the newest pairing's number on this page: only the newest writes or drops the record, A14 r3.1 §3)
let pairingGen = 0;
/** At most this long between the page leaving (pagehide) and its return, a reload or a navigation back to the same page
 * in this browsing context, for the reconnect to be silent (R1-b; A5 item 2, ruled Nov 20 2026: one constant). */
export const RETURN_MS = 10 * 60 * 1000;
const RELOAD_MAX = 4096;

export type ReloadRecord = {
  v: 1; pairingId: string; session: string; port: number;
  agent: { name: string; client: string };
  grant: { folders: string[]; write: boolean; run?: boolean; expires: number | null; id?: string };
  workspace: string; page: string; leftAt?: number;
};
/** The page a record belongs to: its workspace's store and its own address (R1-d). */
export type ReloadScope = { workspace: string; page: string };
type ReloadStorage = Pick<Storage, "getItem" | "setItem" | "removeItem">;

const isStr = (v: unknown, max: number): v is string => typeof v === "string" && v.length > 0 && v.length <= max;
const keysAre = (o: object, want: string[], optional: string[] = []) => {
  const k = Object.keys(o);
  return want.every((w) => k.includes(w)) && k.every((x) => want.includes(x) || optional.includes(x));
};

/** A record as kept, or null for anything else: the exact keys, each in its bounds (finite numbers only), its
 * folders as grantFolders gives them back. Fails closed: a record that isn't exactly this is no record. */
export function parseReloadRecord(raw: string | null): ReloadRecord | null {
  // (the bound in UTF-8 bytes, as stored, not UTF-16 code units: a non-ASCII record is counted as it is, S3)
  if (typeof raw !== "string" || raw.length > RELOAD_MAX || enc.encode(raw).length > RELOAD_MAX) return null;
  let v: any;
  try { v = parseStrict(raw); } catch { return null; }
  if (!v || typeof v !== "object" || Array.isArray(v)) return null;
  if (!keysAre(v, ["v", "pairingId", "session", "port", "agent", "grant", "workspace", "page"], ["leftAt"])) return null;
  if (v.v !== 1 || typeof v.pairingId !== "string" || !/^[0-9a-f]{24}$/.test(v.pairingId)) return null;
  if (typeof v.session !== "string" || !/^[A-Za-z0-9_-]{43}$/.test(v.session)) return null;
  if (!Number.isInteger(v.port) || v.port < 1 || v.port > 65535) return null;
  const a = v.agent, g = v.grant;
  if (!a || typeof a !== "object" || Array.isArray(a) || !keysAre(a, ["name", "client"])) return null;
  if (!isStr(a.name, 80) || typeof a.client !== "string" || a.client.length > 40) return null;
  if (!g || typeof g !== "object" || Array.isArray(g) || !keysAre(g, ["folders", "write", "expires"], ["id", "run"])) return null;
  // ("May run code": present only as true; a record without it is a grant that may not run code)
  if ("run" in g && g.run !== true) return null;
  if ("id" in g && !(typeof g.id === "string" && GRANT_ID.test(g.id))) return null;
  if (!Array.isArray(g.folders) || g.folders.length < 1 || g.folders.length > 64 || !g.folders.every((f: unknown) => isStr(f, 512))) return null;
  if (typeof g.write !== "boolean") return null;
  if (g.expires !== null && !(typeof g.expires === "number" && Number.isFinite(g.expires))) return null;
  let folders: string[];
  try { folders = grantFolders(g.folders); } catch { return null; }
  if (folders.length !== g.folders.length || folders.some((f, i) => f !== g.folders[i])) return null;
  if (!isStr(v.workspace, 256) || !isStr(v.page, 256)) return null;
  if ("leftAt" in v && !(typeof v.leftAt === "number" && Number.isFinite(v.leftAt))) return null;
  return v as ReloadRecord;
}

/** What a page may do with a parsed record:
 *  - "silent": reconnect now, with no gesture: a reload, or a navigation back to the same page in this browsing context
 *    (leaving for Files and coming back), within RETURN_MS of leaving, the same scope, the grant not expired (R1-a..e;
 *    A5 item 2, design r3, SEC-cleared Nov 20 2026). A copy of the record in a duplicated, restored or window.open tab is
 *    taken once there too: the agent's one live page decides between them;
 *  - "click": keep it in memory for one [Reconnect]: a reload, the same scope, not expired, only older than RETURN_MS;
 *  - "discard": never usable: another workspace or page, the grant over, a record with no leftAt (as a copy taken
 *    while its page lived has), any other navigation type, or a navigation back older than RETURN_MS: those need a new
 *    Allow unless the grant was remembered. */
export function reloadDecision(r: ReloadRecord, o: { scope: ReloadScope; navType: string; now: number }): "silent" | "click" | "discard" {
  if (r.workspace !== o.scope.workspace || r.page !== o.scope.page) return "discard";
  if (r.grant.expires !== null && !(o.now < r.grant.expires)) return "discard";
  if (r.leftAt === undefined || !(o.navType === "reload" || o.navType === "navigate" || o.navType === "back_forward")) return "discard";
  const age = o.now - r.leftAt;
  if (age >= 0 && age <= RETURN_MS) return "silent";
  return o.navType === "reload" ? "click" : "discard";
}

/** What taking the record found (S1): "none", no storage or no entry (genuinely absent); "bad", an entry this page
 * may not use: unreadable, not removable (consumed before any attempt, R1-c, or not at all), or not exactly a
 * record; "ok", the record, already removed. A "bad" take is never silently replaced by another grant. */
export type ReloadTake = { kind: "none" } | { kind: "bad" } | { kind: "ok"; record: ReloadRecord };
/** The record, taken: read, removed at once (before any attempt, R1-c, this page only), then parsed. Fails closed: an
 * entry that can't be read or removed is "bad", never used. */
export function takeReloadRecord(s: ReloadStorage | null, scope?: ReloadScope): ReloadTake {
  if (!s) return { kind: "none" };
  let raw: string | null = null;
  try { raw = s.getItem(RELOAD_KEY); } catch { return { kind: "bad" }; }
  if (raw === null) return { kind: "none" };
  // (another page's record (the Agents page's, while the person is on a board): left alone, for that page to take when
  //  they go back to it; A5. This page's own, or one that can't be read: taken, as before)
  if (scope) {
    const r = parseReloadRecord(raw);
    if (r && r.page !== scope.page) return { kind: "none" };
  }
  try { s.removeItem(RELOAD_KEY); } catch { return { kind: "bad" }; }
  const record = parseReloadRecord(raw);
  return record ? { kind: "ok", record } : { kind: "bad" };
}
/** The record written (or, with null, removed). Only a record the reader would take back exactly is written (its
 * shape and its byte bound, S3); anything else is not stored, and any older entry goes: the live grant itself is
 * never cut to fit. */
export function putReloadRecord(s: ReloadStorage | null, r: ReloadRecord | null): void {
  if (!s) return;
  const raw = r ? JSON.stringify(r) : null;
  const fits = raw !== null && parseReloadRecord(raw) !== null;
  try { if (fits) s.setItem(RELOAD_KEY, raw!); else s.removeItem(RELOAD_KEY); } catch { /* (no storage: no restore) */ }
}
/** On pagehide: the time the page left, on the record it holds: a valid record of this page's own scope (workspace and
 * page) only. Another page's record (the Agents page's, while the person is on a board) is left byte for byte as it
 * is: a page passed through on the way never renews another page's window (A5). */
export function markReloadLeft(s: ReloadStorage | null, now: number, scope: ReloadScope): void {
  if (!s) return;
  let r: ReloadRecord | null = null;
  try { r = parseReloadRecord(s.getItem(RELOAD_KEY)); } catch { return; }
  if (r && r.workspace === scope.workspace && r.page === scope.page) putReloadRecord(s, { ...r, leftAt: now });
}

// Delegate's requests from the page to the agent: the transport of pair-delegate-plan-r3.3 §2.5 (P0, frozen), groundwork
// rather than all of its enforcement. JSON-RPC requests over the pairing (AgentPairing.own), with ids "p<n>" (the hello is
// "p1"), only to an agent whose negotiated hello lists DELEGATE_FEATURE, only these methods, at most
// TASK_REQUESTS.pending at once. Each request the page sends, and each answer's raw frame as received (its envelope,
// whitespace and multibyte characters counted), at most TASK_REQUESTS.frameBytes; an answer over it is refused
// ("too_large") before its result or error reaches the caller (the pairing's own frames keep their own bound). Each is
// rejected with "timeout" if no answer comes within its time: a bound on waiting, not a promise that the agent answers.
// Every pending one ends with the pairing. Its own module, so the pages that don't offer Delegate (the LaTeX editor's
// pairing) carry none of it.
// The grant's delegate:true (the Agents page's switch, AgentPairing.setDelegate) is checked here before each request,
// and by the agent always. Not here: §2.5's schema of each result, which every caller checks before any use.
import { AgentError, type AgentPairing } from "./agent-pair";

export const DELEGATE_FEATURE = "delegate.1";
export const TASK_METHODS: readonly string[] = ["tasks.start", "tasks.list", "tasks.get", "tasks.diff", "tasks.file", "tasks.merged", "tasks.close", "tasks.ask", "tasks.stop", "tasks.revoke", "tasks.resume", "tasks.answer"];
export const TASK_REQUESTS = Object.freeze({ pending: 8, frameBytes: 4 * 2 ** 20, timeoutMs: 30_000, longMs: 120_000, long: ["tasks.start", "tasks.merged"] as readonly string[] });

const enc = new TextEncoder();
// (one client per pairing: its ids are the pairing's)
const clients = new WeakMap<AgentPairing, TaskClient>();

export class TaskClient {
  private next = 1;
  private pending = new Map<string, { resolve: (r: unknown) => void; reject: (e: AgentError) => void; timer: ReturnType<typeof setTimeout> }>();
  private out: { send(m: unknown): "ok" | "closed" | "over" | "link" };
  private unwatch: () => void;

  /** The pairing's client (made on first use). */
  static of(p: AgentPairing): TaskClient {
    let c = clients.get(p);
    if (!c) { c = new TaskClient(p); clients.set(p, c); }
    return c;
  }
  private constructor(private p: AgentPairing) {
    this.out = p.own((msg, bytes) => this.answered(msg, bytes));
    // (the pairing's end ends every pending request)
    this.unwatch = p.onChange(() => { if (p.state === "closed") this.endAll(p.closeReason || "the agent isn't connected"); });
  }

  /** Whether this pairing's agent offers Delegate. */
  offered(): boolean { return !!this.p.hello?.features?.includes(DELEGATE_FEATURE); }

  /** One request: its result, or an AgentError whose code is the agent's (data.code), or the page's own:
   * "unavailable" (over a runner: M1 is loopback only), "closed" (not granted, or the pairing ended), "forbidden" (the
   * agent doesn't offer delegate.1), "bad_request" (not one of TASK_METHODS), "busy" (TASK_REQUESTS.pending already),
   * "too_large" (the message over TASK_REQUESTS.frameBytes or the connection's bound), "timeout". */
  request(method: string, params: Record<string, unknown>, o: { timeoutMs?: number } = {}): Promise<unknown> {
    const no = (code: string, why: string) => Promise.reject(new AgentError(code, why));
    if (this.p.link) return no("unavailable", "Delegate works only with an agent on this computer for now");
    if (this.p.state !== "granted") return no("closed", "the agent isn't connected");
    if (!this.offered()) return no("forbidden", "this agent doesn't offer Delegate");
    if (this.p.grant?.delegate !== true) return no("forbidden", "Delegate tasks aren't turned on for this agent");
    if (!TASK_METHODS.includes(method)) return no("bad_request", "not a Delegate request");
    if (this.pending.size >= TASK_REQUESTS.pending) return no("busy", "too many requests to the agent at once");
    const id = "p" + ++this.next;
    const m = { jsonrpc: "2.0", id, method, params };
    const text = JSON.stringify(m);
    if (text.length > TASK_REQUESTS.frameBytes || enc.encode(text).length > TASK_REQUESTS.frameBytes) return no("too_large", "the request is over the connection's limit");
    const sent = this.out.send(m);
    if (sent !== "ok") return sent === "over" ? no("too_large", "the request is over the connection's limit") : sent === "link" ? no("unavailable", "Delegate works only with an agent on this computer for now") : no("closed", "the agent isn't connected");
    const ms = o.timeoutMs ?? (TASK_REQUESTS.long.includes(method) ? TASK_REQUESTS.longMs : TASK_REQUESTS.timeoutMs);
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { if (this.pending.delete(id)) reject(new AgentError("timeout", "the agent didn't answer in time")); }, ms);
      this.pending.set(id, { resolve, reject, timer });
    });
  }

  private answered(msg: any, bytes: number): boolean {
    const r = this.pending.get(msg.id);
    if (!r) return false;
    this.pending.delete(msg.id);
    clearTimeout(r.timer);
    // (an answer's raw frame over §2.5's bound: refused, its result or error never handed on)
    if (bytes > TASK_REQUESTS.frameBytes) { r.reject(new AgentError("too_large", "the agent's answer is over the limit")); return true; }
    if (msg.error !== undefined) {
      const code = typeof msg.error?.data?.code === "string" ? msg.error.data.code.slice(0, 40) : "error";
      r.reject(new AgentError(code, String(msg.error?.message ?? "refused").slice(0, 300)));
    } else r.resolve(msg.result);
    return true;
  }
  private endAll(why: string) {
    for (const [id, r] of [...this.pending]) { clearTimeout(r.timer); this.pending.delete(id); r.reject(new AgentError("closed", why)); }
    this.unwatch();
  }
}

// What the page accepts from a Delegate host (design/workspace-agent-protocol.md §6.1, `delegate.1`), checked closed
// before any use: each tasks.* result has exactly its listed keys, each value its rule, and an event is one of the
// listed kinds; anything else is refused (TaskShapeError), never shown. The agent checks the page's requests with the
// same rules on its side (sagebrush-agent lib/tasks-schema.mjs).
//
// One reading of §6.1 where it is open: a list entry's and a diff's `round` may be 0 (no proposal yet; the base), as the
// host gives them. A chat turn event inside a task (§6.1 "the chat turn events", the kinds of agent-chat/events.ts) is
// checked here closed too: each kind's fields exactly, each bounded. All text, every field, must be well formed (no lone
// surrogate: §2's common rule).

export class TaskShapeError extends Error {}
const bad = (m: string): never => { throw new TaskShapeError(m); };

export const TASK_STATUSES = ["working", "proposal", "merged", "closed", "failed", "interrupted"] as const;
export type TaskStatus = (typeof TASK_STATUSES)[number];
export const TASK_LIMITS = Object.freeze({ list: 64, title: 200, text: 64 * 1024, reason: 1024, files: 2000, path: 1024, component: 255, doc: 4 * 2 ** 20 });

const HEX32 = /^[0-9a-f]{32}$/, HEX40 = /^[0-9a-f]{40}$/;
const enc = new TextEncoder();
const isObj = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === "object" && !Array.isArray(v) && Object.getPrototypeOf(v) === Object.prototype;
function keys(v: unknown, want: readonly string[], what: string, optional: readonly string[] = []): Record<string, unknown> {
  if (!isObj(v)) return bad(`${what} isn't an object`);
  for (const k of Object.keys(v)) if (!want.includes(k) && !optional.includes(k)) bad(`${what}: unknown field ${JSON.stringify(k.slice(0, 40))}`);
  for (const k of want) if (!Object.hasOwn(v, k)) bad(`${what}: missing ${k}`);
  return v;
}
const task = (v: unknown, what = "task") => (typeof v === "string" && HEX32.test(v) ? v : bad(`${what} isn't 32 lowercase hex`));
const oid = (v: unknown, what: string) => (typeof v === "string" && HEX40.test(v) ? v : bad(`${what} isn't 40 lowercase hex`));
const oidOrNull = (v: unknown, what: string) => (v === null ? null : oid(v, what));
const int = (v: unknown, min: number, what: string) => (typeof v === "number" && Number.isSafeInteger(v) && v >= min ? v : bad(`${what} isn't an integer of at least ${min}`));
const bool = (v: unknown, what: string) => (typeof v === "boolean" ? v : bad(`${what} isn't true or false`));
// (§2 and §3: text is well formed, with no lone surrogate and no NUL; one check for every text field. Binary documents
//  come as {base64})
const LONE_SURROGATE = /[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/;
const wellFormed = (v: string, what: string) => (LONE_SURROGATE.test(v) || v.includes("\u0000") ? bad(`${what} isn't well-formed text`) : v);
const text = (v: unknown, max: number, what: string) => (typeof v === "string" && enc.encode(v).length <= max ? wellFormed(v, what) : bad(`${what} isn't text of at most ${max} bytes`));
const status = (v: unknown, what = "status") => ((TASK_STATUSES as readonly unknown[]).includes(v) ? (v as TaskStatus) : bad(`${what} isn't a task status`));
// (§6.1's path rules, as the host's own checker has them (sagebrush-agent lib/task-paths.mjs pathProblem), and §2's
//  common rule that text is well formed: relative and normalized, no empty, "." or ".." component, no backslash,
//  ":" (drive or ADS), control character or NUL, no lone surrogate, no Windows reserved name (CON, NUL, COM1, ... with
//  any extension), no component ending in a space or dot, no .git (any case) or .sagebrush component, each component at
//  most 255 bytes and the path at most 1,024)
const RESERVED = /^(con|prn|aux|nul|com[0-9\u00b9\u00b2\u00b3]|lpt[0-9\u00b9\u00b2\u00b3])(\..*)?$/i;
function path(v: unknown, what: string): string {
  if (typeof v !== "string" || v === "" || enc.encode(v).length > TASK_LIMITS.path) return bad(`${what} isn't a path of 1 to ${TASK_LIMITS.path} bytes`);
  wellFormed(v, what);
  if (v.startsWith("/") || /[\\:\x00-\x1f\x7f]/.test(v)) bad(`${what} isn't relative, or has a backslash, colon or control character`);
  for (const c of v.split("/")) {
    if (c === "" || c === "." || c === "..") bad(`${what} has an empty, . or .. component`);
    if (enc.encode(c).length > TASK_LIMITS.component) bad(`${what} has a component over ${TASK_LIMITS.component} bytes`);
    if (c.toLowerCase() === ".git" || c === ".sagebrush") bad(`${what} has a .git or .sagebrush component`);
    if (RESERVED.test(c) || /[ .]$/.test(c)) bad(`${what} has a Windows reserved name, or a component ending in a space or dot`);
  }
  return v;
}
function kindFor(p: string, v: unknown, what: string): "notebook" | "file" {
  if (v !== "notebook" && v !== "file") return bad(`${what} isn't "notebook" or "file"`);
  if ((v === "notebook") !== /\.ipynb$/.test(p)) bad(`${what}: a notebook's path ends .ipynb, and only a notebook's`);
  return v;
}

export type TaskEntry = { task: string; title: string; status: TaskStatus; target: "local"; run: boolean; round: number; seq: number; proposal: string | null; question: boolean; updated: number };
export function taskEntry(v: unknown, what = "task"): TaskEntry {
  const o = keys(v, ["task", "title", "status", "target", "run", "round", "seq", "proposal", "question", "updated"], what);
  if (typeof o.title !== "string" || [...o.title].length > TASK_LIMITS.title) bad(`${what}.title isn't text of at most ${TASK_LIMITS.title} characters`);
  wellFormed(o.title as string, `${what}.title`);
  if (o.target !== "local") bad(`${what}.target isn't "local"`);
  return { task: task(o.task, `${what}.task`), title: o.title as string, status: status(o.status, `${what}.status`), target: "local", run: bool(o.run, `${what}.run`), round: int(o.round, 0, `${what}.round`), seq: int(o.seq, 0, `${what}.seq`), proposal: oidOrNull(o.proposal, `${what}.proposal`), question: bool(o.question, `${what}.question`), updated: int(o.updated, 0, `${what}.updated`) };
}

export type DiffFile = { path: string; kind: "notebook" | "file"; change: "added" | "modified" | "deleted"; base_blob: string | null; blob: string | null };
function diffFile(v: unknown, what: string): DiffFile {
  const o = keys(v, ["path", "kind", "change", "base_blob", "blob"], what);
  const p = path(o.path, `${what}.path`);
  const change = o.change === "added" || o.change === "modified" || o.change === "deleted" ? o.change : bad(`${what}.change isn't added, modified or deleted`);
  const base_blob = oidOrNull(o.base_blob, `${what}.base_blob`), blob = oidOrNull(o.blob, `${what}.blob`);
  // (each change with the blobs it has: added has no base, deleted has no proposal)
  if ((change === "added") !== (base_blob === null) || (change === "deleted") !== (blob === null)) bad(`${what}: its blobs don't match its change`);
  return { path: p, kind: kindFor(p, o.kind, `${what}.kind`), change, base_blob, blob };
}
function diffFiles(v: unknown, what: string): DiffFile[] {
  if (!Array.isArray(v) || v.length > TASK_LIMITS.files) return bad(`${what} isn't a list of at most ${TASK_LIMITS.files}`);
  const out = v.map((f, i) => diffFile(f, `${what}[${i}]`));
  // (one task's set of paths, as the host's pathSetProblem: none twice ignoring case, and none also another's folder)
  const seen = new Set<string>();
  for (const f of out) { const k = f.path.toLowerCase(); if (seen.has(k)) bad(`${what}: a path twice (case aside)`); seen.add(k); }
  for (const f of out) { const parts = f.path.toLowerCase().split("/"); for (let i = 1; i < parts.length; i++) if (seen.has(parts.slice(0, i).join("/"))) bad(`${what}: a path is also another's folder`); }
  return out;
}

/** A document's content as the host sends it: UTF-8 text, or {base64}; at most 4 MiB of bytes (§6.1: the text's UTF-8
 * bytes, or the base64's decoded bytes). */
export type TaskContent = string | { base64: string };
function content(v: unknown, what: string): TaskContent {
  if (typeof v === "string") {
    // (counted without encoding when it can't be under: 4 MiB of UTF-8 is at least 4 Mi / 3 UTF-16 units, at most 4 Mi)
    if (v.length > TASK_LIMITS.doc || enc.encode(v).length > TASK_LIMITS.doc) bad(`${what} is over ${TASK_LIMITS.doc} bytes`);
    return wellFormed(v, what);
  }
  if (isObj(v) && Object.keys(v).length === 1 && typeof v.base64 === "string" && /^[A-Za-z0-9+/]*={0,2}$/.test(v.base64) && v.base64.length % 4 === 0) {
    const pad = v.base64.endsWith("==") ? 2 : v.base64.endsWith("=") ? 1 : 0;
    if ((v.base64.length / 4) * 3 - pad > TASK_LIMITS.doc) bad(`${what} is over ${TASK_LIMITS.doc} bytes decoded`);
    return { base64: v.base64 };
  }
  return bad(`${what} isn't text or {base64}`);
}

/** Each tasks.* result, checked. */
export const TASK_RESULTS = {
  "tasks.start": (v: unknown) => { const o = keys(v, ["task", "base", "seq"], "result"); return { task: task(o.task), base: oid(o.base, "base"), seq: int(o.seq, 0, "seq") }; },
  "tasks.list": (v: unknown) => {
    const o = keys(v, ["tasks"], "result");
    if (!Array.isArray(o.tasks) || o.tasks.length > TASK_LIMITS.list) return bad(`tasks isn't a list of at most ${TASK_LIMITS.list}`);
    return { tasks: o.tasks.map((t, i) => taskEntry(t, `tasks[${i}]`)) };
  },
  "tasks.get": (v: unknown) => getResult(v, false),
  "tasks.diff": (v: unknown) => { const o = keys(v, ["task", "base", "commit", "round", "seq", "files"], "result"); return { task: task(o.task), base: oid(o.base, "base"), commit: oid(o.commit, "commit"), round: int(o.round, 0, "round"), seq: int(o.seq, 0, "seq"), files: diffFiles(o.files, "files") }; },
  "tasks.file": (v: unknown) => {
    const o = keys(v, ["blob", "content"], "result");
    return { blob: oid(o.blob, "blob"), content: content(o.content, "content") };
  },
  "tasks.merged": (v: unknown) => {
    const o = keys(v, ["recorded", "commit"], "result");
    if (o.recorded !== "merge" && o.recorded !== "receipt") bad('recorded isn\'t "merge" or "receipt"');
    const commit = oidOrNull(o.commit, "commit");
    if ((o.recorded === "merge") !== (commit !== null)) bad("a merge has its commit, and a receipt none");
    return { recorded: o.recorded as "merge" | "receipt", commit };
  },
  "tasks.close": (v: unknown) => { const o = keys(v, ["status"], "result"); return { status: status(o.status) }; },
  "tasks.ask": (v: unknown) => { const o = keys(v, ["status", "round"], "result"); return { status: status(o.status), round: int(o.round, 0, "round") }; },
  "tasks.stop": (v: unknown) => { const o = keys(v, ["status"], "result"); return { status: status(o.status) }; },
  "tasks.revoke": (v: unknown) => { const o = keys(v, ["status"], "result"); return { status: status(o.status) }; },
  "tasks.resume": (v: unknown) => { const o = keys(v, ["status"], "result"); return { status: status(o.status) }; },
  "tasks.answer": (v: unknown) => { const o = keys(v, ["accepted", "current"], "result"); return { accepted: bool(o.accepted, "accepted"), current: bool(o.current, "current") }; },
} as const;
export type TaskMethod = keyof typeof TASK_RESULTS;
export type TaskResult<M extends TaskMethod> = ReturnType<(typeof TASK_RESULTS)[M]>;

// (the chat turn events (agent-chat/events.ts's kinds), closed: per kind its required and optional fields, each checked;
//  `turn_id` may come with any of them)
const SHORT = 400, ID = 128, BIG = 4 * 2 ** 20, TEXT = 192 * 1024;
const idStr = (v: unknown, what: string) => (typeof v === "string" && v.length >= 1 && v.length <= ID && /^[\x21-\x7e]+$/.test(v) ? v : bad(`${what} isn't an id`));
const oneOf = <T extends string>(v: unknown, set: readonly T[], what: string): T => ((set as readonly unknown[]).includes(v) ? (v as T) : bad(`${what} isn't one of ${set.join(", ")}`));
type Field = (v: unknown, what: string) => unknown;
const T = (max: number): Field => (v, what) => text(v, max, what);
const N: Field = (v, what) => int(v, 0, what);
const I: Field = idStr;
const TURN: Record<string, [Record<string, Field>, Record<string, Field>]> = {
  turn_started: [{}, {}],
  turn_state: [{ state: T(SHORT) }, {}],
  message_revised: [{ message: I, revision: N }, {}],
  text_delta: [{ message: I, revision: N, text: T(TEXT) }, {}],
  message_truncated: [{ message: I, revision: N }, {}],
  thinking_delta: [{ text: T(TEXT) }, {}],
  tool_call_started: [{ call: I, tool: T(SHORT) }, { name: T(SHORT), summary: T(SHORT) }],
  tool_output: [{ call: I, text: T(TEXT) }, {}],
  tool_call_finished: [
    { call: I, status: T(SHORT), duration_ms: N },
    {
      summary: T(SHORT), body: T(BIG), body_cut: (v, w) => (v === true ? v : bad(`${w} isn't true`)),
      diff: (v, w) => { const o = keys(v, ["path", "before", "after"], w); return { path: text(o.path, 1024, `${w}.path`), before: text(o.before, BIG, `${w}.before`), after: text(o.after, BIG, `${w}.after`) }; },
    },
  ],
  attention: [{ id: I, kind: T(SHORT), state: (v, w) => oneOf(v, ["open", "approved", "denied"] as const, w), title: T(SHORT) }, { summary: T(SHORT), detail: T(64 * 1024), instance: I }],
  artifact: [{ id: I, kind: (v, w) => oneOf(v, ["markdown", "code", "diff", "notebook", "board"] as const, w), title: T(SHORT), body: T(BIG) }, { lang: T(64), path: T(1024) }],
  turn_usage: [{ usage: (v, w) => { const o = keys(v, ["input_tokens", "output_tokens"], w); return { input_tokens: int(o.input_tokens, 0, `${w}.input_tokens`), output_tokens: int(o.output_tokens, 0, `${w}.output_tokens`) }; } }, {}],
  turn_info: [{}, { model: T(SHORT), effort: T(64) }],
  turn_error: [{ code: T(64), message: T(64 * 1024) }, {}],
  turn_finished: [{ outcome: (v, w) => oneOf(v, ["completed", "interrupted", "error"] as const, w) }, { code: T(64) }],
};
function turnEvent(v: Record<string, unknown>, what: string): Record<string, unknown> {
  const [req, opt] = TURN[v.type as string];
  const o = keys(v, ["type", ...Object.keys(req)], what, [...Object.keys(opt), "turn_id"]);
  const out: Record<string, unknown> = { type: o.type };
  for (const [k, f] of Object.entries(req)) out[k] = f(o[k], `${what}.${k}`);
  for (const [k, f] of Object.entries(opt)) if (o[k] !== undefined) out[k] = f(o[k], `${what}.${k}`);
  if (o.turn_id !== undefined) out.turn_id = idStr(o.turn_id, `${what}.turn_id`);
  return out;
}

export type TaskEvent =
  | { type: "task_status"; status: TaskStatus; reason?: string }
  | { type: "proposal"; round: number; base: string; commit: string; files: DiffFile[] }
  | { type: "question"; qid: number; revision: number; text: string; blocking: boolean; choices?: string[] }
  | { type: "question_withdrawn"; qid: number; revision: number }
  | { type: "question_answered"; qid: number; revision: number; answer_id: string; current: boolean }
  | { type: "turn"; event: Record<string, unknown> };

/** One task event (§6.1), checked: a task's own, or a chat turn event (kind only; see above). */
export function taskEvent(v: unknown, what = "event"): TaskEvent {
  if (!isObj(v) || typeof v.type !== "string") return bad(`${what} isn't an event`);
  switch (v.type) {
    case "task_status": {
      const o = keys(v, ["type", "status"], what, ["reason"]);
      return { type: "task_status", status: status(o.status, `${what}.status`), ...(o.reason !== undefined ? { reason: text(o.reason, TASK_LIMITS.reason, `${what}.reason`) } : {}) };
    }
    case "proposal": {
      const o = keys(v, ["type", "round", "base", "commit", "files"], what);
      return { type: "proposal", round: int(o.round, 1, `${what}.round`), base: oid(o.base, `${what}.base`), commit: oid(o.commit, `${what}.commit`), files: diffFiles(o.files, `${what}.files`) };
    }
    case "question": {
      const o = keys(v, ["type", "qid", "revision", "text", "blocking"], what, ["choices"]);
      let choices: string[] | undefined;
      if (o.choices !== undefined) {
        if (!Array.isArray(o.choices) || o.choices.length > 16) bad(`${what}.choices isn't a list of at most 16`);
        choices = (o.choices as unknown[]).map((c, i) => text(c, 400, `${what}.choices[${i}]`));
      }
      return { type: "question", qid: int(o.qid, 1, `${what}.qid`), revision: int(o.revision, 1, `${what}.revision`), text: text(o.text, TASK_LIMITS.text, `${what}.text`), blocking: bool(o.blocking, `${what}.blocking`), ...(choices ? { choices } : {}) };
    }
    case "question_withdrawn": {
      const o = keys(v, ["type", "qid", "revision"], what);
      return { type: "question_withdrawn", qid: int(o.qid, 1, `${what}.qid`), revision: int(o.revision, 1, `${what}.revision`) };
    }
    case "question_answered": {
      const o = keys(v, ["type", "qid", "revision", "answer_id", "current"], what);
      return { type: "question_answered", qid: int(o.qid, 1, `${what}.qid`), revision: int(o.revision, 1, `${what}.revision`), answer_id: task(o.answer_id, `${what}.answer_id`), current: bool(o.current, `${what}.current`) };
    }
    default:
      if (Object.hasOwn(TURN, v.type)) return { type: "turn", event: turnEvent(v, what) };
      return bad(`${what}: not a task event (${JSON.stringify(v.type.slice(0, 40))})`);
  }
}

/** A task.event notification's params ({task, seq, event}), checked. */
export function taskNotification(v: unknown): { task: string; seq: number; event: TaskEvent } {
  const o = keys(v, ["task", "seq", "event"], "task.event");
  return { task: task(o.task), seq: int(o.seq, 1, "seq"), event: taskEvent(o.event) };
}

// (a task's log as the page shows it: everything around each event checked closed as above, and each event alone, so
//  an event this page refuses is kept as `refused` (its seq and why) and the rest of the log still shows)
export type TaskLogEntry = { seq: number; event: TaskEvent } | { seq: number; refused: string };
function eventOrRefused(seq: number, v: unknown, what: string, lenient: boolean): TaskLogEntry {
  if (!lenient) return { seq, event: taskEvent(v, what) };
  try { return { seq, event: taskEvent(v, what) }; } catch (e) { if (e instanceof TaskShapeError) return { seq, refused: e.message }; throw e; }
}
function getResult(v: unknown, lenient: boolean) {
  const o = keys(v, ["task", "events", "last", "reset"], "result");
  if (!Array.isArray(o.events)) return bad("events isn't a list");
  const events = o.events.map((e, i) => { const x = keys(e, ["seq", "event"], `events[${i}]`); return eventOrRefused(int(x.seq, 1, `events[${i}].seq`), x.event, `events[${i}].event`, lenient); });
  for (let i = 1; i < events.length; i++) if (events[i].seq <= events[i - 1].seq) bad("events aren't in increasing seq");
  return { task: taskEntry(o.task), events, last: int(o.last, 0, "last"), reset: bool(o.reset, "reset") };
}
/** tasks.get's result as the page shows it (above): each event checked alone. */
export const taskLog = (v: unknown): { task: TaskEntry; events: TaskLogEntry[]; last: number; reset: boolean } => getResult(v, true);
/** A task.event notification as the page shows it: its task and seq checked, and its event alone (above). */
export function taskNotice(v: unknown): { task: string } & TaskLogEntry {
  const o = keys(v, ["task", "seq", "event"], "task.event");
  return { task: task(o.task), ...eventOrRefused(int(o.seq, 1, "seq"), o.event, "event", true) };
}

/** A git blob id (SHA-1 of "blob <n>\0" + the bytes), for the page's check of what tasks.file gives. */
export async function blobId(bytes: Uint8Array): Promise<string> {
  const head = enc.encode(`blob ${bytes.length}\0`);
  const all = new Uint8Array(head.length + bytes.length);
  all.set(head);
  all.set(bytes, head.length);
  const h = new Uint8Array(await crypto.subtle.digest("SHA-1", all));
  return [...h].map((b) => b.toString(16).padStart(2, "0")).join("");
}
/** A task document's bytes: its text as UTF-8, or its base64 decoded. */
export function contentBytes(c: TaskContent): Uint8Array {
  if (typeof c === "string") return enc.encode(c);
  const bin = atob(c.base64), out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

#!/usr/bin/env node
// sagebrush-agent: chat with Claude in Sagebrush. Runs Claude on this computer
// (the Claude Agent SDK, with your own Claude login) and waits for a
// Sagebrush page to pair with it over the loopback address.
//
//   npx sagebrush-agent [--port N] [--origin https://...]
//
// Then open the link it prints (or enter the code and port in the page).
//
//   sagebrush-agent --stdio
//
// is how `sagebrush remote --serve-agents --agent-cmd ...` runs it: the page is
// reached through the runner, one JSON message per line on stdin and stdout
// (stdout carries nothing else). SIGINT stops the running turns; SIGTERM, or
// the end of stdin, stops the agent.
//
//   sagebrush-agent --codex --stdio
//
// runs Codex there instead: one pinned release, fetched and checked (never the
// `codex` on PATH), as `codex app-server` with that computer's Codex login and
// settings: only over the runner, and only for a connection with shell and files on.

import { AgentServer, DEFAULT_ORIGINS, TEXT } from "../lib/server.mjs";
import { stdinChunks } from "../lib/stdio.mjs";

// An exact http(s) origin, like https://example.org or http://127.0.0.1:8000: no path, no wildcard.
function exactOrigin(s) {
  let u;
  try { u = new URL(s); } catch { u = null; }
  if (!u || (u.protocol !== "https:" && u.protocol !== "http:") || u.origin !== s) {
    console.error(`--origin needs an exact origin like https://example.org (not ${JSON.stringify(s)})`);
    process.exit(2);
  }
  return s;
}

const args = process.argv.slice(2);
let port = 0;
let stdio = false;
let codex = false;
let loopbackFlags = false;
const origins = [...DEFAULT_ORIGINS];
for (let i = 0; i < args.length; i++) {
  if (args[i] === "--port") { port = Number(args[++i]); loopbackFlags = true; }
  else if (args[i] === "--origin") { origins.push(exactOrigin(String(args[++i]))); loopbackFlags = true; }
  else if (args[i] === "--stdio") stdio = true;
  else if (args[i] === "--codex") codex = true;
  else if (args[i] === "--help" || args[i] === "-h") {
    console.log("usage: sagebrush-agent [--port N] [--origin https://...]\n       sagebrush-agent [--codex] --stdio   (run by sagebrush remote --serve-agents)");
    process.exit(0);
  } else {
    console.error(`unknown argument: ${args[i]}`);
    process.exit(2);
  }
}
if (codex && !stdio) {
  console.error("--codex works only with --stdio: Codex is run by sagebrush remote --serve-agents, with shell and files on");
  process.exit(2);
}
if (stdio && loopbackFlags) {
  console.error("--stdio can't be used with --port or --origin: the runner is the only peer");
  process.exit(2);
}

let query, createServer, deleteSession;
// (native mode's permission mode: the SDK's own settings resolver and the CLI's trust filter, with the fake model too)
const { resolveSettings, filterEscalatingDefaultMode } = await import("@anthropic-ai/claude-agent-sdk");
const resolver = { resolveSettings, filterEscalatingDefaultMode };
if (process.env.SAGEBRUSH_AGENT_FAKE === "1") {
  // The fake model, for tests: chosen only by this variable, set where the agent is started; nothing the page or
  // the runner sends can choose it.
  const fake = await import("../lib/fake.mjs");
  ({ fakeQuery: query, fakeCreateServer: createServer } = fake);
  console.error("FAKE model: no Claude, for testing");
} else {
  const sdk = await import("@anthropic-ai/claude-agent-sdk");
  query = sdk.query;
  deleteSession = sdk.deleteSession;
  createServer = (spec) => sdk.createSdkMcpServer({ name: spec.name, version: spec.version, tools: spec.tools.map(([name, description, shape, handler]) => sdk.tool(name, description, shape, handler)) });
}

if (stdio) {
  const server = new AgentServer({ query, deleteSession, stdio: true, resolver, ...(codex ? { name: "Codex", client: "codex-app-server" } : {}) });
  server.createServer = createServer;
  if (codex) {
    const { CodexBackend } = await import("../lib/codex.mjs");
    // (the fake app-server, for tests: chosen only by SAGEBRUSH_AGENT_FAKE=1, like the fake model)
    // (the real one: the pinned Codex, fetched and checked by the backend, never `codex` from PATH)
    const command = process.env.SAGEBRUSH_AGENT_FAKE === "1" ? [process.execPath, new URL("../lib/fake-codex.mjs", import.meta.url).pathname] : null;
    server.backend = new CodexBackend(server, { command });
  }
  let stopping = false;
  const stop = async (code = 0) => {
    if (stopping) return;
    stopping = true;
    let problems;
    try { problems = await server.close(); } catch (e) { problems = [String(e?.message ?? e)]; }
    for (const p of problems) console.error(p);
    process.exit(problems.length ? 1 : code);
  };
  const fatal = (text) => { console.error(text); stop(1); };
  // (a runner that went away: nothing more can be written)
  process.stdout.on("error", () => stop(0));
  process.on("SIGINT", () => server.stopTurns());
  process.once("SIGTERM", () => stop(0));
  await server.serveStdio({ input: stdinChunks(), output: process.stdout, fatal });
  if (!server.stdioStarted) fatal(TEXT.badStart);
  else stop(0);
} else {
await listenLoopback();
}

async function listenLoopback() {
const server = new AgentServer({ port, origins, query, deleteSession });
server.createServer = createServer;
// Delegate tasks (design/workspace-agent-protocol.md §6), over this loopback pairing only: on where the tasks folder
// (~/.sagebrush/tasks) can be used, else off, saying why.  The page shows Delegate only under the person's own switch.
// (with the fake model, for tests: only in the folder SAGEBRUSH_TASKS_HOME names, else off; never the real home)
const fakeHome = process.env.SAGEBRUSH_AGENT_FAKE === "1" ? process.env.SAGEBRUSH_TASKS_HOME || null : undefined;
if (fakeHome !== null) try {
  const { TaskStore } = await import("../lib/tasks.mjs");
  const { TaskTurns, claudeProjects } = await import("../lib/task-turns.mjs");
  const { TaskRpc } = await import("../lib/task-rpc.mjs");
  const { installationId } = await import("../lib/installation.mjs");
  const { join } = await import("node:path");
  const store = fakeHome
    ? new TaskStore({ root: join(fakeHome, ".sagebrush", "tasks"), scope: installationId(fakeHome), transcripts: claudeProjects({ CLAUDE_CONFIG_DIR: join(fakeHome, ".claude") }) }).init()
    : new TaskStore({ scope: installationId(), transcripts: claudeProjects() }).init();
  // (the runner: refuses every run in this version, saying why; RUNS_ENABLED is turned on only by a reviewed change)
  const { TaskRunner } = await import("../lib/task-runner.mjs");
  const turns = new TaskTurns({ store, query, createServer, log: (m) => console.error(m), runner: new TaskRunner({ store }) });
  server.setTasks({ store, turns, rpc: new TaskRpc({ store, turns }) });
} catch (e) {
  console.error(`Delegate tasks are off on this computer: ${e?.message ?? e}`);
}
const p = await server.listen();
const code = server.newCode();
// SAGEBRUSH_AGENT_PAGE changes only the printed link, never the allowed origins.
const page = (process.env.SAGEBRUSH_AGENT_PAGE ?? "https://sagebrush.space/agents/").replace(/\/?$/, "/");
if (!/^https?:$/.test(new URL(page, "x:/").protocol)) {
  console.error("SAGEBRUSH_AGENT_PAGE must be an http(s) URL");
  process.exit(2);
}
console.log(`
Sagebrush agent: Claude on this computer, waiting for your Sagebrush page.

  Open:  ${page}?pair=${code}&port=${p}
  (or enter code ${code} and port ${p} in the page)

The code works once, for 5 minutes; a new one is printed here each time the page goes away.
Claude uses your own Claude login, and only the workspace files you allow in the page.
Press Ctrl+C to stop (this run's conversation transcripts are deleted then).
`);
// (a fresh one-time link each time the page goes away. A new code ends only the old code; it never ends the page's
//  session or a running turn. (No terminal input is read: a background job reading its terminal would be stopped.))
const fresh = (why) => {
  const c = server.newCode();
  console.log(`
${why} To connect a page, open:

  ${page}?pair=${c}&port=${p}
  (or enter code ${c} and port ${p} in the page)

The code works once, for 5 minutes. A page that reconnects by itself doesn't need it.
`);
};
server.onPageGone = () => fresh("The page disconnected; Claude's turns go on.");

const stop = async () => {
  console.error("stopping: deleting this run's transcripts ...");
  let problems;
  try { problems = await server.close(); } catch (e) { problems = [String(e?.message ?? e)]; }
  for (const p of problems) console.error(`  ${p}`);
  console.error(problems.length ? "stopped, but see above." : "stopped; this run's transcripts are deleted.");
  process.exit(problems.length ? 1 : 0);
};
process.once("SIGINT", stop);
process.once("SIGTERM", stop);
}

// The daemon: a WebSocket server on the loopback address that one Sagebrush
// page pairs with (design/workspace-agent-protocol.md §2: a one-time code,
// the Origin and Host checked), and Claude, run through the Claude Agent SDK
// on this computer with the person's own Claude login.
//
// Claude's only tools on files are the workspace's (workspace_*): each call
// goes to the page, which checks it against the person's grant and does it in
// the workspace in the browser. Claude gets none of this computer's files,
// shell or settings.
//
// All work belongs to a binding: the paired socket plus the grant it last
// sent. A new hello, a grant change or a disconnect ends the binding, and with
// it every running turn, queued message, tool call and open question: nothing
// started under one binding runs under a later one.
//
// With --stdio the page is reached through `sagebrush remote` instead (the
// runner's agent channel): one JSON message per line on stdin and stdout, the
// runner's control lines ({"relay": ...}: start, then page attached and page
