        const ids = [...(a.set ?? []).map((x) => x.id), ...(a.remove ?? []), ...(a.insert ?? []).map((x) => x.after).filter((x) => x !== null)];
        const was = Object.fromEntries(ids.filter((id) => read.hashes.has(id)).map((id) => [id, read.hashes.get(id)]));
