  // ---- the run record (run.json, beside task.json): which run may be alive, and what it goes back to
  /** Record a run before it starts (`pid` null) and again once started (its pid, which is its process group, and the
   * process's start time): written whole (a temporary file, fsynced, renamed), so a crash leaves the old one or the
   * new one. */
  writeRunRecord(task, rec) {
    if (!runRecordOk(rec)) throw new Error("not a run record");
    const dir = this.dir(task), path = join(dir, "run.json"), tmp = `${path}.${process.pid}.tmp`;
    const fd = openSync(tmp, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | (constants.O_NOFOLLOW ?? 0), 0o600);
