    try { if (lstatSync(path).isFile()) { rmSync(path); git.syncDir(this.dir(task)); } } catch {}
  }
  // (at load, a task's run record, if any: a run from before the agent stopped.  Its process, if one is recorded and
  //  is still that process (its start time the recorded one), is killed by group and waited for, at most runGoneMs;
  //  a process id whose start time differs is another process now, never signalled.  Once no writer can be left, the
  //  copy goes back to the run's snapshot, the run's tmp is removed and the record cleared.  Returns why the task must
  //  be left as it is, or null)
  #reconcileRun(dir) {
    const path = join(dir, "run.json");
    try { lstatSync(path); } catch (e) { return e?.code === "ENOENT" ? null : `its run record can't be read (${e?.code ?? e})`; }
    let rec;
    try { rec = parseCanonical(git.readPlain(path, 4096).toString("utf8")); } catch { rec = null; }
    if (!runRecordOk(rec)) return "its run record isn't one: a run from before may still be running, so nothing is touched";
    // (recorded before its start and never after: it may have started (the agent died between the two writes), and
    //  nothing ties a process to it: unknown, so nothing is signalled or put back. The way out is the person's: deleting
    //  the task's folder)
    if (rec.pid === null) return "a run from before may have started, and it can't be told whether it has ended: nothing is touched (delete the task's folder to discard it)";
    if (rec.pid !== null) {
      // (only a definite "no such process" counts as gone; a process that can't be told apart is left alone)
      const now = procInfo(rec.pid);
      if (now.unknown) return `a run from before may still be running (${now.unknown}): nothing is touched until it can be told ended`;
      if (!now.gone) {
        if (rec.start === null) return "a run from before may still be running (its start time wasn't recorded): nothing is touched until it has ended";
        if (now.start === rec.start) {
          if (now.pgid !== rec.pid) return "a run from before is still running, outside its own process group: nothing is touched until it has ended";
          try { this.signal(-rec.pid, "SIGKILL"); } catch {}
          const until = Date.now() + this.runGoneMs;
          while (groupAlive(rec.pid) && Date.now() < until) Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 50);
          if (groupAlive(rec.pid)) return "a run from before is still running after being stopped: nothing is touched until it has ended";
        }
      }
    }
    this.#finishUndo(dir);
    try { this.#restore(dir, rec.snapshot); } catch (e) { return `the copy couldn't be put back as it was before a run from before (${e?.code ?? e?.message ?? e})`; }
    const tmp = join(dir, "tmp", rec.tmp);
    if (!plainDirProblem(tmp)) rmSync(tmp, { recursive: true, force: true });
    try { rmSync(path); git.syncDir(dir); } catch {}
    return null;
  }
  // (restoreWork renames work/ to .dropped-<tag>, then .work-<tag> (built whole before that first rename) to work/: a
  //  crash between the two leaves no work/.  Then the undo is finished: .work-<tag> becomes work/, the one paired with a
  //  .dropped-<tag> first; with none, the run's copy (.dropped-<tag>) is put back.  Never both deleted: with neither,
  //  nothing is done here, and the task fails on its records, kept)
  #finishUndo(dir) {
    const work = join(dir, "work");
    try { lstatSync(work); return; } catch (e) { if (e?.code !== "ENOENT") return; }
    let names;
    try { names = readdirSync(dir).filter((n) => /^\.(work|dropped)-[0-9a-f]{12}$/.test(n) && !plainDirProblem(join(dir, n))).sort(); } catch { return; }
    const fresh = names.filter((n) => n.startsWith(".work-"));
    const from = fresh.find((n) => names.includes(`.dropped-${n.slice(6)}`)) ?? fresh[0] ?? names.find((n) => n.startsWith(".dropped-"));
    if (!from) return;
    try { renameSync(join(dir, from), work); git.syncDir(dir); } catch {}
  }
  // (what a crash during a run or a restore can leave: the run tmp folders and a half-built or dropped copy; only plain
  //  folders of those names are removed, and only while work/ itself is a plain folder: never the last copy)
  #dropRunLeftovers(id) {
    const dir = this.dir(id), tmp = join(dir, "tmp");
    if (plainDirProblem(join(dir, "work"))) return;
    try {
      for (const name of readdirSync(dir)) if (/^\.(work|dropped)-[0-9a-f]{12}$/.test(name) && !plainDirProblem(join(dir, name))) rmSync(join(dir, name), { recursive: true, force: true });
      if (!plainDirProblem(tmp)) for (const name of readdirSync(tmp)) if (/^run-[0-9a-f]{12}$/.test(name) && !plainDirProblem(join(tmp, name))) rmSync(join(tmp, name), { recursive: true, force: true });
    } catch {}
  }
  writeWork(task, path, bytes) {
    return this.#serial(task, () => {
      const t = this.#get(task);
      if (t.status !== "working") throw new TaskError("stale", `the task is ${t.status}`);
      const why = pathProblem(path);
      if (why) throw new TaskError("bad_request", why);
      if (bytes.length > LIMITS.doc) throw new TaskError("too_large", `a file is at most ${LIMITS.doc} bytes`);
      const { files } = scanTree(this.work(task), this.budget.files * 10);
      const names = [...files.keys()];
      if (!files.has(path)) {
        if (files.size + 1 > this.budget.files) throw new TaskError("too_large", `at most ${this.budget.files} files`);
        const clash = pathSetProblem([...names, path]);
        if (clash) throw new TaskError("bad_request", clash);
      }
      const size = [...files.values()].reduce((n, f) => n + f.size, 0) - (files.get(path)?.size ?? 0) + bytes.length;
      if (size > this.budget.work) throw new TaskError("too_large", "the working copy would be over its budget");
      this.#reserve(task, bytes.length);
      writeTaskFile(this.work(task), path, bytes);
      return { path, bytes: bytes.length };
    });
  }

  /** tasks.answer: questions come in M2. */
  answer() { throw new TaskError("unavailable", "questions come in a later version"); }

  /** For tests and the turns (A2): a task's state, read only. */
  state(id) { return structuredClone(this.#get(id)); }
}

// A Delegate task's history: an ordinary bare git repository, written by this module alone (pair-delegate plan r3.3
// §2.1; the protocol: design/workspace-agent-protocol.md §6).  Objects are git's own (blob, tree, commit: their SHA-1
// ids as `git hash-object` gives them), written as loose objects; a ref moves only by compare-and-swap under git's own
// lock file (`<ref>.lock`, created exclusively), so ordinary git reads the repository and agrees with it:
//   git --git-dir=<task>/git --work-tree=<task>/work log --all
// What this never does: read a config, a hook, an attribute or a pointer from anywhere; run anything; fetch or push.
// The repository's location is the caller's fixed path, never one found in a working copy.

import { createHash } from "node:crypto";
import { closeSync, constants, fsyncSync, fstatSync, mkdirSync, openSync, readSync, readdirSync, renameSync, unlinkSync, writeSync, existsSync, lstatSync } from "node:fs";
import { join, dirname } from "node:path";
import { deflateSync, inflateSync } from "node:zlib";

/** The largest object read back (bytes, inflated): a task's document is at most 4 MB, a tree or commit far less. */
export const OBJECT_READ_MAX = 8 * 1024 * 1024;
const OID = /^[0-9a-f]{40}$/;
const REF = /^refs\/(heads|tags)\/[a-z0-9][a-z0-9-]{0,63}$/;
/** Who writes a task's commits (no person's name: the agent records what it and the page did). */
export const AUTHOR = "sagebrush-agent <tasks@sagebrush-agent.invalid>";

const enc = new TextEncoder();
const bytesOf = (b) => (typeof b === "string" ? enc.encode(b) : b);

/** The git id of an object of `type` holding `body`. */
export function objectId(type, body) {
  const b = bytesOf(body);
  return createHash("sha1").update(`${type} ${b.length}\0`).update(b).digest("hex");
}
/** The git blob id of `bytes` (what P0's `blob` is: the SHA-1 of "blob <n>\0" and the bytes). */
export const blobId = (bytes) => objectId("blob", bytes);

/** Write all of `data` to `fd`: a short write is continued, and no progress is an error (never a partial file acknowledged). */
export function writeAll(fd, data) {
  const b = Buffer.isBuffer(data) ? data : Buffer.from(data);
  for (let at = 0; at < b.length; ) {
    const n = writeSync(fd, b, at, b.length - at);
    if (!(n > 0)) throw new Error(`a write made no progress at byte ${at} of ${b.length}`);
    at += n;
  }
}
const NOFOLLOW = constants.O_NOFOLLOW ?? 0;
// (a file written whole and durably: a unique temporary name beside it (created exclusively, never through a link),
//  every byte written, fsync, rename; the directory fsynced after.  Any failure is thrown: nothing is acknowledged)
function writeDurable(path, data, mode = 0o600) {
  const tmp = `${path}.${process.pid}.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}.tmp`;
  const fd = openSync(tmp, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | NOFOLLOW, mode);
  try {
    writeAll(fd, data);
    fsyncSync(fd);
  } finally {
    closeSync(fd);
  }
  renameSync(tmp, path);
  syncDir(dirname(path));
}
/** fsync a directory; an error is thrown (a durability failure is never swallowed). */
export function syncDir(dir) {
  const fd = openSync(dir, constants.O_RDONLY | NOFOLLOW);
  try { fsyncSync(fd); } finally { closeSync(fd); }
}
const plainDir = (p) => { const st = lstatSync(p); return st.isDirectory() && !st.isSymbolicLink(); };
/** Why the repository at `gitdir` isn't the plain layout this module writes (every fixed folder a real directory, HEAD
 * and config plain files, no link anywhere on them), or null. */
export function repoProblem(gitdir) {
  try {
    for (const d of ["", "objects", "refs", "refs/heads", "refs/tags"]) if (!plainDir(join(gitdir, d))) return `${d || "the repository"} is not a plain folder`;
    for (const f of ["HEAD", "config"]) { const st = lstatSync(join(gitdir, f)); if (!st.isFile() || st.nlink !== 1) return `${f} is not a plain file`; }
  } catch (e) { return String(e?.code ?? e?.message ?? e); }
  return null;
}

/** A new bare repository at `gitdir` (which must not exist), private to this user. */
export function initRepo(gitdir) {
  mkdirSync(gitdir, { mode: 0o700 });
  for (const d of ["objects", "refs", "refs/heads", "refs/tags"]) mkdirSync(join(gitdir, d), { mode: 0o700 });
  writeDurable(join(gitdir, "HEAD"), "ref: refs/heads/base\n");
  writeDurable(join(gitdir, "config"), "[core]\n\trepositoryformatversion = 0\n\tbare = true\n");
}

/** Write an object (if it isn't there); its id. */
export function writeObject(gitdir, type, body) {
  const b = bytesOf(body);
  const oid = objectId(type, b);
  const dir = join(gitdir, "objects", oid.slice(0, 2)), path = join(dir, oid.slice(2));
  if (existsSync(dir) && !plainDir(dir)) throw new Error(`objects/${oid.slice(0, 2)} is not a plain folder`);
  if (existsSync(path)) { const st = lstatSync(path); if (!st.isFile()) throw new Error(`object ${oid} is not a plain file`); return oid; }
  mkdirSync(dir, { recursive: true, mode: 0o700 });
  const head = enc.encode(`${type} ${b.length}\0`);
  const all = new Uint8Array(head.length + b.length);
  all.set(head, 0);
  all.set(b, head.length);
  writeDurable(path, deflateSync(all), 0o400);
  return oid;
}

/** An object's type and body; checked against its id.  Throws if missing, corrupt or too large. */
export function readObject(gitdir, oid) {
  if (!OID.test(oid)) throw new Error("not an object id");
  // (the fan-out folder a plain one too: never read through a link)
  const fan = join(gitdir, "objects", oid.slice(0, 2));
  if (!plainDir(fan)) throw new Error(`objects/${oid.slice(0, 2)} is not a plain folder`);
  const raw = inflateSync(readPlain(join(fan, oid.slice(2)), OBJECT_READ_MAX + 64), { maxOutputLength: OBJECT_READ_MAX + 64 });
  const nul = raw.indexOf(0);
  const m = /^(blob|tree|commit) (\d+)$/.exec(raw.subarray(0, nul).toString("latin1"));
  if (!m || Number(m[2]) !== raw.length - nul - 1) throw new Error(`object ${oid} is malformed`);
  const body = raw.subarray(nul + 1);
  if (objectId(m[1], body) !== oid) throw new Error(`object ${oid} doesn't match its id`);
  return { type: m[1], body };
}

/** A plain file's bytes, opened without following a link, checked to be a regular file with one link, at most `max`. */
export function readPlain(path, max) {
  // (non-blocking, so a FIFO planted in its place can't stall the open; then a regular file is required before any read)
  const fd = openSync(path, constants.O_RDONLY | NOFOLLOW | (constants.O_NONBLOCK ?? 0));
  try {
    const st = fstatSync(fd);
    if (!st.isFile() || st.nlink !== 1) throw new Error(`${path.split("/").slice(-2).join("/")} is not a plain file`);
    if (st.size > max) throw new Error(`${path.split("/").slice(-2).join("/")} is over ${max} bytes`);
    const buf = Buffer.alloc(st.size);
    for (let n = 0; n < st.size; ) { const k = readSync(fd, buf, n, st.size - n, n); if (k === 0) throw new Error("a file shrank while it was read"); n += k; }
    return buf;
  } finally { closeSync(fd); }
}

// ---- trees: a flat map of path -> blob id, written as git's nested trees
/** git's tree order: names as bytes, a directory's name compared as if it ended in "/". */
const treeKey = (e) => Buffer.from(e.dir ? e.name + "/" : e.name, "utf8");
function writeTreeLevel(gitdir, files) {
  const here = new Map(); // name -> {blob} | {sub: Map}
  for (const [path, oid] of files) {
    const [first, ...rest] = path.split("/");
    if (!rest.length) here.set(first, { blob: oid });
    else {
      const e = here.get(first) ?? { sub: new Map() };
      e.sub.set(rest.join("/"), oid);
      here.set(first, e);
    }
  }
  const entries = [...here].map(([name, e]) => (e.sub ? { name, dir: true, oid: writeTreeLevel(gitdir, e.sub) } : { name, dir: false, oid: e.blob }));
  entries.sort((a, b) => Buffer.compare(treeKey(a), treeKey(b)));
  const parts = entries.flatMap((e) => [enc.encode(`${e.dir ? "40000" : "100644"} ${e.name}\0`), Buffer.from(e.oid, "hex")]);
  return writeObject(gitdir, "tree", Buffer.concat(parts));
}
/** A tree for `files` (Map path -> blob id); its id. */
export const writeTree = (gitdir, files) => writeTreeLevel(gitdir, files);

/** A tree's files, recursively: Map path -> blob id.  Only regular files and directories are accepted. */
export function readTree(gitdir, oid, prefix = "", out = new Map()) {
  const { type, body } = readObject(gitdir, oid);
  if (type !== "tree") throw new Error(`${oid} is not a tree`);
  let i = 0;
  while (i < body.length) {
    const sp = body.indexOf(0x20, i), nul = body.indexOf(0, sp);
    const mode = body.subarray(i, sp).toString("latin1"), name = body.subarray(sp + 1, nul).toString("utf8");
    const child = body.subarray(nul + 1, nul + 21).toString("hex");
    i = nul + 21;
    if (mode === "40000") readTree(gitdir, child, prefix + name + "/", out);
    else if (mode === "100644") out.set(prefix + name, child);
    else throw new Error(`tree ${oid} has an entry of mode ${mode}`);
  }
  return out;
}

// ---- commits
/** A commit of `tree` with `parents` and `message`, at `time` (seconds); its id. */
export function writeCommit(gitdir, { tree, parents = [], message, time }) {
  const t = `${Math.floor(time)} +0000`;
  const text = `tree ${tree}\n${parents.map((p) => `parent ${p}\n`).join("")}author ${AUTHOR} ${t}\ncommitter ${AUTHOR} ${t}\n\n${message.endsWith("\n") ? message : message + "\n"}`;
  return writeObject(gitdir, "commit", text);
}
/** A commit's tree, parents and message. */
export function readCommit(gitdir, oid) {
  const { type, body } = readObject(gitdir, oid);
  if (type !== "commit") throw new Error(`${oid} is not a commit`);
  const text = body.toString("utf8"), blank = text.indexOf("\n\n");
  const head = text.slice(0, blank).split("\n");
  return { tree: head.find((l) => l.startsWith("tree ")).slice(5), parents: head.filter((l) => l.startsWith("parent ")).map((l) => l.slice(7)), message: text.slice(blank + 2) };
}

// ---- refs: read, and moved only by compare-and-swap
/** A ref's commit id, or null if it doesn't exist. */
export function readRef(gitdir, ref) {
  if (!REF.test(ref)) throw new Error("not a task ref");
  let t;
  try { t = readPlain(join(gitdir, ref), 256).toString("utf8"); } catch (e) { if (e.code === "ENOENT") return null; throw e; }
  const oid = t.trim();
  if (!OID.test(oid)) throw new Error(`ref ${ref} is malformed`);
  return oid;
}
export class RefConflict extends Error {}
/** Move `ref` from `expect` (null: absent) to `next`, or throw RefConflict.  git's protocol: `<ref>.lock` created
 * exclusively (another writer's lock is a conflict), the value checked under it, written, fsynced, renamed. */
export function casRef(gitdir, ref, expect, next) {
  if (!REF.test(ref) || !OID.test(next) || (expect !== null && !OID.test(expect))) throw new Error("bad ref update");
  const path = join(gitdir, ref), lock = path + ".lock";
  let fd;
  try { fd = openSync(lock, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | NOFOLLOW, 0o600); } catch (e) { if (e.code === "EEXIST") throw new RefConflict(`${ref} is locked`); throw e; }
  let moved = false;
  try {
    const now = readRef(gitdir, ref);
    if (now !== expect) throw new RefConflict(`${ref} is ${now ?? "absent"}, not ${expect ?? "absent"}`);
    writeAll(fd, next + "\n");
    fsyncSync(fd);
    closeSync(fd);
    fd = undefined;
    renameSync(lock, path);
    moved = true;
    syncDir(dirname(path));
  } finally {
    if (fd !== undefined) closeSync(fd);
    if (!moved) try { unlinkSync(lock); } catch {}
