}
/** Locks left by a crash (only this process writes a task's refs, one operation at a time): removed at recovery. */
export function clearStaleLocks(gitdir) {
  for (const d of ["refs/heads", "refs/tags"]) {
    let names = [];
    try { names = readdirSync(join(gitdir, d)); } catch {}
    for (const n of names) if (n.endsWith(".lock")) { const p = join(gitdir, d, n); if (lstatSync(p).isFile()) unlinkSync(p); }
  }
}

// A Delegate task's paths and the host's own file access (design/workspace-agent-protocol.md §6.1 "Paths"; plan r3.4
// §2.7).  The host touches a task's working copy only while nothing else of that task runs (its runner is a child it
// waits for), and then only through these: each path walked one component at a time from the task's root by lstat,
// every component a real directory and the last a regular file with one link; no link, FIFO, device or Windows
// reparse point is followed or opened.  Writes go to a temporary file beside the target, fsynced, then renamed.

import { closeSync, fstatSync, fsyncSync, lstatSync, mkdirSync, openSync, readSync, readdirSync, renameSync, unlinkSync, writeSync, constants } from "node:fs";
import { join } from "node:path";
import { syncDir, writeAll } from "./task-git.mjs";

export const PATH_LIMITS = Object.freeze({ files: 2000, component: 255, path: 1024 });
const RESERVED = /^(con|prn|aux|nul|com[0-9¹²³]|lpt[0-9¹²³])(\..*)?$/i;
const enc = new TextEncoder();
/** A UTF-16 surrogate with no partner: text that isn't well formed (the page refuses it too). */
export const LONE_SURROGATE = /[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/;
/** Text that isn't well formed for the protocol (§3 and §6: neither side accepts it): a lone surrogate, or U+0000 (a
 * binary document goes as {base64}). */
export const NOT_WELL_FORMED = /\u0000|[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/;

/** Why `p` isn't a task path, or null.  The rules: relative and normalized ("a/b.ipynb"), no "." or ".." component,
 * no empty component, no backslash, ":" (drive or ADS), control character or NUL, no Windows reserved name, no
 * component named .git (any case) or .sagebrush, each component at most 255 bytes, the path at most 1,024. */
export function pathProblem(p) {
  if (typeof p !== "string" || p === "") return "a path is a non-empty string";
  if (LONE_SURROGATE.test(p)) return "a path is well-formed text (no lone surrogate)";
  if (enc.encode(p).length > PATH_LIMITS.path) return `a path is at most ${PATH_LIMITS.path} bytes`;
  if (p.startsWith("/") || /[\\:\x00-\x1f\x7f]/.test(p)) return "a path is relative, with no backslash, colon or control character";
  for (const c of p.split("/")) {
    if (c === "" || c === "." || c === "..") return "a path has no empty, . or .. component";
    if (enc.encode(c).length > PATH_LIMITS.component) return `a path's component is at most ${PATH_LIMITS.component} bytes`;
    if (c.toLowerCase() === ".git" || c === ".sagebrush") return "no component may be .git or .sagebrush";
    if (RESERVED.test(c) || /[ .]$/.test(c)) return "a component may not be a Windows reserved name, or end in a space or dot";
  }
  return null;
}
/** Why a set of paths can't be one task's, or null: each valid, at most 2,000, no two the same ignoring case, and no
 * path also a folder of another. */
export function pathSetProblem(paths) {
  if (paths.length > PATH_LIMITS.files) return `at most ${PATH_LIMITS.files} files a task`;
  const seen = new Set();
  for (const p of paths) {
    const bad = pathProblem(p);
    if (bad) return `${JSON.stringify(p.slice(0, 80))}: ${bad}`;
    const k = p.toLowerCase();
    if (seen.has(k)) return `${JSON.stringify(p.slice(0, 80))}: two paths differ only in case`;
    seen.add(k);
  }
  for (const p of paths) {
    const parts = p.toLowerCase().split("/");
    for (let i = 1; i < parts.length; i++) if (seen.has(parts.slice(0, i).join("/"))) return `${JSON.stringify(p.slice(0, 80))}: a path is also another's folder`;
  }
  return null;
}

export class UnsafePath extends Error {}
const isPlainDir = (st) => st.isDirectory() && !st.isSymbolicLink();

/** Walk `rel` under `root` component by component: every folder on the way a real directory (made, 0700, when
 * `make`), never a link.  The full path of the last component; it may not exist. */
function walk(root, rel, make) {
  // (the root itself first: a real directory, never a link, before anything under it is read or written)
  const rs = lstatSync(root);
  if (!isPlainDir(rs)) throw new UnsafePath("the working copy's folder is not a plain folder");
  const parts = rel.split("/");
  let cur = root;
  for (let i = 0; i < parts.length - 1; i++) {
    cur = join(cur, parts[i]);
    let st;
    try { st = lstatSync(cur); } catch (e) {
      if (e.code !== "ENOENT" || !make) throw e.code === "ENOENT" ? Object.assign(new Error("no such folder"), { code: "ENOENT" }) : e;
      mkdirSync(cur, { mode: 0o700 });
      st = lstatSync(cur);
    }
    if (!isPlainDir(st)) throw new UnsafePath(`${parts.slice(0, i + 1).join("/")} is not a plain folder`);
  }
  return join(cur, parts[parts.length - 1]);
}

/** A task file's bytes, read without following any link: a regular file with one link, at most `max` bytes. */
export function readTaskFile(root, rel, max) {
  const full = walk(root, rel, false);
  const st = lstatSync(full);
  if (!st.isFile() || st.nlink !== 1) throw new UnsafePath(`${rel} is not a plain file`);
  if (st.size > max) throw Object.assign(new Error(`${rel} is over ${max} bytes`), { code: "too_large" });
  const fd = openSync(full, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const f = fstatSync(fd);
    if (!f.isFile() || f.nlink !== 1 || f.ino !== st.ino || f.dev !== st.dev) throw new UnsafePath(`${rel} changed while it was opened`);
    if (f.size > max) throw Object.assign(new Error(`${rel} is over ${max} bytes`), { code: "too_large" });
    const buf = Buffer.alloc(f.size);
    let n = 0;
    while (n < f.size) { const k = readSync(fd, buf, n, f.size - n, n); if (k === 0) break; n += k; }
    return buf.subarray(0, n);
  } finally { closeSync(fd); }
}

/** Write a task file whole: folders made as needed (never through a link), the bytes to a temporary file beside it,
 * fsynced, renamed over it.  An existing target that isn't a plain file is refused, not replaced. */
export function writeTaskFile(root, rel, bytes) {
  const full = walk(root, rel, true);
  try {
    const st = lstatSync(full);
    if (!st.isFile() || st.nlink !== 1) throw new UnsafePath(`${rel} is not a plain file`);
  } catch (e) { if (e.code !== "ENOENT") throw e; }
  const tmp = `${full}.sb-${process.pid}-${Math.random().toString(36).slice(2, 10)}.tmp`;
  const fd = openSync(tmp, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | (constants.O_NOFOLLOW ?? 0), 0o600);
  try { writeAll(fd, bytes); fsyncSync(fd); } finally { closeSync(fd); }
  renameSync(tmp, full);
  syncDir(full.slice(0, full.lastIndexOf("/")));
}

/** Remove a task file (a plain file only). */
export function removeTaskFile(root, rel) {
  const full = walk(root, rel, false);
  const st = lstatSync(full);
  if (!st.isFile()) throw new UnsafePath(`${rel} is not a plain file`);
  unlinkSync(full);
}

/** Every file of the working copy, by a bounded no-follow walk: Map path -> {size}.  Anything but plain folders and
 * plain files with one link (a link, FIFO, device, a file with hard links) is a problem: `{files, problems}`.  At most
 * `maxEntries` entries are looked at; past them, a problem. */
export function scanTree(root, maxEntries = 20000) {
  const files = new Map(), problems = [];
  if (!isPlainDir(lstatSync(root))) return { files, problems: ["the working copy's folder is not a plain folder"] };
  let seen = 0;
  const visit = (dir, rel) => {
    for (const name of readdirSync(dir).sort()) {
      if (++seen > maxEntries) { problems.push(`more than ${maxEntries} entries`); return false; }
      const p = rel ? `${rel}/${name}` : name, full = join(dir, name), st = lstatSync(full);
      if (isPlainDir(st)) { if (visit(full, p) === false) return false; }
      else if (st.isFile() && st.nlink === 1) files.set(p, { size: st.size });
      else problems.push(`${p.slice(0, 200)}: ${st.isSymbolicLink() ? "a link" : st.isFile() ? "a file with more than one link" : "not a plain file or folder"}`);
    }
    return true;
  };
  visit(root, "");
  return { files, problems };
}

/** Why `dir` can't hold private task state, or null: it must be a real directory (not a link), owned by this user,
 * with no access for group or others.  POSIX only: on Windows there is no Delegate in M1 (plan r3.4 §0.5). */
export function privateDirProblem(dir) {
  if (process.platform === "win32") return "Delegate isn't available on Windows yet";
  let st;
  try { st = lstatSync(dir); } catch (e) { return `${dir}: ${e.code ?? e.message}`; }
  if (!isPlainDir(st)) return `${dir} is not a plain folder`;
  if (typeof process.getuid === "function" && st.uid !== process.getuid()) return `${dir} is not owned by this user`;
  if ((st.mode & 0o077) !== 0) return `${dir} is open to other users (mode ${(st.mode & 0o777).toString(8)})`;
  return null;
}

// The Delegate runner (pair-delegate plan r3.4 §2.6): one notebook of a task's copy run by the pinned engine under the
// pinned Deno, as a child of this agent, with no shell, no PATH and none of this agent's environment.
//
// Three layers, so no single one is the boundary: this host makes no links and walks work/ by lstat before and after
// every run (a link or special file there and the run doesn't start, or its result isn't kept); Deno's permissions
// (read and write only work/ and the run's own tmp, read the engine file, no network, subprocess, FFI or system
// calls); and the engine's own --confine, always given both roots.  There is no unconfined path and no fallback: where
// any of it can't be had, notebook_run refuses, saying why, and editing and proposing go on.
//
// RUNS_ENABLED is false in this version: runs are refused until the security review clears them on the full evidence.

import { createHash, randomBytes } from "node:crypto";
import { spawn } from "node:child_process";
import { closeSync, constants as C, fstatSync, lstatSync, mkdirSync, openSync, readSync, realpathSync, rmSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import { platformKey } from "./codex-fetch.mjs";
import { ensureRunner, pinProblem, RUNNER_PIN } from "./runner-fetch.mjs";
import { procStart } from "./proc-start.mjs";
import { pathProblem, scanTree } from "./task-paths.mjs";
import { writeAll } from "./task-git.mjs";
import { TaskError } from "./tasks-schema.mjs";

/** Runs are off in this version: a separate, reviewed change turns them on. */
export const RUNS_ENABLED = false;
export const RUN_LIMITS = Object.freeze({
  timeoutS: 300, // a run's cells, all together, unless the call asks for less
  maxTimeoutS: 3600,
  marginMs: 30 * 1000, // on top of the cells' time: the wall bound, after which the run's process group is killed
  stdout: 4 * 1024 * 1024, // the engine's report; past it the run is killed and refused
  stderr: 64 * 1024, // kept for the reason; the rest dropped
});
export const TZ_SOURCE = new URL("./tzdata/zoneinfo/", import.meta.url).pathname;
const NOFOLLOW = C.O_NOFOLLOW ?? 0;
const unavailable = (why) => new TaskError("unavailable", `Running code isn't available for Delegate on this computer: ${why}`);

/** The fixed Deno argv for one run: every path absolute, each list one argv element, no shell (plan §2.6). */
export function runArgv({ engine, work, runTmp, notebook, timeoutS }) {
  return [
    "run", "--no-prompt", "--no-config", "--no-lock", "--no-remote", "--no-npm", "--cached-only", "--no-code-cache",
    `--allow-read=${work},${runTmp},${engine}`, `--allow-write=${work},${runTmp}`, "--allow-env",
    "--deny-net", "--deny-run", "--deny-ffi", "--deny-sys",
    engine, "notebook", "run", notebook, "--json", "--write", "--timeout", String(timeoutS), "--confine", work, "--confine", runTmp,
    // (the lifeline: this agent holds the run's standard input open; when the agent ends, however it ends, so does the run)
    "--until-stdin-ends",
  ];
}

/** The run's whole environment: nothing of this agent's (--allow-env exposes exactly these, and Deno's own PATH and
 * DENO_NODE_SHIM_ACTIVE). */
export function runEnv({ work, runTmp }) {
  const zones = join(runTmp, "zoneinfo");
  return { HOME: work, TMPDIR: runTmp, DENO_DIR: join(runTmp, "deno"), NO_COLOR: "1", TZ: "UTC", TZDIR: zones, PYTHONTZPATH: zones };
}

/** Copy the pinned zone data into `dest`, bytewise: each file read without following a link, a regular file with one
 * link, of its pinned size and sha256, written new (never over anything).  Throws on any difference. */
export function copyZones(dest, files, source = TZ_SOURCE) {
  mkdirSync(dest, { mode: 0o700 });
  for (const [rel, f] of Object.entries(files)) {
    if (pathProblem(rel)) throw new Error(`zone data: ${rel} isn't a plain path`);
    const parts = rel.split("/");
    for (let i = 1; i < parts.length; i++) { try { mkdirSync(join(dest, ...parts.slice(0, i)), { mode: 0o700 }); } catch (e) { if (e.code !== "EEXIST") throw e; } }
    const fd = openSync(join(source, rel), C.O_RDONLY | NOFOLLOW);
    let bytes;
    try {
      const st = fstatSync(fd);
      if (!st.isFile() || st.nlink !== 1 || st.size !== f.size) throw new Error(`zone data: ${rel} isn't as pinned`);
      bytes = Buffer.alloc(f.size);
      let n = 0;
      while (n < f.size) { const k = readSync(fd, bytes, n, f.size - n, n); if (!k) break; n += k; }
      if (n !== f.size || createHash("sha256").update(bytes).digest("hex") !== f.sha256) throw new Error(`zone data: ${rel} isn't as pinned`);
    } finally { closeSync(fd); }
    const out = openSync(join(dest, rel), C.O_WRONLY | C.O_CREAT | C.O_EXCL | NOFOLLOW, 0o600);
    try { writeAll(out, bytes); } finally { closeSync(out); }
  }
}
const zoneBytes = (files) => Object.values(files).reduce((n, f) => n + f.size, 0);

export class TaskRunner {
  /**
   * `store`: the TaskStore.  `enabled`: whether runs may happen at all (RUNS_ENABLED; tests say so explicitly).
   * `ensure`: gives the verified {deno, engine} paths (runner-fetch's ensureRunner; tests pass their own).
   */
  constructor({ store, enabled = RUNS_ENABLED, ensure = ensureRunner, pin = RUNNER_PIN, platform = platformKey(), zoneSource = TZ_SOURCE, limits = RUN_LIMITS, spawnFn = spawn }) {
    Object.assign(this, { store, enabled, ensure, pin, platform, zoneSource, spawnFn });
    this.limits = { ...RUN_LIMITS, ...limits };
  }

  /** Why runs are off on this computer or for this task, or null. */
  problem(task) {
    if (!this.enabled) return "runs are turned off in this version";
    if (process.platform === "win32") return "runs aren't available on Windows in this version";
    const why = pinProblem(this.pin, this.platform);
    if (why) return why;
    if (task && this.store.state(task).grant.run !== true) return "this task wasn't started with running code allowed";
    return null;
  }

  /**
   * Run one notebook of the task's copy (`rel`, a path in work/).  Resolves to the engine's JSON report, or rejects
   * with a TaskError saying why.  `signal`: the turn's abort; on it (a Stop, a breach, the time limit) the run's
   * process group is killed, the exit waited for, and work/ put back as it was before the run.  `admit`: why the run
   * can't have the disk it needs now (the turn's free-space admission), or null; asked after the fetch and the
   * snapshot (which may write the cache and git objects), before the run's tmp folder, zone data or process.
   */
  async run(task, rel, { timeoutS = this.limits.timeoutS, signal, admit } = {}) {
    const why = this.problem(task);
    if (why) throw unavailable(why);
    if (typeof rel !== "string" || pathProblem(rel) || !/\.ipynb$/i.test(rel)) throw new TaskError("bad_request", "a notebook's path in your copy, ending in .ipynb");
    if (!Number.isInteger(timeoutS) || timeoutS < 1 || timeoutS > this.limits.maxTimeoutS) throw new TaskError("bad_request", `a timeout of 1 to ${this.limits.maxTimeoutS} seconds`);
    let paths;
    try { paths = await this.ensure({ pin: this.pin, platform: this.platform, signal }); } catch (e) { throw unavailable(e?.message ?? String(e)); }
    const store = this.store, work = store.work(task);
    // (the notebook: a plain file in work/, reached through plain folders)
    let st;
    try { st = lstatSync(join(work, rel)); } catch { throw new TaskError("not_found", `${rel} isn't in your copy`); }
    if (!st.isFile() || st.nlink !== 1) throw new TaskError("bad_request", `${rel} isn't a plain file`);
    // (before: work/ by lstat, nothing but plain folders and files; and what a cut-off run goes back to)
    const before = await store.snapshotWork(task);
    // (the disk, asked again here, after the fetch and the snapshot: short, refused before the run's folder, the zone
    //  data or the run itself)
    const short = admit?.();
    if (short) throw new TaskError("busy", short);
    const runTmp = join(store.runTmpRoot(task), `run-${randomBytes(6).toString("hex")}`);
    mkdirSync(runTmp, { mode: 0o700 });
    // (the run record, before anything the run does: if this agent dies, its next start ends the run and undoes it)
    const record = { v: 1, tmp: basename(runTmp), snapshot: before, pid: null, start: null };
    let release = () => {}, settled = true;
    try {
      store.writeRunRecord(task, record);
      const engine = realpathSync(paths.engine), deno = realpathSync(paths.deno), realWork = realpathSync(work), realTmp = realpathSync(runTmp);
      // (Deno's permission lists are comma-separated: a path with a comma can't be granted exactly)
      for (const p of [engine, realWork, realTmp]) if (p.includes(",")) throw unavailable(`a folder it would need has a comma in its path (${p})`);
      // (the zone data, copied in for this run only, checked against its pin: its bytes reserved first, as any write is,
      //  against the task's budget and the total, and held until the run's tmp is removed)
      release = store.reserveRun(task, zoneBytes(this.pin.tzdata.files));
      try { copyZones(join(realTmp, "zoneinfo"), this.pin.tzdata.files, this.zoneSource); } catch (e) { throw unavailable(e?.message ?? String(e)); }
      const notebook = join(realWork, rel);
      settled = false;
      // (the run's identity recorded before anything else: if that can't be written, the run doesn't go on)
      const onStart = (pid) => { try { store.writeRunRecord(task, { ...record, pid, start: procStart(pid) }); return true; } catch { return false; } };
      const out = await this.#spawn(onStart, deno, runArgv({ engine, work: realWork, runTmp: realTmp, notebook, timeoutS }), runEnv({ work: realWork, runTmp: realTmp }), dirname(notebook), timeoutS, signal);
      // (after: the run's process group is gone; work/ walked again, and a link or special file there undoes the run)
      const { problems } = scanTree(work, store.budget.files * 10);
      if (!out.killed && !problems.length) settled = true;
      if (out.killed || problems.length) {
        await store.restoreWork(task, before);
        settled = true;
        if (problems.length) throw new TaskError("bad_request", `the run left what your copy can't hold (${problems.slice(0, 2).join("; ")}): its changes were undone`);
        if (out.killed === "couldn't record the run") throw new TaskError("unavailable", "the run failed: couldn't record the run; its changes were undone");
        throw new TaskError(out.killed === "output" ? "too_large" : "unavailable", out.killed === "output" ? "the run's report was too large: its changes were undone" : `the run was stopped (${out.killed}): its changes were undone`);
      }
      let report;
      try { report = JSON.parse(out.stdout); } catch { throw new TaskError("unavailable", `the run gave no report (exit ${out.code}${out.stderr ? `: ${out.stderr.slice(-300)}` : ""})`); }
      return { exit: out.code, report };
    } finally {
      rmSync(runTmp, { recursive: true, force: true });
      release();
      // (kept while the copy may still hold a cut-off run's changes: the next start undoes them)
      if (settled) store.clearRunRecord(task);
    }
  }

  // (the run as a process group of its own: killed whole on the turn's abort, the wall bound, or too much output; the
  //  exit always waited for before anything is read)
  #spawn(onStart, deno, argv, env, cwd, timeoutS, signal) {
    return new Promise((resolve, reject) => {
      let child;
      // (its standard input a pipe this agent holds open and never writes: the run's lifeline)
      try { child = this.spawnFn(deno, argv, { cwd, env, detached: true, stdio: ["pipe", "pipe", "pipe"] }); } catch (e) { return reject(unavailable(`Deno couldn't be started (${e?.code ?? e?.message ?? e})`)); }
      child.stdin.on("error", () => {});
      let recorded = false;
      if (child.pid) recorded = onStart(child.pid);
      let stdout = [], outBytes = 0, stderr = "", killed = null;
      const kill = (why) => {
        killed ??= why;
        try { process.kill(-child.pid, "SIGKILL"); } catch {}
      };
      const wall = setTimeout(() => kill("its time was up"), timeoutS * 1000 + this.limits.marginMs);
      if (child.pid && !recorded) kill("couldn't record the run");
      const onAbort = () => kill("the task's turn was stopped");
      if (signal?.aborted) onAbort();
      signal?.addEventListener("abort", onAbort, { once: true });
      child.stdout.on("data", (d) => { outBytes += d.length; if (outBytes > this.limits.stdout) kill("output"); else stdout.push(d); });
      child.stderr.on("data", (d) => { if (stderr.length < this.limits.stderr) stderr += d.toString("utf8").slice(0, this.limits.stderr - stderr.length); });
      child.on("error", (e) => { clearTimeout(wall); signal?.removeEventListener("abort", onAbort); reject(unavailable(`Deno couldn't be started (${e?.code ?? e?.message ?? e})`)); });
      child.on("close", (code, sig) => {
        clearTimeout(wall);
        signal?.removeEventListener("abort", onAbort);
        // (anything the run left in its group goes with it)
        try { process.kill(-child.pid, "SIGKILL"); } catch {}
        child.stdin.destroy();
        resolve({ code: code ?? sig, stdout: Buffer.concat(stdout).toString("utf8"), stderr, killed });
      });
    });
  }
}

// A process's start time, as the system reports it: what ties a recorded run to the process that is running now, so a
// process id that has since been reused is never taken for the run (pair-delegate plan r3.4 §2.6: a run's recovery
// after the agent died).  Linux: /proc/<pid>/stat's field 22 (clock ticks since boot); macOS: `ps -o lstart=`.

import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";

/**
 * What process `pid` is: `{ gone: true }` only when the system says there is no such process (Linux: no
 * /proc/<pid>; macOS: kill(pid, 0) is ESRCH); `{ start, pgid }` when its start time and process group are read; else
 * `{ unknown: why }`: the process may be there and can't be told apart (an unreadable /proc entry, a `ps` that fails
 * or says nothing), never taken as gone.  `ps` and `kill`: the macOS tools (tests pass stand-ins).
 */
export function procInfo(pid, platform = process.platform, { ps = "/bin/ps", kill = (p, sig) => process.kill(p, sig) } = {}) {
  if (!Number.isSafeInteger(pid) || pid <= 1) return { unknown: "not a process id" };
  if (platform === "linux") {
    let s;
    try { s = readFileSync(`/proc/${pid}/stat`, "utf8"); } catch (e) {
      return e?.code === "ENOENT" ? { gone: true } : { unknown: `its /proc entry can't be read (${e?.code ?? e})` };
    }
    // (the fields after the command's name, which is in parentheses and may hold anything: field 3 onward)
    const rest = s.slice(s.lastIndexOf(")") + 2).split(" ");
    const start = rest[22 - 3], pgid = rest[5 - 3];
    return /^\d+$/.test(start ?? "") && /^\d+$/.test(pgid ?? "") ? { start: `linux:${start}`, pgid: Number(pgid) } : { unknown: "its /proc entry can't be parsed" };
  }
  if (platform === "darwin") {
    try { kill(pid, 0); } catch (e) { if (e?.code === "ESRCH") return { gone: true }; if (e?.code !== "EPERM") return { unknown: `it can't be asked about (${e?.code ?? e})` }; }
    const r = spawnSync(ps, ["-o", "pgid=,lstart=", "-p", String(pid)], { encoding: "utf8", timeout: 5000, env: { LC_ALL: "C", PATH: "/usr/bin:/bin" } });
    const m = r.status === 0 ? /^\s*(\d+)\s+(\S.*\S)\s*$/.exec(r.stdout) : null;
    return m ? { start: `darwin:${m[2]}`, pgid: Number(m[1]) } : { unknown: "ps can't say what it is" };
  }
  return { unknown: `no way to tell on ${platform}` };
}
/** Process `pid`'s start time, or null when it is gone or can't be read. */
export const procStart = (pid, platform, tools) => procInfo(pid, platform, tools).start ?? null;

/** Whether process `pid` exists (one of another account counts too: it can't be signalled, but it is there). */
export function alive(pid) {
  try { process.kill(pid, 0); return true; } catch (e) { return e?.code === "EPERM"; }
}

/** Whether any process of group `pgid` exists. */
export function groupAlive(pgid) {
  try { process.kill(-pgid, 0); return true; } catch (e) { return e?.code === "EPERM"; }
}

// A Delegate task's turns (pair-delegate plan r3.4 §2.2; the protocol: design/workspace-agent-protocol.md §6): Claude
// working on the task's own copy, with no page at all.  A turn belongs to its task, not to a page or a pairing: its
// tools act on the task's work/ folder only, through the task store (tasks.mjs), and it makes no page call, so the
// page can come and go while it runs.  The turn ends when Claude proposes (the store's propose, which commits the copy
// as the next round), or it is interrupted, with its reason, when it ends without one.
//
// The SDK runs with no setting sources, no native tools (no Bash, Read, Edit, Write, WebFetch or WebSearch), no MCP
// server but the task's own, no hooks, in the task's own sdk/ folder, every tool call through one callback that admits
// only the task's tools.  notebook_run goes to the task runner (task-runner.mjs), which refuses, saying why, wherever
// runs can't be had (in this version, everywhere: they stay off until their review clears them).  A turn's tool calls
// run one at a time, so nothing touches the copy while a run's process group is alive, and a turn ends only once its
// run has exited and, if the host cut it off, been undone.
//
// Limits: at most 4 turns running at once (more wait, at most 16), each at most 24 hours.  The SDK's transcript (under
// ~/.claude/projects, in the folder named after the task's sdk/) is the one thing a turn writes that the store doesn't:
// while a turn runs, it, the task's whole use and the disk's free space are checked every 500 ms, and a turn past a
// bound is interrupted then, with why (best effort: what is written between two checks can pass the bound).

import { mkdirSync, statfsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { randomBytes } from "node:crypto";
import { z } from "zod";
import { Turn } from "./turns.mjs";
import { conformTurnEvent } from "./turn-bounds.mjs";
import { notebookDoc } from "./notebook.mjs";
import { readTaskFile, scanTree } from "./task-paths.mjs";
import { LIMITS, TaskError } from "./tasks-schema.mjs";

export const TASK_SERVER = "sagebrush_task";
const PREFIX = `mcp__${TASK_SERVER}__`;
const MiB = 1024 * 1024;
const HALT = Symbol("halt");
export const TURN_LIMITS = Object.freeze({ running: 4, queued: 16, turnMs: 24 * 60 * 60 * 1000, readBytes: 256 * 1024, stopMs: 10000, transcript: 64 * MiB, transcriptEntries: 20000, headroom: 64 * MiB, pollMs: 500 });
/** Where Claude Code keeps its transcripts: `projects` in its config folder (CLAUDE_CONFIG_DIR, else ~/.claude). */
export const claudeProjects = (env = process.env) => join(env.CLAUDE_CONFIG_DIR || join(homedir(), ".claude"), "projects");
// (the free bytes of the filesystem holding `dir`, as an unprivileged writer sees them)
const freeBytes = (dir) => { const f = statfsSync(dir); return f.bavail * f.bsize; };
const KERNEL = {
  python: { name: "python3", display_name: "Python 3", language: "python" },
  sage: { name: "sagemath", display_name: "SageMath", language: "sage" },
  magma: { name: "magma", display_name: "Magma", language: "magma" },
  matlab: { name: "matlab", display_name: "MATLAB", language: "matlab" },
};

export const TASK_SYSTEM = `You are Claude, working on a task the person delegated to you in Sagebrush, a workspace for mathematics. You work on your own copy of the task's documents: nothing you do changes the person's own files. Use the workspace tools to read and change your copy (paths are relative to it, like "notes/a.md" or "analysis.ipynb"). Running code isn't available for delegated tasks yet: check your work by reading it. When you are done, call propose with a short summary of what you changed and why; the person then reviews the difference and merges it, closes it, or asks for changes. Don't call propose until the copy is the way you want it.`;

const text = (t) => ({ content: [{ type: "text", text: t }] });
const refusal = (t) => ({ content: [{ type: "text", text: `refused: ${t}` }], isError: true });
const rel = (p) => (typeof p === "string" ? p.replace(/^\/+/, "") : p);

/** A notebook written by the tool, as an .ipynb file (nbformat 4.5, Sagebrush's own cell ids). */
export function notebookIpynb(doc) {
  return JSON.stringify({
    cells: doc.cells.map((c) => (c.type === "markdown" ? { cell_type: "markdown", id: c.id, metadata: {}, source: c.code } : { cell_type: "code", id: c.id, metadata: {}, source: c.code, outputs: [], execution_count: null })),
    metadata: { kernelspec: KERNEL[doc.mode] ?? KERNEL.python, language_info: { name: (KERNEL[doc.mode] ?? KERNEL.python).language } },
    nbformat: 4,
    nbformat_minor: 5,
  }, null, 1);
}

/** A run's report as the model reads it: each code cell's status, time, output text and error, cut to `max` bytes in
 * all (said so). */
export function runSummary({ exit, report }, max) {
  const cells = (report?.cells ?? []).map((c) => ({ n: c.n, id: c.id, status: c.status, ...(c.ms !== undefined ? { ms: c.ms } : {}), ...(c.stdout ? { stdout: c.stdout } : {}), ...(c.stderr ? { stderr: c.stderr } : {}), ...(c.error ? { error: c.error } : {}), ...(c.outputs?.length ? { outputs: c.outputs } : {}) }));
  const whole = JSON.stringify({ ok: report?.ok === true, exit, ...(report?.wrote ? { wrote: true } : {}), cells }, null, 1);
  return Buffer.byteLength(whole) <= max ? whole : `${Buffer.from(whole).subarray(0, max).toString("utf8")}\n[cut: the report is ${Buffer.byteLength(whole)} bytes; ${max} shown. The outputs are in the notebook: read it.]`;
}

export class TaskTurns {
  /** `store`: the TaskStore; `query` and `createServer`: the SDK's (or the tests' fakes, as the agent server takes them). */
  constructor({ store, query, createServer, log = () => {}, limits = TURN_LIMITS, free = freeBytes, runner = null }) {
    this.store = store;
    this.runner = runner; // (a TaskRunner, or null: then notebook_run refuses)
    this.free = free;
    this.query = query;
    this.createServer = createServer;
    this.log = log;
    this.limits = { ...TURN_LIMITS, ...limits };
    this.running = new Map(); // task -> {abort, done, then}
    this.waiting = []; // [{task, kind}]
    this.reserved = 0; // (places held for requests between their check and their begin)
  }

  /** Why a turn for this task can't start for lack of disk, or null: the filesystem must have the task's remaining
   * budget plus the headroom free. */
  diskProblem(task) {
    const used = this.store.usage(task);
    if (used === null) return "the task's storage can't be measured";
    let free;
    try { free = this.free(this.store.root); } catch (e) { return `the free disk space can't be read (${e?.code ?? e?.message ?? e})`; }
    const need = Math.max(0, this.store.budget.task - used) + this.limits.headroom;
    return free < need ? `not enough free disk space for this task (${Math.ceil(need / MiB)} MB needed, ${Math.floor(free / MiB)} MB free)` : null;
  }
  /** Refused `busy` when a turn for this task couldn't start now for lack of disk (before a start, Ask or Resume is
   * recorded). */
  admit(task) {
    const why = task ? this.diskProblem(task) : this.#freeProblem();
    if (why) throw new TaskError("busy", why);
  }
  #freeProblem() {
    let free;
    try { free = this.free(this.store.root); } catch (e) { return `the free disk space can't be read (${e?.code ?? e?.message ?? e})`; }
    const need = this.store.budget.task + this.limits.headroom;
    return free < need ? `not enough free disk space for a task (${Math.ceil(need / MiB)} MB needed, ${Math.floor(free / MiB)} MB free)` : null;
  }
  /** What is over a bound while this task's turn runs, or null: its transcript, its whole use, the disk's headroom. */
  #breach(task) {
    // (the copy and the run's folder too, within the same entry bound: past it, or unreadable, a breach)
    const trees = this.store.runTreesProblem(task, this.limits.transcriptEntries);
    if (trees) return trees;
    const tr = this.store.transcriptBytes(task, this.limits.transcriptEntries);
    if (tr === null) return "its transcript can't be measured (a link there, or too many files)";
    if (tr > this.limits.transcript) return `its transcript passed ${Math.round(this.limits.transcript / MiB)} MB`;
    const used = this.store.usage(task);
    if (used === null) return "the task's storage can't be measured";
    if (used > this.store.budget.task) return "the task's storage budget is used up";
    let free;
    try { free = this.free(this.store.root); } catch { free = 0; }
    if (free < this.limits.headroom) return "the disk is almost full";
    return null;
  }

  /** A place for one more turn, held from before a request records anything until its begin (or its release):
   * refused `busy`, with nothing changed, when the running and waiting places are all taken.  A task whose turn is
   * still running holds its own place already. */
  reserve(task = null) {
    if (task && this.running.has(task)) return { release() {} };
    if (this.running.size + this.waiting.length + this.reserved >= this.limits.running + this.limits.queued) throw new TaskError("busy", `at most ${this.limits.running} tasks run at once, and ${this.limits.queued} wait`);
    this.reserved++;
    let held = true;
    return { release: () => { if (held) { held = false; this.reserved--; } } };
  }

  /** Start a turn for a working task (`kind`: "start", "ask" or "resume"), now or when a place frees; refused `busy` past
   * the queue.  `slot`: a place reserve() held for it, given back here. */
  begin(task, kind, slot = null) {
    slot?.release();
    // (a turn still ending (it proposed, and is finishing its records): the new one follows it, in its place)
    const r = this.running.get(task);
    if (r) { if (!r.then) r.then = kind; return { queued: true }; }
    if (this.waiting.some((w) => w.task === task)) return { queued: false, already: true };
    if (this.running.size >= this.limits.running) {
      if (this.waiting.length >= this.limits.queued) throw new TaskError("busy", `at most ${this.limits.running} tasks run at once, and ${this.limits.queued} wait`);
      this.waiting.push({ task, kind });
      return { queued: true };
    }
    this.#run(task, kind);
    return { queued: false };
  }
  /** Stop a task's turn (running or waiting); resolves when it has stopped. */
  async stop(task) {
    this.waiting = this.waiting.filter((w) => w.task !== task);
    const r = this.running.get(task);
    if (!r) return;
    r.then = null;
    r.abort.abort();
    // (bounded: a model that doesn't heed the abort can't hold a Stop or the switch's turning off; the caller then
    //  records the task's stop, and the turn's own end, if it ever comes, finds the task no longer working)
    let t;
    await Promise.race([r.done, new Promise((res) => { t = setTimeout(res, this.limits.stopMs ?? 10000); })]);
    clearTimeout(t);
  }
  /** Stop every turn (the agent stopping, or the Delegate switch turned off). */
  async stopAll() {
    this.waiting = [];
    await Promise.all([...this.running.keys()].map((t) => this.stop(t)));
  }
  isRunning(task) { return this.running.has(task); }

  #next() {
    while (this.running.size < this.limits.running && this.waiting.length) {
      const w = this.waiting.shift();
      if (this.store.state(w.task).status === "working") this.#run(w.task, w.kind);
    }
  }

  #run(task, kind) {
    const abort = new AbortController();
    // (each turn its own entry, and only the entry still current for its task records or changes the task's state: a
    //  turn that was stopped can't touch the task's next turn)
    const entry = { abort, done: null, then: null, runs: new Set() };
    this.running.set(task, entry);
    entry.done = this.#turn(task, kind, entry).catch((e) => this.log(`a task's turn failed: ${e?.message ?? e}`)).finally(() => {
      this.running.delete(task);
      if (entry.then && this.store.state(task).status === "working") return this.#run(task, entry.then);
      queueMicrotask(() => this.#next());
    });
  }

  #prompt(task, kind) {
    const t = this.store.state(task);
    const files = [...scanTree(this.store.work(task)).files.keys()].sort();
    const head = `Task: ${t.title}\n\n${t.prompt}\n\nYour copy holds: ${files.join(", ") || "(nothing)"}.`;
    // (the person's request, exactly as they wrote it, between two marker lines it can't forge: a fresh random tag)
    const ask = kind === "ask" || (kind === "resume" && t.mines.length > 0 && t.mines.length === t.proposals.length) ? this.store.lastAsk(task) : null;
    const request = () => {
      const tag = randomBytes(8).toString("hex");
      const theirs = ask.paths.length ? `\n\nWith their request they sent their own current versions of: ${ask.paths.join(", ")}. Those are recorded with the request, not in your copy; when they merge, the page combines your proposal with their versions.` : "";
      return `The person reviewed your proposal (round ${t.proposals.length}) and asked for changes. Their request, exactly as they wrote it, is between the two marker lines:\n----- the person's request ${tag} -----\n${ask.note}\n----- end of the person's request ${tag} -----${theirs}\n\nYour copy still holds what you proposed.`;
    };
    if (kind === "ask") return `${head}\n\n${ask ? request() : `The person reviewed your proposal (round ${t.proposals.length}) and asked for changes. Your copy still holds what you proposed.`} Make the changes they ask for, then propose again.`;
    if (kind === "resume") return `${head}\n\n${ask ? `${request()}\n\n` : ""}You were interrupted while working on this task; your copy is as you left it. Look at it, then carry on.`;
    return head;
  }

  // The task's tools: its copy only, through the store.
  #tools(task, proposed, entry) {
    const store = this.store, work = store.work(task), abort = entry.abort;
    // (one call at a time: the SDK may ask for several at once, and nothing may touch the copy while a run is alive;
    //  before each call: the turn not stopped, and the task still working, not stopped, revoked, closed or merged)
    let tail = Promise.resolve();
    const call = (f) => {
      const next = tail.then(async () => {
        if (abort.signal.aborted || store.state(task).status !== "working") return refusal("this task's turn is over");
        try { return await f(); } catch (e) { return refusal(e instanceof TaskError ? e.message : String(e?.message ?? e)); }
      });
      tail = next.catch(() => {});
      return next;
    };
    const path = z.string().max(1024).describe("A path in your copy, like notes/a.md or analysis.ipynb");
    return [
      ["workspace_list", "List the files of your copy of the task's documents.", { folder: z.string().max(1024).optional() }, (a) => call(async () => {
        const f = rel(a.folder ?? "");
        const all = [...scanTree(work).files].filter(([p]) => !f || p === f || p.startsWith(f.replace(/\/$/, "") + "/"));
        return text(JSON.stringify(all.map(([p, x]) => ({ path: p, size: x.size }))));
      })],
      ["workspace_read", "Read one file of your copy (text; a notebook as its .ipynb JSON). Long files are cut, said so.", { path }, (a) => call(async () => {
        const bytes = readTaskFile(work, rel(a.path), LIMITS.doc);
        const t = bytes.toString("utf8");
        const cut = Buffer.byteLength(t) > this.limits.readBytes;
        return text(cut ? `${Buffer.from(t).subarray(0, this.limits.readBytes).toString("utf8")}\n[cut: the file is ${bytes.length} bytes; ${this.limits.readBytes} shown]` : t);
      })],
      ["workspace_write", "Write one text file of your copy, whole (it is created if it isn't there).", { path, text: z.string().max(LIMITS.doc) }, (a) => call(async () => {
        if (/\.ipynb$/i.test(rel(a.path))) {
          try { const j = JSON.parse(a.text); if (!j || !Array.isArray(j.cells)) throw 0; } catch { return refusal("a notebook is written as its .ipynb JSON, or with workspace_write_notebook"); }
        }
        await store.writeWork(task, rel(a.path), Buffer.from(a.text, "utf8"));
        return text(`wrote ${rel(a.path)}`);
      })],
      ["workspace_write_notebook", "Write a Sagebrush notebook (an .ipynb file) of your copy, whole: its language and its cells, code and Markdown.", {
        path,
        mode: z.enum(["python", "sage", "matlab", "magma"]),
        cells: z.array(z.object({ type: z.enum(["code", "markdown"]), source: z.string() }).strict()),
      }, (a) => call(async () => {
        if (!/\.ipynb$/i.test(rel(a.path))) return refusal("a notebook's path ends in .ipynb");
        const doc = notebookDoc({ mode: a.mode, cells: a.cells });
        if (doc instanceof Error) return refusal(doc.message);
        await store.writeWork(task, rel(a.path), Buffer.from(notebookIpynb(doc), "utf8"));
        return text(`wrote ${rel(a.path)} (${doc.cells.length} cells)`);
      })],
      ["notebook_run", "Run every code cell of a notebook of your copy, with its outputs written into it. Code can read and write only your copy (and a scratch folder of its own); it has no network.", {
        path,
        timeout: z.number().int().min(1).max(3600).optional().describe("Seconds for all its cells together (default 300)"),
      }, (a) => call(async () => {
        const why = this.runner ? this.runner.problem(task) : "runs are turned off in this version";
        if (why) return refusal(`Running code isn't available for Delegate on this computer: ${why}. Check your work by reading it.`);
        // (the run's own admission: the same free space a turn needs, asked again before the run's tmp folder, zone
        //  data or process is made)
        const run = this.runner.run(task, rel(a.path), { ...(a.timeout ? { timeoutS: a.timeout } : {}), signal: abort.signal, admit: () => this.diskProblem(task) });
        entry.runs.add(run);
        try { return text(runSummary(await run, this.limits.readBytes)); } finally { entry.runs.delete(run); }
      })],
      ["propose", "Propose your copy to the person: they see the difference from what you started with, and merge it, close it, or ask for changes. Call it once, when you are done.", { summary: z.string().max(LIMITS.prompt) }, (a) => call(async () => {
        if (proposed.done) return refusal("you already proposed in this turn");
        await store.propose(task, { summary: a.summary });
        proposed.done = true;
        return text("proposed: the person will review it");
      })],
    ];
  }

  async #turn(task, kind, entry) {
    const store = this.store, abort = entry.abort;
    const current = () => this.running.get(task) === entry;
    const turn = new Turn(`task-${randomBytes(6).toString("hex")}`);
    // (each event made to fit the page's bounds first: what the host records, the page can show)
    const send = async (drafts) => { const events = drafts.flatMap((d) => conformTurnEvent(d, this.log)); if (events.length && current()) await store.record(task, events); };
    const proposed = { done: false };
    const deadline = setTimeout(() => abort.abort(), this.limits.turnMs);
    const sdkDir = store.sdk(task);
    // (the watch: a bound passed mid-turn interrupts it, with why)
    let why = null, it = null;
    const halted = new Promise((r) => abort.signal.addEventListener("abort", () => r(HALT), { once: true }));
    const watch = setInterval(() => {
      if (why || abort.signal.aborted) return;
      try { why = this.#breach(task); } catch (e) { why = `the task's storage can't be checked (${e?.code ?? e?.message ?? e})`; }
      if (why) abort.abort();
    }, this.limits.pollMs);
    try {
      // (a turn that waited: the disk checked again as it starts; short, it doesn't start, and the task says why)
      why = this.diskProblem(task);
      if (why) return;
      // (sdk/ made here, not through a link: a link or anything but a private folder there, and the turn doesn't start)
      try { mkdirSync(sdkDir, { mode: 0o700 }); } catch (e) { if (e?.code !== "EEXIST") throw e; }
      why = store.sdkProblem(task) && `its sdk folder can't be used (${store.sdkProblem(task)})`;
      if (why) return;
      await send(turn.start());
      const server = this.createServer({ name: TASK_SERVER, version: "1", tools: this.#tools(task, proposed, entry) });
      const q = this.query({
        prompt: this.#prompt(task, kind),
        options: {
          includePartialMessages: true,
          cwd: sdkDir,
          mcpServers: { [TASK_SERVER]: server },
          systemPrompt: TASK_SYSTEM,
          settingSources: [],
          strictMcpConfig: true,
          tools: [],
          permissionMode: "default",
          settings: { permissions: { defaultMode: "default", disableAutoMode: "disable", disableBypassPermissionsMode: "disable" } },
          // (every call through here: the task's own tools pass, anything else is refused)
          canUseTool: async (name, input) => (typeof name === "string" && name.startsWith(PREFIX) ? { behavior: "allow", updatedInput: input } : { behavior: "deny", message: "only the task's own tools are available" }),
          persistSession: true,
          abortController: abort,
        },
      });
      // (each message raced against the turn's abort: a Stop, a breach or the time limit ends the turn here at once,
      //  whether or not the SDK heeds the abort; nothing it yields after that is taken or recorded)
      it = q[Symbol.asyncIterator]();
      for (;;) {
        const next = it.next();
        next.catch(() => {});
        const m = await Promise.race([next, halted]);
        if (m === HALT || m.done || abort.signal.aborted) break;
        if (store.state(task).status !== "working") break; // (proposed, or stopped: the turn's work is over)
        await send(turn.feed(m.value));
      }
      if (store.state(task).status === "working") await send(abort.signal.aborted ? turn.interrupted() : turn.finished ? [] : turn.failed("the agent stopped without a result"));
    } catch (e) {
      if (store.state(task).status === "working") await send(abort.signal.aborted ? turn.interrupted() : turn.failed(e?.message ?? e)).catch(() => {});
    } finally {
      clearTimeout(deadline);
      // (a run still alive was killed by the same abort: its exit, and the undoing of its changes, waited for here, so
      //  nothing else touches the copy before that; the watch keeps measuring meanwhile)
      if (entry.runs.size) await Promise.allSettled([...entry.runs]);
      clearInterval(watch);
      // (a turn that ended without a proposal leaves the task interrupted, with why; only the person's Resume goes on)
      if (current() && store.state(task).status === "working") {
        await store.interrupt(task, why ?? (abort.signal.aborted ? "the turn was stopped" : "the agent's turn ended without a proposal")).catch(() => {});
      }
      // (then the SDK's query closed, on every way out: a proposal, an end, an error, a Stop or a breach; after an
      //  abort, that ends Claude Code's process (stdin closed, then killed after a grace period); waited for at most
      //  the stop bound, and only then is the turn's place freed)
      if (it) {
        let t;
        await Promise.race([Promise.resolve().then(() => it.return?.()).catch(() => {}), new Promise((r) => { t = setTimeout(r, this.limits.stopMs); })]);
        clearTimeout(t);
      }
    }
  }
}

// A task's chat turn events made to fit the page's bounds before they are recorded (the one table: the page's
// web/workspace/tasks-schema.ts TURN, protocol §6.1), so an event the host records is never one the page refuses.
// Nothing is lost where it can be kept: long text is split into several deltas; free text is cut, ending in "…"; a
// code is cut; an id that isn't the page's kind of id is replaced by a stable one (the same original, the same id);
// an artifact of a kind the page doesn't show is not recorded, and the agent's log says so.

import { createHash } from "node:crypto";

export const PAGE_BOUNDS = Object.freeze({ short: 400, id: 128, text: 192 * 1024, code: 64, lang: 64, kinds: Object.freeze(["markdown", "code", "diff", "notebook", "board"]) });
// (where the host's own record check (tasks.mjs EVENT_SHAPES) is stricter than the page, its bound: both must pass)
const HOST = Object.freeze({ tool: 40, name: 200, lang: 40, errorMessage: 4096 });
const PAGE_ID = /^[\x21-\x7e]{1,128}$/;

/** An id as the page takes one (1 to 128 printable ASCII): kept if it is one, else "h" and 32 hex of its sha256. */
export const pageId = (s) => (typeof s === "string" && PAGE_ID.test(s) ? s : `h${createHash("sha256").update(String(s)).digest("hex").slice(0, 32)}`);

// (the longest start of `s` of at most `max` UTF-8 bytes, whole characters only)
function prefix(s, max) {
  if (Buffer.byteLength(s) <= max) return s;
  let n = 0, out = "";
  for (const ch of s) {
    const b = Buffer.byteLength(ch);
    if (n + b > max) break;
    n += b;
    out += ch;
  }
  return out;
}
/** `s` in at most `max` UTF-8 bytes: as it is, or cut and ending in "…". */
export const cut = (s, max) => (Buffer.byteLength(s) <= max ? s : `${prefix(s, max - 3)}…`);
/** `s` split into pieces of at most `max` UTF-8 bytes, at character boundaries; joined, they are `s`. */
export function split(s, max) {
  const out = [];
  let rest = s;
  while (Buffer.byteLength(rest) > max) {
    const p = prefix(rest, max);
    out.push(p);
    rest = rest.slice(p.length);
  }
  out.push(rest);
  return out;
}

/** One draft event, conformed: the events to record in its place (none, one, or a split delta's pieces). */
export function conformTurnEvent(e, log = () => {}) {
  const B = PAGE_BOUNDS;
  const x = { ...e };
  if (typeof x.turn_id === "string") x.turn_id = pageId(x.turn_id);
  switch (x.type) {
    case "message_revised":
      return [{ ...x, message: pageId(x.message) }];
    case "text_delta":
      return split(x.text, B.text).map((text) => ({ ...x, message: pageId(x.message), text }));
    case "thinking_delta":
      return split(x.text, B.text).map((text) => ({ ...x, text }));
    case "tool_call_started": {
      const o = { ...x, call: pageId(x.call), tool: prefix(x.tool, Math.min(B.short, HOST.tool)) };
      if (typeof o.name === "string") o.name = cut(o.name, Math.min(B.short, HOST.name));
      if (typeof o.summary === "string") o.summary = cut(o.summary, B.short);
      return [o];
    }
    case "tool_call_finished":
      return [{ ...x, call: pageId(x.call) }];
    case "turn_error":
      return [{ ...x, code: prefix(x.code, B.code), message: cut(x.message, HOST.errorMessage) }];
    case "turn_finished":
      return [typeof x.code === "string" ? { ...x, code: prefix(x.code, B.code) } : x];
    case "artifact": {
      if (!B.kinds.includes(x.kind)) {
        log(`an artifact of kind ${JSON.stringify(String(x.kind).slice(0, 40))} isn't one the page shows: not recorded`);
        return [];
      }
      const o = { ...x, id: pageId(x.id), title: cut(x.title, B.short) };
      if (typeof o.lang === "string") o.lang = prefix(o.lang, Math.min(B.lang, HOST.lang));
      return [o];
    }
    default:
      return [x];
  }
}

// A Delegate task's proposal, for the person to read (Pair and Delegate plan r1, UI-2): the files the agent changed
// against the task's snapshot, each with its diff, and a notebook as proposed. In the review chunk
// (sagebrush-review.js) with the review page, whose diff renderers it shares (diff-render.ts). Nothing here runs
// code, and nothing here decides: the decisions (Merge, Close, Ask for changes) are the host page's, in `o.actions`.
//
// From a ProposalSource (the page's view of the host: tasks.diff and tasks.file), never from the workspace:
//   - the list, from source.diff(): the base and proposal commits, the round, and each file with its change;
//   - a file's diff when its row is opened (a proposal of one file: opened at once): both sides read (source.file),
//     then admitted to the preview only if each is at most PROPOSAL_LIMITS.bytes of UTF-8; a notebook (.ipynb text,
//     read by the notebook module's fromFile) cell by cell, any other text line by line, anything else "No preview";
//     and a notebook's proposed document, read only and not reactive, with outputs.ts's filter, under a details;
//   - one file open at a time; a newer open, a refresh or a close drops what an older one read (its generation).
import { h, notebookDiff, style, textDiff } from "./diff-render";
import { reviewLineDiff, utf8Length } from "./line-diff";
import { CELL_LIMITS, type CellKey } from "./cells";
import { filterOutputs } from "./outputs";

export type ProposalFile = { path: string; kind: string; change: "added" | "modified" | "deleted" };
export type ProposalDiff = { base: string; proposal: string; round: number; seq: number; files: ProposalFile[] };
export type ProposalSource = {
  diff(): Promise<ProposalDiff>;
  /** A file as stored at a commit: a notebook's .ipynb text, a text file's text; null if it isn't there. */
  file(path: string, commit: string): Promise<string | null>;
};
/** The notebook component's module, as the pages load it: its component, and its reading of an .ipynb text. */
export type ProposalNotebookModule = {
  createNotebook(root: HTMLElement, opts: Record<string, unknown>): { load(doc: unknown): void; setReadOnly(ro: boolean): void; destroy(): void };
  fromFile(name: string, text: string): { cells: { id?: string; type?: string; code?: string }[] };
};
export type ProposalView = { close(): void; refresh(): void; idle(): Promise<void> };

export const PROPOSAL_LIMITS = Object.freeze({ bytes: 4 * 2 ** 20, files: 2000 });

export const PROPOSAL_TEXT = {
  title: (round: number) => (round > 1 ? `Proposal, round ${round}` : "Proposal"),
  commits: (base: string, proposal: string, n: number) => `${n === 1 ? "1 file" : `${n.toLocaleString("en-US")} files`} changed · from ${base.slice(0, 7)} to ${proposal.slice(0, 7)}`,
  change: { added: "added", modified: "changed", deleted: "deleted" } as Record<ProposalFile["change"], string>,
  proposed: "The notebook as proposed",
  noPreview: "No preview for this kind of file.",
  tooLarge: "Too large to show here.",
  tooLargeText: "Too large to compare line by line.",
  tooManyCells: `Too many cells to show here (more than ${CELL_LIMITS.cells.toLocaleString("en-US")}).`,
  outputsTooMany: "Its outputs are too many or too large to show here.",
  notShown: "This output isn't shown here.",
  unreadable: "Couldn't read this file.",
  tooManyFiles: `Too many changed files to show here (more than ${PROPOSAL_LIMITS.files.toLocaleString("en-US")}).`,
  failed: "Couldn't load the proposal.",
  nothing: "No files changed.",
} as const;

const isNotebook = (f: ProposalFile) => f.kind === "notebook" || /\.ipynb$/i.test(f.path);
const keysOf = (d: { cells: { type?: string; code?: string }[] } | null): CellKey[] => (d?.cells ?? []).map((c) => ({ type: c.type ?? "code", code: String(c.code ?? "") }));

/** The proposal from `source` in `panel`, with `o.actions` (the host page's buttons) at its foot. */
export function openProposal(source: ProposalSource, panel: HTMLElement, o: { notebook: () => Promise<ProposalNotebookModule>; actions?: HTMLElement }): ProposalView {
  style();
  let gen = 0, closed = false, mounted: { destroy(): void } | null = null, busy: Promise<void> = Promise.resolve();
  const root = h("div", { className: "sbrv sbpv" });
  panel.replaceChildren(root);
  const unmount = () => { try { mounted?.destroy(); } catch {} mounted = null; };

  function draw() {
    const my = ++gen;
    unmount();
    root.replaceChildren(h("p", { className: "st", textContent: "…" }));
    busy = (async () => {
      let d: ProposalDiff;
      try { d = await source.diff(); } catch { if (my === gen && !closed) root.replaceChildren(h("p", { className: "msg", textContent: PROPOSAL_TEXT.failed })); return; }
      if (my !== gen || closed) return;
      const list = h("div");
      root.replaceChildren(
        h("h3", { textContent: PROPOSAL_TEXT.title(d.round) }),
        h("p", { className: "st", textContent: PROPOSAL_TEXT.commits(d.base, d.proposal, d.files.length) }),
        list,
      );
      if (o.actions) root.append(o.actions);
      if (!d.files.length) { list.append(h("p", { className: "st", textContent: PROPOSAL_TEXT.nothing })); return; }
      if (d.files.length > PROPOSAL_LIMITS.files) { list.append(h("p", { className: "msg", textContent: PROPOSAL_TEXT.tooManyFiles })); return; }
      for (const f of d.files) {
        const row = h("div", { className: "file" });
        const open = h("button", { className: "path", type: "button", textContent: f.path });
        const body = h("div");
        open.onclick = () => void openFile(f, d, body, my);
        row.append(open, h("span", { className: "run", textContent: " " + PROPOSAL_TEXT.change[f.change] }), body);
        list.append(row);
      }
      // (one file changed: opened at once)
      if (d.files.length === 1) await openFile(d.files[0], d, list.querySelector(".file > div:last-child") as HTMLElement, my);
    })();
  }

  async function openFile(f: ProposalFile, d: ProposalDiff, body: HTMLElement, my: number) {
    const fileGen = ++gen;
    const stale = () => closed || gen !== fileGen;
    unmount();
    for (const b of root.querySelectorAll(".file > div")) b.replaceChildren();
    const say = (t: string, cls = "st") => body.append(h("p", { className: cls, textContent: t }));
    let a: string | null = null, b: string | null = null;
    try {
      [a, b] = await Promise.all([f.change === "added" ? null : source.file(f.path, d.base), f.change === "deleted" ? null : source.file(f.path, d.proposal)]);
    } catch { if (!stale()) say(PROPOSAL_TEXT.unreadable, "msg"); return; }
    if (stale()) return;
    // (admitted to the preview by each side's UTF-8 bytes, after the read: the read itself is the host's bound)
    if (utf8Length(a ?? "") > PROPOSAL_LIMITS.bytes || utf8Length(b ?? "") > PROPOSAL_LIMITS.bytes) return say(PROPOSAL_TEXT.tooLarge);
    if (isNotebook(f)) {
      let mod: ProposalNotebookModule;
      try { mod = await o.notebook(); } catch { if (!stale()) say(PROPOSAL_TEXT.unreadable, "msg"); return; }
      if (stale()) return;
      let A: ReturnType<ProposalNotebookModule["fromFile"]> | null = null, B: ReturnType<ProposalNotebookModule["fromFile"]> | null = null;
      try { A = a === null ? null : mod.fromFile(f.path, a); B = b === null ? null : mod.fromFile(f.path, b); } catch { return say(PROPOSAL_TEXT.unreadable, "msg"); }
      if ((A?.cells.length ?? 0) > CELL_LIMITS.cells || (B?.cells.length ?? 0) > CELL_LIMITS.cells) return say(PROPOSAL_TEXT.tooManyCells);
      await notebookDiff(body, keysOf(A), keysOf(B), stale);
      if (stale() || !B) return;
      // (the notebook as proposed: what may be shown decided on this one document, before the component sees it)
      const slot = h("details", {}, h("summary", { textContent: PROPOSAL_TEXT.proposed }));
      body.append(slot);
      const shown = filterOutputs(B, PROPOSAL_TEXT.notShown);
      if ("refused" in shown) { slot.append(h("p", { className: "st", textContent: PROPOSAL_TEXT.outputsTooMany })); return; }
      const el = h("div");
      slot.append(el);
      const comp = mod.createNotebook(el, { kernel: null, readOnly: true, reactive: false, remotePictures: "click" });
      mounted = comp;
      comp.load(B);
      comp.setReadOnly(true);
      for (const btn of el.querySelectorAll<HTMLButtonElement>("button")) btn.disabled = true;
      return;
    }
    // (a line diff only for text: a text or code file, or a data file whose name says it is text)
    const texty = f.kind === "text" || f.kind === "code" || /\.(txt|md|py|sage|m|mag|js|json|tex|csv|tsv|bib|sty|cls)$/i.test(f.path);
    if (!texty) return say(PROPOSAL_TEXT.noPreview);
    const dd = reviewLineDiff(a ?? "", b ?? "");
    const pre = dd.ok ? textDiff(dd.a, dd.b, dd.segs) : null;
    body.append(pre ?? h("p", { className: "st", textContent: PROPOSAL_TEXT.tooLargeText }));
    void my;
  }

  draw();
  return {
    close() { closed = true; gen++; unmount(); panel.replaceChildren(); },
    refresh() { if (!closed) draw(); },
    idle: () => busy,
  };
}

// What the review page and the Delegate proposal view both draw (moved here from review-page.ts unchanged): the DOM
// helper, the views' style, a text diff with three lines of context, and a notebook's cells compared base to head. In
// the review chunk (sagebrush-review.js) with both views.
import { REVIEW_DIFF, reviewLineDiff, type Seg } from "./line-diff";
import { CELL_LIMITS, cellDiff, foldRows, type CellKey } from "./cells";

/** The words the diffs show; review-page.ts's REVIEW_PAGE_TEXT carries them too. */
export const DIFF_TEXT = {
  unchangedCells: (n: number) => (n === 1 ? "1 unchanged cell" : `${n.toLocaleString("en-US")} unchanged cells`),
  unchangedLines: (n: number) => (n === 1 ? "1 unchanged line" : `${n.toLocaleString("en-US")} unchanged lines`),
  moreCells: (n: number) => (n === 1 ? "1 more changed cell not shown" : `${n.toLocaleString("en-US")} more changed cells not shown`),
  tooManyCells: `Too many cells to compare (more than ${CELL_LIMITS.cells.toLocaleString("en-US")}).`,
} as const;

export function h<K extends keyof HTMLElementTagNameMap>(tag: K, props: Partial<HTMLElementTagNameMap[K]> & { className?: string } = {}, ...kids: (Node | string | null | undefined | false)[]): HTMLElementTagNameMap[K] {
  const e = Object.assign(document.createElement(tag), props);
  for (const k of kids) if (k) e.append(k);
  return e;
}

let styled = false;
/** The views' style, added once. */
export function style() {
  if (styled) return;
  styled = true;
  document.head.append(h("style", { textContent: `
.sbrv{font:14px/1.4 system-ui,sans-serif;color:#222}
.sbrv h3{font-size:16px;margin:.4em 0}
.sbrv .st{color:#555;margin:.2em 0 .6em}
.sbrv .file{border-top:1px solid #ddd;padding:.5em 0}
.sbrv .path{font-family:ui-monospace,monospace;cursor:pointer;background:none;border:0;padding:0;color:#0645ad;text-align:left}
.sbrv .run{color:#555;font-size:13px}
.sbrv .dec label{margin-right:1em}
.sbrv .dec input[type=text]{width:60%}
.sbrv .msg{color:#8a1f11;margin:.3em 0}
.sbrv pre.diff{font:12px/1.35 ui-monospace,monospace;margin:.3em 0;white-space:pre-wrap;word-break:break-all}
.sbrv .l-{background:#fdecec}.sbrv .l\\+{background:#e8f5e9}
.sbrv .fold{color:#777;font-style:italic;font-size:12px;margin:.2em 0}
.sbrv .cell{border-left:3px solid #ccc;padding-left:.5em;margin:.3em 0}
.sbrv .cell.add{border-color:#4caf50}.sbrv .cell.del{border-color:#e57373}.sbrv .cell.chg{border-color:#ffb300}
.sbrv textarea{width:100%;min-height:3em}
.sbrv .branches button{display:block;margin:.3em 0;text-align:left;background:none;border:0;color:#0645ad;cursor:pointer}
` }));
}

/** A text diff, three lines of context, longer unchanged runs folded; null past REVIEW_DIFF.renderLines. */
export function textDiff(a: string[], b: string[], segs: Seg[], budget = { lines: REVIEW_DIFF.renderLines }): HTMLElement | null {
  const out = h("pre", { className: "diff" });
  const line = (cls: string, t: string) => { if (--budget.lines < 0) return false; out.append(h("div", { className: cls, textContent: (cls === "l-" ? "- " : cls === "l+" ? "+ " : "  ") + t.replace(/\n$/, "") })); return true; };
  for (let i = 0; i < segs.length; i++) {
    const s = segs[i];
    if (s.t === "-") { for (let k = 0; k < s.n; k++) if (!line("l-", a[s.a + k])) return null; continue; }
    if (s.t === "+") { for (let k = 0; k < s.n; k++) if (!line("l+", b[s.b + k])) return null; continue; }
    const head = i === 0 ? 0 : 3, tail = i === segs.length - 1 ? 0 : 3;
    if (s.n <= head + tail + 1) { for (let k = 0; k < s.n; k++) if (!line("l", a[s.a + k])) return null; continue; }
    for (let k = 0; k < head; k++) if (!line("l", a[s.a + k])) return null;
    out.append(h("div", { className: "fold", textContent: DIFF_TEXT.unchangedLines(s.n - head - tail) }));
    for (let k = s.n - tail; k < s.n; k++) if (!line("l", a[s.a + k])) return null;
  }
  return out;
}

/** A notebook's cells, base to head: unchanged runs folded, each changed cell its code's diff, each added or deleted
 * cell its code; one comparison budget and one render budget for the file, the rest counted past them. */
export async function notebookDiff(box: HTMLElement, A: CellKey[], B: CellKey[], stale: () => boolean) {
  const rows = cellDiff(A, B);
  if (!rows) { box.append(h("p", { textContent: DIFF_TEXT.tooManyCells })); return; }
  let budget = REVIEW_DIFF.budget, notShown = 0, k = 0;
  const lines = { lines: REVIEW_DIFF.renderLines };
  for (const r of foldRows(rows)) {
    // (every 50 rows a task's turn, so a close or a change can come in and stop it)
    if (++k % 50 === 0) { await new Promise((r) => setTimeout(r, 0)); if (stale()) return; }
    if ("fold" in r) { box.append(h("div", { className: "fold", textContent: DIFF_TEXT.unchangedCells(r.fold) })); continue; }
    if (notShown) { notShown++; continue; }
    const [a, b] = r.t === "+" ? ["", B[r.b].code] : r.t === "-" ? [A[r.a].code, ""] : [A[r.a].code, B[r.b].code];
    const d = reviewLineDiff(a, b, { budget });
    if (!d.ok) { notShown++; continue; }
    budget -= d.used;
    const pre = textDiff(d.a, d.b, d.segs, lines);
    if (!pre) { notShown++; continue; }
    box.append(h("div", { className: "cell " + (r.t === "+" ? "add" : r.t === "-" ? "del" : "chg") }, pre));
  }
  if (notShown) box.append(h("p", { className: "fold", textContent: DIFF_TEXT.moreCells(notShown) }));
}

// A Delegate proposal merged into the person's version as it is now (Pair and Delegate plan r1, UI-1): three-way,
// base (the task's snapshot), mine (the person's version now) and theirs (the agent's proposal), and every place both
// changed differently is a conflict the person picks, never settled here. Pure: no page, no store.
//
// A notebook, by cell id (the three descend from one snapshot, so a cell keeps its id on every side):
//   - a cell's content is its type, code, attachments and metadata; its outputs, count and time follow its code and
//     never make a change of their own;
//   - changed on one side: that side's; changed alike on both: once; changed differently on both: a conflict;
//   - removed on one side and unchanged on the other: removed; removed on one side and changed on the other: a
//     conflict (the cell kept or removed, as picked);
//   - added on one side: kept, after the nearest cell before it on its own side that the merge has (else first);
//     added with one id on both, alike: once, else a conflict;
//   - the order is the person's; the agent's moves of existing cells are not applied;
//   - the notebook's other fields (its mode and the rest), key by key, by the same rule; a clash is a conflict.
// The notebook's fields are read and written as own properties, so one named like an Object.prototype key ("__proto__")
// is kept as data. A cell's type is "code" when it has none, as when it says so.
// Outputs: a cell taken from a side takes that side's outputs, count and time; a cell unchanged on both takes the
// person's, unless only the agent's has outputs (it ran the cell, the person didn't); one changed alike on both takes
// the person's.
//
// A text file, by lines (diff3): each side's changes against the base (review/line-diff.ts, under its bounds), and
// changes that overlap or touch on both sides are one conflict, unless both made the same change. A diff past its
// bounds makes the whole file one conflict.
import { reviewLineDiff, splitLines } from "./line-diff";

export type Cell = { id: string; type?: string; code?: string; outputs?: unknown[]; [k: string]: unknown };
export type Notebook = { cells: Cell[]; [k: string]: unknown };
export type Pick = "mine" | "theirs";
export type CellConflict = { id: string; kind: "cell"; cell: string; mine: Cell | null; theirs: Cell | null };
export type FieldConflict = { id: string; kind: "field"; key: string; mine: unknown; theirs: unknown };
export type NotebookMerge = {
  /** The merged notebook with every conflict still open: each conflict's cell at its place, as `mine` has it (left
   * out where mine has none), each conflicting field as mine. resolveNotebook gives the final one. */
  merged: Notebook;
  conflicts: (CellConflict | FieldConflict)[];
  /** Theirs' cells in the order they'd take, for a conflict that takes theirs where mine has no cell. */
  order: string[];
};

const OUT_KEYS = new Set(["outputs", "n", "ms", "exec_count", "execution_count"]);
/** A cell's content, as text, for comparing: everything but its outputs, count and time, keys sorted. */
function content(c: Cell | undefined): string | null {
  if (!c) return null;
  // (the type normalized: a cell with no type is a code cell, as one that says so)
  const k = Object.keys(c).filter((x) => !OUT_KEYS.has(x) && x !== "type").sort();
  return JSON.stringify([["type", c.type ?? "code"], ...k.map((x) => [x, c[x]])]);
}
const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b);
// (a field read and written as an own property only: a field named "__proto__" is data, never the prototype)
const own = (o: object, k: string): unknown => (Object.hasOwn(o, k) ? (o as Record<string, unknown>)[k] : undefined);
const put = (o: object, k: string, v: unknown) => Object.defineProperty(o, k, { value: v, writable: true, enumerable: true, configurable: true });
const byId = (cells: Cell[]) => new Map(cells.map((c) => [String(c.id), c]));

export function mergeNotebooks(base: Notebook, mine: Notebook, theirs: Notebook): NotebookMerge {
  const B = byId(base.cells ?? []), M = byId(mine.cells ?? []), T = byId(theirs.cells ?? []);
  const conflicts: (CellConflict | FieldConflict)[] = [];
  // (what each cell id becomes: a cell, removed (null), or a conflict)
  const take = new Map<string, Cell | null>();
  const conflictOf = new Map<string, CellConflict>();
  const ids = new Set([...B.keys(), ...M.keys(), ...T.keys()]);
  for (const id of ids) {
    const b = B.get(id), m = M.get(id), t = T.get(id);
    const cb = content(b), cm = content(m), ct = content(t);
    const mineChanged = cm !== cb, theirsChanged = ct !== cb;
    // (unchanged on both: the person's, outputs and all, unless only theirs has outputs (the agent ran it, the
    //  person didn't); changed by theirs alone: theirs')
    const ran = (c: Cell | undefined) => Array.isArray(c?.outputs) && c!.outputs!.length > 0;
    if (!mineChanged && !theirsChanged) take.set(id, (!ran(m) && ran(t) ? t : m) ?? null);
    else if (!mineChanged) take.set(id, t ?? null);
    else if (!theirsChanged) take.set(id, m ?? null);
    else if (cm === ct) take.set(id, m ?? null);
    else {
      const c: CellConflict = { id: `cell:${id}`, kind: "cell", cell: id, mine: m ?? null, theirs: t ?? null };
      conflicts.push(c);
      conflictOf.set(id, c);
      take.set(id, m ?? null);
    }
  }
  // (the order: the person's; then each cell only theirs has (added by them, or kept by a conflict), after its
  // nearest earlier cell on theirs' side that is placed, else first)
  const order: string[] = (mine.cells ?? []).map((c) => String(c.id));
  const placed = new Set(order);
  let prev: string | null = null;
  for (const c of theirs.cells ?? []) {
    const id = String(c.id);
    if (!placed.has(id) && (take.get(id) || conflictOf.has(id))) {
      const at = prev === null ? 0 : order.indexOf(prev) + 1;
      order.splice(at, 0, id);
      placed.add(id);
    }
    if (placed.has(id)) prev = id;
  }
  const cells = order.map((id) => take.get(id)).filter((c): c is Cell => !!c);
  // (the notebook's other fields, key by key)
  const merged: Notebook = { cells } as Notebook;
  const keys = new Set([...Object.keys(base), ...Object.keys(mine), ...Object.keys(theirs)].filter((k) => k !== "cells"));
  for (const k of [...keys].sort()) {
    const b = own(base, k), m = own(mine, k), t = own(theirs, k);
    let v: unknown;
    if (same(m, b)) v = t;
    else if (same(t, b) || same(m, t)) v = m;
    else { conflicts.push({ id: `field:${k}`, kind: "field", key: k, mine: m, theirs: t }); v = m; }
    if (v !== undefined) put(merged, k, v);
  }
  return { merged, conflicts, order };
}

/** The final notebook: each conflict as picked (every conflict must have a pick). */
export function resolveNotebook(r: NotebookMerge, picks: Record<string, Pick>): Notebook {
  const missing = r.conflicts.filter((c) => picks[c.id] !== "mine" && picks[c.id] !== "theirs").map((c) => c.id);
  if (missing.length) throw new Error(`not picked: ${missing.join(", ")}`);
  const cellPick = new Map<string, Cell | null>();
  for (const c of r.conflicts) if (c.kind === "cell") cellPick.set(c.cell, picks[c.id] === "mine" ? c.mine : c.theirs);
  const now = new Map(r.merged.cells.map((c) => [String(c.id), c]));
  const cells: Cell[] = [];
  for (const id of r.order) {
    const c = cellPick.has(id) ? cellPick.get(id) : now.get(id);
    if (c) cells.push(c);
  }
  const out: Notebook = { ...r.merged, cells };
  for (const c of r.conflicts) {
    if (c.kind !== "field") continue;
    const v = picks[c.id] === "mine" ? c.mine : c.theirs;
    if (v === undefined) delete out[c.key];
    else put(out, c.key, v);
  }
  return out;
}

export type TextPart = { kind: "same"; text: string } | { kind: "conflict"; id: string; base: string; mine: string; theirs: string };
export type TextMerge = { parts: TextPart[]; conflicts: number };

type Hunk = { a0: number; a1: number; lines: string[] };
function hunks(base: string, side: string): Hunk[] | null {
  const d = reviewLineDiff(base, side);
  if (!d.ok) return null;
  const out: Hunk[] = [];
  let cur: Hunk | null = null;
  for (const s of d.segs) {
    if (s.t === "=") { if (cur) out.push(cur); cur = null; continue; }
    cur ??= { a0: s.a, a1: s.a, lines: [] };
    if (s.t === "-") cur.a1 = s.a + s.n;
    else cur.lines.push(...d.b.slice(s.b, s.b + s.n));
  }
  if (cur) out.push(cur);
  return out;
}

/** Three-way merge of a text file by lines. */
export function mergeText(base: string, mine: string, theirs: string): TextMerge {
  if (mine === theirs || theirs === base) return { parts: [{ kind: "same", text: mine }], conflicts: 0 };
  if (mine === base) return { parts: [{ kind: "same", text: theirs }], conflicts: 0 };
  const hm = hunks(base, mine), ht = hunks(base, theirs);
  if (!hm || !ht) return { parts: [{ kind: "conflict", id: "text:0", base, mine, theirs }], conflicts: 1 };
  const B = splitLines(base);
  const all = [...hm.map((h) => ({ ...h, side: 0 })), ...ht.map((h) => ({ ...h, side: 1 }))].sort((x, y) => x.a0 - y.a0 || x.a1 - y.a1);
  const parts: TextPart[] = [];
  const keep = (text: string) => { if (!text) return; const p = parts.at(-1); if (p?.kind === "same") p.text += text; else parts.push({ kind: "same", text }); };
  let at = 0, n = 0;
  for (let i = 0; i < all.length; ) {
    // (a group: hunks that overlap or touch, on either side)
    let a0 = all[i].a0, a1 = all[i].a1;
    const group = [all[i++]];
    while (i < all.length && all[i].a0 <= a1) { a1 = Math.max(a1, all[i].a1); group.push(all[i++]); }
    keep(B.slice(at, a0).join(""));
    // (each side's text for the group's base range: its own hunks, base lines between them)
    const sideText = (side: number) => {
      let s = "", p = a0;
      for (const h of group.filter((g) => g.side === side)) { s += B.slice(p, h.a0).join("") + h.lines.join(""); p = h.a1; }
      return s + B.slice(p, a1).join("");
    };
    const sides = new Set(group.map((g) => g.side));
    if (sides.size === 1) keep(sideText(group[0].side));
    else {
      const m = sideText(0), t = sideText(1);
      if (m === t) keep(m);
      else parts.push({ kind: "conflict", id: `text:${n++}`, base: B.slice(a0, a1).join(""), mine: m, theirs: t });
    }
    at = a1;
  }
  keep(B.slice(at).join(""));
  return { parts, conflicts: n };
}

/** The final text: each conflict as picked. */
export function resolveText(r: TextMerge, picks: Record<string, Pick>): string {
  return r.parts.map((p) => {
    if (p.kind === "same") return p.text;
    const k = picks[p.id];
    if (k !== "mine" && k !== "theirs") throw new Error(`not picked: ${p.id}`);
    return k === "mine" ? p.mine : p.theirs;
  }).join("");
}

// The person's review of an agent's branch: a chunk of its own (sagebrush-review.js), fetched when a page opens a
// review, never at a page's start.  openReview(host, { name }, panel) shows the branch's reviewed commit, file by file:
//   - each file changed, with its one run fact (run-line.ts) and, for the file opened, its diff: a notebook cell by
//     cell (cells.ts), a text file line by line (line-diff.ts), a board as counts, anything else as its sizes;
//   - a notebook's document as submitted, outputs and all, in the notebook component with no interpreter, read only
//     and not reactive, only what outputs.ts lets through (pictures whose headers say their size, and text);
//   - per file Accept, Reject or Ask for changes, with a reason, one note for the whole, and Submit (review-actions.ts:
//     its checks decide; this page shows what they say).  Nothing here runs code.
// With no name, the branches (listBranches), each opening its review.
//
// Bound to what it shows: the branch's root fid and name, the reviewed commit and its review seq, captured at each
// read and handed to Submit as they are.  A change to the branch (onBranch: a commit, a decision, a run's note, in
// this tab or another) redraws it; decisions not yet submitted and any "Replace your version" are cleared when the
// review state changes under them.
//
// One refresh at a time: at most one generation reading, diffing or mounting, and at most one
// change waiting behind it, however many arrive; a generation checks it is still the latest after every wait and
// every 50 cells, and stops if not, letting go of what it read.  A change to the review state alone (a decision, a
// run's note) reads the state again but no file.  Only the file opened is read; only one submitted notebook is
// mounted, and it is destroyed when it is closed, the file or the commit changes, or the review closes.

import { REVIEW_TEXT, listBranches, resumeAccepting, review, type PersonHost } from "../review-actions";
import { branchStoreName, onBranch } from "../branch-wake";
import { openBranchStore, type BranchStore } from "../branch-store";
import type { BranchReview, BranchRuns, FileDecision, ReviewStatus } from "../branch-rules";
import { REVIEW_DIFF, reviewLineDiff, utf8Length } from "./line-diff";
import { DIFF_TEXT, h, notebookDiff, style, textDiff } from "./diff-render";
// (the Delegate proposal view rides in this chunk: one lazy fetch for both reviews)
export { openProposal, PROPOSAL_TEXT, PROPOSAL_LIMITS, type ProposalSource, type ProposalView } from "./proposal-view";
import { CELL_LIMITS, type CellKey } from "./cells";
import { JSON_LIMITS, jsonValues } from "./json-scan";
import { filterOutputs } from "./outputs";
import { runFact } from "./run-line";
import { boardCounts } from "./board-summary";

/** What the review needs of the workspace: Workspace.reviewHost(). */
export type ReviewHost = PersonHost & { branchRuns(fid: string, name: string): Promise<BranchRuns | null> };
/** The notebook component's module (web/notebook: sagebrush-notebook.js), as the page loads it. */
export type NotebookModule = { createNotebook(root: HTMLElement, opts: Record<string, unknown>): { load(doc: unknown): void; setReadOnly(ro: boolean): void; destroy(): void } };

/** Every word the review page shows of its own; review-actions.ts's REVIEW_TEXT says the refusals. */
export const REVIEW_PAGE_TEXT = {
  ...DIFF_TEXT,
  status: { open: "Not submitted yet", review: "Waiting for your review", accepted: "Accepted", "partly-accepted": "Partly accepted", rejected: "Rejected", "changes-requested": "Changes asked for" } as Record<ReviewStatus, string>,
  ran: (t: string) => `Ran in the branch at ${t}`,
  changedSince: (t: string) => `Changed since its run at ${t}`,
  noRun: "No run recorded in the branch",
  open: "Review changes",
  replace: "Replace your version",
  submitted: "The notebook as submitted",
  tooLargeText: (a: string, b: string) => `Too large to compare line by line (${a} → ${b}).`,
  noPreview: (a: string, b: string) => `Changed: ${a} → ${b}. No preview for this kind of file.`,
  boardCounts: (added: number, removed: number, changed: number) => [[added, "added"], [removed, "removed"], [changed, "changed"]].filter(([n]) => n).map(([n, w], i) => (i === 0 ? `${n} item${n === 1 ? "" : "s"} ${w}` : `${n} ${w}`)).join(", ") || "No items changed",
  deleted: "Deleted in the branch",
  added: "Added in the branch",
  tooLargeHere: (s: string) => `Too large to show here (${s}).`,
  tooManyCellsHere: (n: number) => `Too many cells to show here (${n.toLocaleString("en-US")}).`,
  outputsTooMany: "Its outputs are too many or too large to show here.",
  notShown: "This output isn't shown here.",
  accept: "Accept",
  reject: "Reject",
  askChanges: "Ask for changes",
  reason: "Reason (optional)",
  note: "A note for the agent (optional)",
  submit: "Submit review",
  noBranches: "No branches yet.",
  gone: "This branch isn't there any more.",
  nothingYet: "Nothing has been committed for review yet.",
  tooManyFiles: (n: number) => `Too many files in the branch to review here (more than ${n.toLocaleString("en-US")} files, or more than 1 MB of file paths).`,
  tooManyChanged: (n: number) => `Too many changed files to review here (more than ${n.toLocaleString("en-US")}).`,
} as const;

/** The submitted notebook's bounds, checked before it is parsed. */
export const SUBMITTED_LIMITS = Object.freeze({ bytes: 8 * 2 ** 20, cells: CELL_LIMITS.cells });

/** How many files a review lists, at most: each side's files and their paths (UTF-16 units), from its trees, and the
 * files changed (each a row with its choices).  A branch can grow past what git_branch copied; past these, the review
 * says so and lists none.  (Not frozen: tests lower them.) */
export const REVIEW_LIST = { files: 10_000, pathBytes: 2 ** 20, changed: 2000 };

/** Tests' hook: awaited before each read the review makes (a test holds one there). */
export const REVIEW_PAGE_HOOK: { read?: (what: string) => void | Promise<void> } = {};

/** What a review holds and has done, for tests: now, and the most at once. */
export type Counters = { active: number; pending: number; reads: number; mounted: number; subscribed: number; peakActive: number; peakReads: number; peakMounted: number; generations: number; mounts: number };

export type ReviewView = { close(): void; counters(): Counters; idle(): Promise<void> };

const enc = new TextEncoder();
const fmtBytes = (n: number) => (n < 1000 ? `${n} B` : n < 1e6 ? `${(n / 1e3).toFixed(1)} KB` : `${(n / 1e6).toFixed(1)} MB`);
function fmtTime(at: number) {
  const d = new Date(at), today = new Date();
  const sameDay = d.toDateString() === today.toDateString();
  return d.toLocaleString(undefined, sameDay ? { hour: "numeric", minute: "2-digit" } : { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
}
/** The review of the branch `at.name` (or, with no name, the branches) in `panel`. `o.notebook`: the notebook
 * component's loader. */
export function openReview(host: ReviewHost, at: { name?: string }, panel: HTMLElement, o: { notebook: () => Promise<NotebookModule> }): ReviewView {
  style();
  const c: Counters = { active: 0, pending: 0, reads: 0, mounted: 0, subscribed: 0, peakActive: 0, peakReads: 0, peakMounted: 0, generations: 0, mounts: 0 };
  const peak = () => { c.peakActive = Math.max(c.peakActive, c.active); c.peakReads = Math.max(c.peakReads, c.reads); c.peakMounted = Math.max(c.peakMounted, c.mounted); };
  const root = h("div", { className: "sbrv" });
  panel.replaceChildren(root);
  let closed = false;
  let inner: ReviewView | null = null;
  const idleWaiters: (() => void)[] = [];

  if (!at.name) {
    // ---- the branches: each opens its review here
    void listBranches(host).then((all) => {
      if (closed) return;
      if (!all.length) { root.replaceChildren(h("p", { textContent: REVIEW_PAGE_TEXT.noBranches })); return; }
      root.replaceChildren(h("div", { className: "branches" }, ...all.map((b) => h("button", {
        textContent: `${b.name}${b.title ? `: ${b.title}` : ""} (${REVIEW_PAGE_TEXT.status[b.status]}, ${fmtTime(b.updated)})`,
        onclick: () => { inner = openReview(host, { name: b.name }, panel, o); },
      }))));
    });
    return { close() { closed = true; inner?.close(); }, counters: () => inner?.counters() ?? c, idle: () => inner?.idle() ?? Promise.resolve() };
  }
  const name = at.name;

  // ---- what is shown: captured at each read, handed to Submit as it is
  let fid: string | null = null, ns = "", store: BranchStore | null = null;
  let shown: { review: BranchReview; runs: Map<string, { at: number; oid: string }>; base: Map<string, string>; head: Map<string, string>; changes: { path: string; kind: "added" | "deleted" | "changed" }[] } | null = null;
  let selected: string | null = null, wantSubmitted = false;
  let decisions = new Map<string, { decision: FileDecision["decision"]; reason: string }>();
  let note = "", banner = "", overwrite = new Set<string>(), rowMsg = new Map<string, string>(), offered = new Set<string>();
  let busy = false, submitting: Promise<void> | null = null;
  // (the file opened: its diff's element and the commit it is of; the submitted notebook mounted, with its key)
  let detail: { key: string; el: HTMLElement } | null = null;
  let nb: { key: string; comp: ReturnType<NotebookModule["createNotebook"]>; el: HTMLElement } | null = null;

  // ---- the refresh slot
  let gen = 0, active = false, dirty = false;
  let off: (() => void) | null = null;
  const invalidate = () => {
    if (closed) return;
    gen++;
    if (active) { dirty = true; c.pending = 1; return; }
    kick();
  };
  const kick = () => {
    dirty = false; c.pending = 0;
    active = true; c.active++; c.generations++; peak();
    const g = gen;
    refresh(g).catch((e) => { if (g === gen && !closed) { banner = String(e?.message ?? e); paint(); } }).finally(() => {
      active = false; c.active--;
      if (dirty && !closed) kick();
      else for (const w of idleWaiters.splice(0)) w();
    });
  };
  /** One read, counted, with the tests' hold before it. */
  const read = async <T,>(what: string, p: () => Promise<T>): Promise<T> => {
    c.reads++; peak();
    try { await REVIEW_PAGE_HOOK.read?.(what); return await p(); } finally { c.reads--; }
  };

  const unmount = () => {
    if (!nb) return;
    try { nb.comp.destroy(); } catch {}
    nb.el.remove();
    nb = null; c.mounted--;
  };

  async function refresh(g: number) {
    const stale = () => closed || g !== gen;
    if (!store) {
      store = await openBranchStore(host.dbName);
      ns = await branchStoreName(host.dbName);
      if (stale()) return;
    }
    if (!fid) {
      const b = await read("branch", () => host.branchAtName(name));
      if (stale()) return;
      if (!b) { root.replaceChildren(h("p", { textContent: REVIEW_PAGE_TEXT.gone })); return; }
      fid = b.fid;
      off = onBranch(ns, fid, invalidate); c.subscribed++;
      // (an accept a closed page left: finished now, only as its intent records it; a refusal said)
      try { await resumeAccepting(host, { fid, name }); } catch (e) { banner = String((e as Error)?.message ?? e); }
      if (stale()) return;
    }
    const got = await read("review", () => host.branchReview(fid!, name));
    if (stale()) return;
    if (!got) { unmount(); shown = null; root.replaceChildren(h("p", { textContent: REVIEW_PAGE_TEXT.gone })); return; }
    const runsGot = await read("runs", () => host.branchRuns(fid!, name));
    if (stale()) return;
    const r = got.review;
    if (!r) { shown = null; root.replaceChildren(h("h3", { textContent: name }), h("p", { className: "st", textContent: `${REVIEW_PAGE_TEXT.status.open}. ${REVIEW_PAGE_TEXT.nothingYet}` })); return; }
    const runs = new Map(runsGot?.runs ?? []);
    // (the review state moved: what the person chose for the old one isn't carried over)
    if (shown && shown.review.seq !== r.seq) { decisions = new Map(); overwrite = new Set(); rowMsg = new Map(); offered = new Set(); }
    if (!shown || shown.review.head !== r.head || shown.review.base !== r.base) {
      // (a new commit: its files by blob id, from the trees alone)
      const max = { files: REVIEW_LIST.files, pathBytes: REVIEW_LIST.pathBytes };
      const base = await read("oids", () => store!.oidsAt(r.base, max));
      if (stale()) return;
      const head = base && (await read("oids", () => store!.oidsAt(r.head, max)));
      if (stale()) return;
      const tooMany = (t: string) => { detail = null; unmount(); shown = null; root.replaceChildren(h("h3", { textContent: name }), h("p", { className: "st", textContent: REVIEW_PAGE_TEXT.status[r.status] }), h("p", { textContent: t })); };
      if (!base || !head) return tooMany(REVIEW_PAGE_TEXT.tooManyFiles(REVIEW_LIST.files));
      const changes: { path: string; kind: "added" | "deleted" | "changed" }[] = [];
      for (const [p, id] of head) { const was = base.get(p); if (was === undefined) changes.push({ path: p, kind: "added" }); else if (was !== id) changes.push({ path: p, kind: "changed" }); }
      for (const p of base.keys()) if (!head.has(p)) changes.push({ path: p, kind: "deleted" });
      if (changes.length > REVIEW_LIST.changed) return tooMany(REVIEW_PAGE_TEXT.tooManyChanged(REVIEW_LIST.changed));
      changes.sort((x, y) => (x.path < y.path ? -1 : x.path > y.path ? 1 : 0));
      shown = { review: r, runs, base, head, changes };
      if (selected && !changes.some((x) => x.path === selected)) selected = null;
      // (what was shown for the old commit goes before anything of the new one is painted)
      detail = null; unmount();
    } else shown = { ...shown, review: r, runs };
    paint();
    // (the file opened: read and diffed only if it's not already shown for this commit)
    const key = selected ? `${r.head}\n${selected}` : "";
    if (!selected) { detail = null; unmount(); return; }
    if (!detail || detail.key !== key) {
      unmount();
      const el = await fileDetail(selected, r, stale);
      if (!el || stale()) return;
      detail = { key, el };
      paint();
    }
    if (wantSubmitted && (!nb || nb.key !== key)) { unmount(); await mountSubmitted(selected, r, key, stale); }
    else if (!wantSubmitted) unmount();
  }

  // ---- one file's diff
  async function fileDetail(p: string, r: BranchReview, stale: () => boolean): Promise<HTMLElement | null> {
    const ch = shown!.changes.find((x) => x.path === p)!;
    const box = h("div", { className: "detail" });
    if (ch.kind === "deleted") { box.append(h("p", { textContent: REVIEW_PAGE_TEXT.deleted })); return box; }
    const kind = (await read("kind", () => store!.fullKind(r.head, p)))?.kind ?? "file";
    if (stale()) return null;
    const a = ch.kind === "added" ? new Uint8Array() : await read("blob", () => store!.blobAt(r.base, p).then((b) => b ?? new Uint8Array()));
    if (stale()) return null;
    const b = (await read("blob", () => store!.blobAt(r.head, p))) ?? new Uint8Array();
    if (stale()) return null;
    if (ch.kind === "added") box.append(h("p", { className: "fold", textContent: REVIEW_PAGE_TEXT.added }));
    const sizes = () => [fmtBytes(a.length), fmtBytes(b.length)] as const;
    if (kind === "notebook" || kind === "board") {
      // (each side's canonical JSON: bounded by its bytes and its values before it is parsed)
      if (a.length > REVIEW_DIFF.sideBytes || b.length > REVIEW_DIFF.sideBytes || jsonValues(a) > JSON_LIMITS.side || jsonValues(b) > JSON_LIMITS.side) { box.append(h("p", { textContent: REVIEW_PAGE_TEXT.tooLargeText(...sizes()) })); return box; }
      const dec = new TextDecoder();
      const pa = a.length ? JSON.parse(dec.decode(a)) : null, pb = JSON.parse(dec.decode(b));
      if (kind === "board") {
        const n = boardCounts(pa, pb);
        box.append(h("p", { textContent: n ? REVIEW_PAGE_TEXT.boardCounts(n.added, n.removed, n.changed) : REVIEW_PAGE_TEXT.noPreview(...sizes()) }));
        return box;
      }
      const cellsOf = (d: any): CellKey[] => (Array.isArray(d?.cells) ? d.cells : []).map((x: any) => ({ type: String(x?.type ?? "code"), code: String(x?.code ?? "") }));
      await notebookDiff(box, cellsOf(pa), cellsOf(pb), stale);
      if (stale()) return null;
      const sub = h("details", {}, h("summary", { textContent: REVIEW_PAGE_TEXT.submitted }));
      sub.open = wantSubmitted;
      sub.addEventListener("toggle", () => { if (sub.open === wantSubmitted) return; wantSubmitted = sub.open; if (!wantSubmitted) unmount(); invalidate(); });
      box.append(sub);
      return box;
    }
    // (a data file: text if both sides decode as UTF-8; bounded by its bytes before either is decoded)
    if (a.length > REVIEW_DIFF.sideBytes || b.length > REVIEW_DIFF.sideBytes) { box.append(h("p", { textContent: REVIEW_PAGE_TEXT.tooLargeText(...sizes()) })); return box; }
    let ta: string, tb: string;
    try { const d = new TextDecoder("utf-8", { fatal: true }); ta = d.decode(a); tb = d.decode(b); }
    catch {
      const why = h("p", { textContent: REVIEW_PAGE_TEXT.noPreview(...sizes()) });
      why.title = `${shown!.base.get(p) ?? "none"} → ${shown!.head.get(p)}`;
      box.append(why);
      return box;
    }
    const d = reviewLineDiff(ta, tb);
    const pre = d.ok ? textDiff(d.a, d.b, d.segs) : null;
    box.append(pre ?? h("p", { textContent: REVIEW_PAGE_TEXT.tooLargeText(...sizes()) }));
    return box;
  }

  // ---- the notebook as submitted
  async function mountSubmitted(p: string, r: BranchReview, key: string, stale: () => boolean) {
    const slot = detail?.el.querySelector("details");
    if (!slot) return;
    const say = (t: string) => { slot.querySelector(".why")?.remove(); slot.append(h("p", { className: "why", textContent: t })); };
    let full = await read("full", () => store!.fullAt(r.head, p));
    if (stale() || !full) return;
    if (full.bytes.length > SUBMITTED_LIMITS.bytes || jsonValues(full.bytes) > JSON_LIMITS.full) return say(REVIEW_PAGE_TEXT.tooLargeHere(fmtBytes(full.bytes.length)));
    let text: string | null = new TextDecoder().decode(full.bytes);
    full = null;
    const doc = JSON.parse(text);
    text = null;
    const n = Array.isArray(doc?.cells) ? doc.cells.length : 0;
    if (n > SUBMITTED_LIMITS.cells) return say(REVIEW_PAGE_TEXT.tooManyCellsHere(n));
    // (what may be shown, decided on this one document, in place, before the component sees it)
    const shownOut = filterOutputs(doc, REVIEW_PAGE_TEXT.notShown);
    if ("refused" in shownOut) return say(REVIEW_PAGE_TEXT.outputsTooMany);
    const mod = await read("notebook", () => o.notebook());
    if (stale()) return;
    const el = h("div");
    slot.append(el);
    const comp = mod.createNotebook(el, { kernel: null, readOnly: true, reactive: false, remotePictures: "click" });
    nb = { key, comp, el }; c.mounted++; c.mounts++; peak();
    comp.load(doc);
    comp.setReadOnly(true);
    for (const btn of el.querySelectorAll<HTMLButtonElement>("button")) btn.disabled = true;
  }

  // ---- the page
  function paint() {
    if (closed || !shown) return;
    const r = shown.review;
    const deciding = r.status === "review" && !r.pending && !r.accepting;
    const rows = shown.changes.map((ch) => {
      const fact = runFact(shown!.runs.get("/" + ch.path), shown!.head.get(ch.path));
      const factText = fact.state === "none" ? REVIEW_PAGE_TEXT.noRun : fact.state === "ran" ? REVIEW_PAGE_TEXT.ran(fmtTime(fact.at)) : REVIEW_PAGE_TEXT.changedSince(fmtTime(fact.at));
      const p = "/" + ch.path;
      const pathBtn = h("button", { className: "path", textContent: p + (ch.kind === "deleted" ? `: ${REVIEW_PAGE_TEXT.deleted}` : ""), onclick: () => { selected = selected === ch.path ? null : ch.path; wantSubmitted = false; detail = null; unmount(); paint(); invalidate(); } });
      const kids: (Node | null)[] = [pathBtn, h("div", { className: "run", textContent: factText })];
      const was = r.files?.[p];
      if (deciding) {
        const cur = decisions.get(p);
        const pick = (d: FileDecision["decision"], label: string) => {
          const inp = h("input", { type: "radio", name: "d" + p, checked: cur?.decision === d, onchange: () => { decisions.set(p, { decision: d, reason: decisions.get(p)?.reason ?? "" }); } });
          return h("label", {}, inp, " " + label);
        };
        const reason = h("input", { type: "text", placeholder: REVIEW_PAGE_TEXT.reason, value: cur?.reason ?? "", oninput: () => { const x = decisions.get(p); if (x) x.reason = reason.value; } });
        kids.push(h("div", { className: "dec" }, pick("accepted", REVIEW_PAGE_TEXT.accept), pick("rejected", REVIEW_PAGE_TEXT.reject), pick("changes", REVIEW_PAGE_TEXT.askChanges), reason));
      } else if (was) kids.push(h("div", { className: "run", textContent: `${was.decision === "accepted" ? REVIEW_PAGE_TEXT.accept : was.decision === "rejected" ? REVIEW_PAGE_TEXT.reject : REVIEW_PAGE_TEXT.askChanges}${was.reason ? `: ${was.reason}` : ""}` }));
      const m = rowMsg.get(p);
      if (m) {
        kids.push(h("div", { className: "msg", textContent: m }));
        if (offered.has(p)) kids.push(h("button", { textContent: REVIEW_PAGE_TEXT.replace, onclick: () => { overwrite.add(p); startSubmit(); } }));
      }
      // (a diff only under exactly the commit and file it was made for: never another's while its own is read)
      if (selected === ch.path && detail && detail.key === `${r.head}\n${ch.path}`) kids.push(detail.el);
      return h("div", { className: "file" }, ...kids);
    });
    const parts: (Node | null)[] = [
      h("h3", { textContent: r.title ? `${name}: ${r.title}` : name }),
      h("p", { className: "st", textContent: REVIEW_PAGE_TEXT.status[r.status] + (r.note && !deciding ? `. ${r.note}` : "") }),
      banner ? h("div", { className: "msg", textContent: banner }) : null,
      ...rows,
    ];
    if (deciding) {
      const ta = h("textarea", { placeholder: REVIEW_PAGE_TEXT.note, value: note, oninput: () => { note = ta.value; } });
      parts.push(ta, h("button", { textContent: REVIEW_PAGE_TEXT.submit, disabled: busy, onclick: startSubmit }));
    }
    root.replaceChildren(...parts.filter((x): x is Node => !!x));
  }

  function startSubmit() { if (!submitting) submitting = submit().finally(() => { submitting = null; }); }
  async function submit() {
    if (busy || !shown || !fid) return;
    const r = shown.review;
    busy = true; banner = ""; rowMsg = new Map(); paint();
    const files: Record<string, { decision: FileDecision["decision"]; reason?: string }> = {};
    for (const [p, d] of decisions) files[p] = { decision: d.decision, ...(d.reason.trim() ? { reason: d.reason.trim() } : {}) };
    try {
      await review(host, { fid, name, head: r.head, seq: r.reviewSeq ?? -1 }, { files, ...(note.trim() ? { note: note.trim() } : {}), overwrite: [...overwrite] });
      decisions = new Map(); overwrite = new Set(); offered = new Set(); note = "";
    } catch (e) {
      const m = String((e as Error)?.message ?? e);
      const p = Object.keys(files).find((x) => m === REVIEW_TEXT.mainChanged(x));
      if (p) { rowMsg.set(p, m); offered.add(p); }
      else banner = m;
    } finally {
      busy = false;
      paint();
      invalidate();
    }
  }

  invalidate();
  return {
    close() {
      if (closed) return;
      closed = true; gen++;
      off?.(); off = null; if (c.subscribed) c.subscribed--;
      unmount();
      detail = null; shown = null;
      panel.replaceChildren();
      for (const w of idleWaiters.splice(0)) w();
    },
    counters: () => ({ ...c }),
    // (no refresh under way and no Submit: tests wait on this, never on time)
    async idle() {
      for (;;) {
        if (closed) return;
        if (submitting) { await submitting; continue; }
        if (active) { await new Promise<void>((r) => idleWaiters.push(r)); continue; }
        return;
      }
    },
  };
}

## 3. The workspace verbs

**Server to page:** `{"id":"s<n>","method":"workspace.<verb>","params":{…}}`.
- **Paths** are checked on both sides against `schema.json`'s limits (`maxPath`, `maxDepth`, `maxName`). Neither side accepts NUL, lone surrogates, or NaN/Infinity in any value.
- **Answers** over `maxList` entries or `maxHistory` versions are a protocol error on the server's side.
- The verbs and their parameter schemas are in `web/workspace/schema.json` (written by `web/workspace/verbs.ts`): list, stat, read, write, create, mkdir, rename, duplicate, remove, restore, history, version.
- `sagebrush-mcp` makes its tools from that file. Tool names use underscores (`workspace_list`), because model APIs refuse dots.

**Contents on the wire:**
- a document (notebook or board) as `{json}`;
- a data file as `{text}` (UTF-8) or `{base64}`.

**Results:**
- list: `{entries, more?, cursor?}`, at most 10,000 entries per answer;
- stat and the changing verbs: `{entry}`;
- read: `{entry, rev, content}`;
- write: `{entry, rev}`;
- history: `{versions, more?, cursor?}`, at most 100 per answer;
- version: `{content}`.

**Errors:** `{code:-32000, message, data:{code, message, current?, retryAfterMs?}}`, where `data.code` is the workspace's: `invalid`, `exists`, `missing`, `conflict`, `limit` or `storage`.
- For a conflict, `current` is `{entry, rev, content}`.
- `sagebrush-mcp` returns errors to the agent as `isError` tool results.

**What the page enforces:**
- the grant: folders, write, run;
- the schema;
- the limits:
  - 8 MiB of content per call, refused with its size, never cut;
  - 8 requests in flight;
  - 100 per second, burst 200 (`limit` with `retryAfterMs`).

**What's never offered:** dropping versions, emptying Trash, forgetting entries. Only a person does those, in the page's own UI (§2.5, §8.2).

**Every change** is credited to `agent:<name>` in the operation log and in versions, and the page shows it ("Claude Code renamed …").

**Running code** (may run code, §8.3) comes later as `board.run` and `notebook.run`. They run in the page's runner, credited and logged, and only under a grant that allows it.

The agent tells the page what happens, as notifications: the chat turn's events, `task_status`, and `proposal` when a round of work is ready.

**Events (`task.event {task, seq, event}`):**
- the chat turn events (as `agent-chat/events.ts`), and:
- `{type: "task_status", status, reason?}`;
- `{type: "proposal", round, base, commit, files}`, with files as in `tasks.diff`;
- **M2:**
  - `{type: "question", qid, revision, text, blocking, choices?}`;
  - `{type: "question_withdrawn", qid, revision}`;
  - `{type: "question_answered", qid, revision, answer_id, current}`.

(From design/workspace-agent-protocol.md §6.1.)
